const l={agriculture:"Food and Agriculture","agriculture and food":"Food and Agriculture","agriculture and agro-processing":"Food and Agriculture","agro-processing":"Food and Agriculture","buildings and construction":"Construction","business to business":"Business to Business","construction and buildings":"Construction","digital/traceability technology":"Digital/Traceability Technology","electronics and ict":"Electronics and ICT","finplast-prim srl":"FINPLAST-PRIM SRL","food and agriculture":"Food and Agriculture","food and beverage":"Food and Agriculture","food and nutrients":"Food and Agriculture",horesca:"HORESCA",ict:"ICT","it services":"IT Services","products-as-a-service":"Products-as-a-Service","recycle (r8)":"Recycle (R8)","recover (r9)":"Recover (R9)","reduce (r2)":"Reduce (R2)","refuse (r0)":"Refuse (R0)","refurbish (r5)":"Refurbish (R5)","remanufacture (r6)":"Remanufacture (R6)","repair (r4)":"Repair (R4)","repurpose (r7)":"Repurpose (R7)","rethink (r1)":"Rethink (R1)","reuse (r3)":"Reuse (R3)",'s.r.l. "refurb"':'S.R.L. "REFURB"',"textiles and fashion":"Textiles","unfloria srl":"Unfloria SRL","uniplast srl":"UNIPLAST SRL"},u=new Set(["and","or","of","the","to","for","in","with"]);function d(a,i){var c,s;const r=Number(((c=a.match(/\(R(\d+)\)/i))==null?void 0:c[1])??1/0),n=Number(((s=i.match(/\(R(\d+)\)/i))==null?void 0:s[1])??1/0);return r-n||a.localeCompare(i)}function p(a){return Array.isArray(a)?a.map(i=>String(i).trim()).filter(Boolean):typeof a=="string"?a.split(/\s+\/\s+|[;,]/).map(i=>i.trim()).filter(Boolean):[]}function m(a){return a.toLowerCase().split(/\s+/).map((i,r)=>r>0&&u.has(i)?i:i.split("-").map(n=>n.charAt(0).toUpperCase()+n.slice(1)).join("-")).join(" ")}function g(a){const i=String(a).trim().replace(/\s+/g," "),r=l[i.toLowerCase()];return r||m(i)}function t(a){return[...new Set(p(a).map(g))]}function e(a){const i=t(a.country),r=t(a.sector),n=t(a.rStrategies);return{caseLink:"",image:"",imageAlt:"",rStrategyDescription:"",...a,country:i.join(", "),countries:i,countryDisplay:i.join(", "),sector:r.join(", "),sectors:r,sectorDisplay:r.join(", "),rStrategies:n,filterValues:{countries:i,sectors:r,rStrategies:n}}}const o=[e({id:"case-001",slug:"uniplast-srl",companyName:{en:"UNIPLAST SRL",uk:"",ro:"",hy:""},country:"Republic of Moldova",sector:["Plastics"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Plastic waste is reprocessed into granules that can substitute virgin raw materials in new manufacturing processes; recovered high-density polyethylene (HDPE) and low-density polyethylene (LDPE) are directed into UNIPLAST's own production line to manufacture pipes and fittings for irrigation and low-pressure networks.",uk:"Пластикові відходи переробляються на гранули, які можуть замінювати первинну сировину в нових виробничих процесах; відновлені поліетилен високої щільності (HDPE) та поліетилен низької щільності (LDPE) спрямовуються на власну виробничу лінію компанії UNIPLAST для виготовлення труб і фітингів для зрошення та мереж низького тиску.",ro:"Deșeurile de plastic sunt reprocesate în granule care pot înlocui materii prime virgine în noile procese de fabricație; polietilena de înaltă densitate recuperată (HDPE) și polietilena de joasă densitate (LDPE) sunt direcționate către linia proprie de producție a UNIPLAST pentru fabricarea țevilor și fitingurilor pentru irigații și rețele de joasă presiune.",hy:"Պլաստիկ թափոնները վերամշակվում են հատիկների տեսքով, որոնք կարող են փոխարինել կուսական հումքը նոր արտադրական գործընթացներում. վերականգնված բարձր խտության պոլիէթիլենը (HDPE) և ցածր խտության պոլիէթիլենը (LDPE) ուղղվում են UNIPLAST-ի սեփական արտադրական գիծ՝ ոռոգման և ցածր ճնշման ցանցերի համար խողովակներ և կցամասեր արտադրելու համար։"},summary:{en:"UNIPLAST SRL recovers polyethylene waste and reprocesses it into secondary raw material used to manufacture its own pipes for irrigation and low-pressure water networks.",uk:"UNIPLAST SRL збирає відходи поліетилену та переробляє їх на вторинну сировину, яка використовується для виробництва власних труб для зрошення та низьконапірних водопровідних мереж.",ro:"UNIPLAST SRL recuperează deșeurile de polietilenă și le reprocesează în materie primă secundară folosită la fabricarea propriilor conducte pentru irigații și rețele de apă de joasă presiune.",hy:"UNIPLAST SRL-ը վերականգնում է պոլիէթիլենային թափոնները և վերամշակում դրանք երկրորդային հումքի վերածելով, որն օգտագործվում է ոռոգման և ցածր ճնշման ջրի ցանցերի համար սեփական խողովակների արտադրության համար։"},description:{en:"UNIPLAST SRL operates an integrated circular manufacturing model in which recovered polyethylene waste is converted into secondary raw material and used within the company's own production process. Based in Chișinău, the company manufactures and distributes plastic pipes, fittings and related equipment for water supply, sewerage, irrigation, heating, gas and other technical networks. It also holds an environmental authorisation for plastic-waste management and recovery operations. || Unlike recyclers that sell recovered plastic as granulate, UNIPLAST retains more of the material's value by incorporating the secondary polyethylene directly into finished products. Collected high-density polyethylene (HDPE) and low-density polyethylene (LDPE) waste enters the company's authorised recovery process, where it is prepared and reprocessed into secondary raw material. This material is subsequently used to manufacture pipes for irrigation systems and low-pressure installations. Virgin-grade polyethylene continues to be used for applications subject to stricter technical and safety requirements, including potable-water networks. || The model connects waste recovery with an established market for agricultural and infrastructure products. Its value proposition is therefore based on transforming recovered plastic into locally manufactured pipes with a new service life, while reducing reliance on virgin polymers in technically suitable applications. According to a United Nations Development Programme (UNDP) study on plastic-waste management in Moldova, UNIPLAST reported collecting and recovering approximately 2,400 tonnes of plastic waste annually. This figure should be reconfirmed before final publication because it reflects the study's reporting period. || The main environmental benefits are the diversion of recoverable polyethylene from disposal and the substitution of part of the virgin material input. Economically, the integrated model reduces dependence on externally supplied raw materials and captures more value internally by selling finished products rather than secondary granulate alone. EU and United Nations Development Programme (UNDP) support awarded in 2026 will contribute to modernising or expanding the company's recycling capacity. The principal lesson is that conventional manufacturers can adopt circularity by integrating authorised waste recovery with existing production lines and clearly separating recycled-material applications according to technical requirements.",uk:"UNIPLAST SRL застосовує інтегровану циркулярну виробничу модель, за якої відновлені поліетиленові відходи перетворюються на вторинну сировину та використовуються у власному виробничому процесі компанії. Підприємство із Кишинева виробляє та постачає пластикові труби, фітинги й супутнє обладнання для систем водопостачання, каналізації, зрошення, опалення, газопостачання та інших інженерних мереж. Компанія також має екологічний дозвіл на управління пластиковими відходами та операції з їхнього відновлення. || На відміну від переробників, які продають відновлений пластик у вигляді грануляту, UNIPLAST зберігає більшу цінність матеріалу, інтегруючи вторинний поліетилен безпосередньо у готову продукцію. Зібрані відходи поліетилену високої (HDPE) та низької щільності (LDPE) потрапляють на авторизовану лінію відновлення, де вони готуються та переробляються на вторинну сировину. Надалі цей матеріал використовується для виробництва труб для систем зрошення та установок низького тиску. Первинний поліетилен продовжує використовуватися для сфер із суворішими технічними вимогами та стандартами безпеки, зокрема для мереж питного водопостачання. || Модель пов’язує переробку відходів зі сформованим ринком сільськогосподарської та інфраструктурної продукції. Таким чином, його ціннісна пропозиція базується на перетворенні відновленого пластику в труби місцевого виробництва з новим терміном служби, одночасно зменшуючи залежність від первинних полімерів у технічно прийнятних застосуваннях. Згідно з дослідженням Програми розвитку Організації Об’єднаних Націй (ПРООН) щодо управління пластиковими відходами в Молдові, UNIPLAST повідомила про збирання та відновлення приблизно 2400 тонн пластикових відходів щорічно. Цю цифру слід підтвердити перед остаточною публікацією, оскільки вона відображає звітний період дослідження. || Основними екологічними перевагами є запобігання захороненню поліетилену, придатного до відновлення, та часткове заміщення первинної сировини. З економічного погляду інтегрована модель зменшує залежність від зовнішніх постачальників сировини та утримує більшу цінність усередині компанії завдяки продажу готової продукції, а не лише вторинного грануляту. Підтримка від ЄС та Програми розвитку ООН (ПРООН), отримана у 2026 році, сприятиме модернізації або розширенню потужностей компанії з вторинного перероблення. Головний висновок полягає в тому, що традиційні виробники можуть впроваджувати принципи циркулярної економіки шляхом інтеграції авторизованого відновлення відходів у наявні виробничі лінії та чіткого розмежування сфер застосування вторинної сировини відповідно до технічних вимог.",ro:"UNIPLAST SRL operează un model de fabricație circular integrat în care deșeurile de polietilenă recuperate sunt transformate în materie primă secundară și utilizate în procesul de producție propriu al companiei. Cu sediul în Chișinău, compania produce și distribuie țevi din plastic, fitinguri și echipamente aferente pentru alimentarea cu apă, canalizare, irigații, încălzire, gaze și alte rețele tehnice. De asemenea, deține o autorizație de mediu pentru operațiuni de gestionare și valorificare a deșeurilor de plastic. || Spre deosebire de reciclatorii care vând plastic recuperat ca granulat, UNIPLAST păstrează mai mult din valoarea materialului prin încorporarea polietilenei secundare direct în produsele finite. Deșeurile colectate din polietilenă de înaltă densitate (HDPE) și polietilenă de joasă densitate (LDPE) intră în procesul de recuperare autorizat al companiei, unde sunt pregătite și reprocesate în materie primă secundară. Acest material este utilizat ulterior la fabricarea conductelor pentru sisteme de irigare și instalații de joasă presiune. Polietilena virgină continuă să fie utilizată pentru aplicații supuse unor cerințe tehnice și de siguranță mai stricte, inclusiv rețele de apă potabilă. || Modelul conectează recuperarea deșeurilor cu o piață stabilită pentru produse agricole și de infrastructură. Prin urmare, propunerea sa de valoare se bazează pe transformarea plasticului recuperat în țevi fabricate local cu o nouă durată de viață, reducând în același timp dependența de polimerii virgini în aplicații adecvate din punct de vedere tehnic. Potrivit unui studiu al Programului Națiunilor Unite pentru Dezvoltare (PNUD) privind gestionarea deșeurilor de plastic în Moldova, UNIPLAST a raportat că colectează și recuperează aproximativ 2.400 de tone de deșeuri de plastic anual. Această cifră ar trebui reconfirmată înainte de publicarea finală, deoarece reflectă perioada de raportare a studiului. || Principalele beneficii de mediu sunt deturnarea polietilenei recuperabile de la eliminare și înlocuirea unei părți din aportul de material virgin. Din punct de vedere economic, modelul integrat reduce dependența de materiile prime furnizate extern și captează mai multă valoare pe plan intern prin vânzarea produselor finite, mai degrabă decât a granulatelor secundare. Sprijinul acordat de UE și Programul Națiunilor Unite pentru Dezvoltare (PNUD) în 2026 va contribui la modernizarea sau extinderea capacității de reciclare a companiei. Principala lecție este că producătorii convenționali pot adopta circularitatea integrând recuperarea autorizată a deșeurilor cu liniile de producție existente și separând în mod clar aplicațiile de materiale reciclate în funcție de cerințele tehnice.",hy:"UNIPLAST SRL-ն օգտագործում է ինտեգրված շրջանաձև արտադրության մոդել, որտեղ վերականգնված պոլիէթիլենային թափոնները վերածվում են երկրորդական հումքի և օգտագործվում են ընկերության սեփական արտադրության գործընթացում: Հիմնված լինելով Քիշնևում, ընկերությունը արտադրում և տարածում է պլաստիկ խողովակներ, կցամասեր և հարակից սարքավորումներ ջրամատակարարման, կոյուղու, ոռոգման, ջեռուցման, գազի և այլ տեխնիկական ցանցերի համար: Այն նաև ունի բնապահպանական թույլտվություն պլաստիկ թափոնների կառավարման և վերականգնման աշխատանքների համար։ || Ի տարբերություն վերամշակողների, որոնք վաճառում են վերականգնված պլաստիկը որպես հատիկավոր, UNIPLAST-ը պահպանում է նյութի արժեքի մեծ մասը՝ երկրորդական պոլիէթիլենն անմիջապես պատրաստի արտադրանքի մեջ ներառելով: Հավաքված բարձր խտության պոլիէթիլենային (HDPE) և ցածր խտության պոլիէթիլենային (LDPE) թափոնները մտնում են ընկերության թույլատրված վերականգնման գործընթաց, որտեղ այն պատրաստվում և վերամշակվում է երկրորդական հումքի: Այս նյութը հետագայում օգտագործվում է ոռոգման համակարգերի և ցածր ճնշման կայանքների համար խողովակներ արտադրելու համար: Վիրջին տեսակի պոլիէթիլենը շարունակում է օգտագործվել այնպիսի ծրագրերի համար, որոնք ենթակա են տեխնիկական և անվտանգության ավելի խիստ պահանջների, ներառյալ խմելու ջրի ցանցերը։ || Մոդելը կապում է թափոնների վերականգնումը գյուղատնտեսական և ենթակառուցվածքային ապրանքների համար ստեղծված շուկայի հետ: Հետևաբար, դրա արժեքային առաջարկը հիմնված է վերականգնված պլաստիկը տեղական արտադրության խողովակների վերածելու վրա՝ նոր ծառայության ժամկետով, միաժամանակ նվազեցնելով կույս պոլիմերներից կախվածությունը տեխնիկապես հարմար կիրառություններում: Համաձայն ՄԱԿ-ի Զարգացման ծրագրի (ՄԱԶԾ) Մոլդովայում պլաստիկ թափոնների կառավարման վերաբերյալ ուսումնասիրության՝ UNIPLAST-ը հաղորդել է տարեկան մոտավորապես 2400 տոննա պլաստիկ թափոնների հավաքման և վերականգնման մասին: Այս թիվը պետք է վերահաստատվի մինչև վերջնական հրապարակումը, քանի որ այն արտացոլում է հետազոտության հաշվետու ժամանակաշրջանը։ || Բնապահպանական հիմնական առավելություններն են վերականգնվող պոլիէթիլենի հեռացումը հեռացումից և կուսական նյութի մի մասի փոխարինումը: Տնտեսապես, ինտեգրված մոդելը նվազեցնում է կախվածությունը դրսից մատակարարվող հումքից և ավելի մեծ արժեք է գրավում ներսում՝ վաճառելով պատրաստի արտադրանքը, այլ ոչ միայն երկրորդական հատիկավորը: ԵՄ-ի և ՄԱԿ-ի Զարգացման ծրագրի (ՄԱԶԾ) աջակցությունը, որը տրվել է 2026 թվականին, կնպաստի ընկերության վերամշակման կարողությունների արդիականացմանը կամ ընդլայնմանը: Հիմնական դասն այն է, որ սովորական արտադրողները կարող են կիրառել շրջանաձևություն՝ ինտեգրելով թույլատրված թափոնների վերականգնումը գոյություն ունեցող արտադրական գծերի հետ և հստակ տարանջատելով վերամշակված նյութերի կիրառությունները՝ համաձայն տեխնիկական պահանջների։"},caseLink:"https://uniplast.md/",image:"/images/cases/moldova/uniplast-srl.jpg",imageAlt:{en:"UNIPLAST SRL case image",uk:"Зображення корпусу UNIPLAST SRL",ro:"Imagine caz UNIPLAST SRL",hy:"UNIPLAST SRL պատյան պատկեր"}}),e({id:"case-002",slug:"finplast-prim-srl",companyName:{en:"FINPLAST-PRIM SRL",uk:"",ro:"",hy:""},country:"Republic of Moldova",sector:["Plastics"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Plastic waste is reprocessed into granules that can substitute virgin raw materials in new manufacturing processes; other collected packaging materials are recovered and directed into appropriate recycling streams.",uk:"Пластикові відходи переробляють на гранули, які можуть замінювати первинну сировину в нових виробничих процесах; інші зібрані пакувальні матеріали відновлюють і спрямовують у відповідні потоки перероблення.",ro:"Deșeurile de plastic sunt reprocesate în granule care pot înlocui materii prime virgine în noile procese de fabricație; alte materiale de ambalare colectate sunt recuperate și direcționate în fluxuri adecvate de reciclare.",hy:"Պլաստիկ թափոնները վերամշակվում են հատիկների տեսքով, որոնք կարող են փոխարինել կուսական հումքը նոր արտադրական գործընթացներում. հավաքված այլ փաթեթավորման նյութերը վերականգնվում և ուղղվում են համապատասխան վերամշակման հոսքեր։"},summary:{en:"FINPLAST-PRIM SRL collects, sorts and recycles plastic and other packaging waste into a differentiated range of recycled plastic granules sold to manufacturers.",uk:"FINPLAST-PRIM SRL збирає, сортує та переробляє пластик та інші відходи упаковки в диференційований асортимент перероблених пластикових гранул, які продаються виробникам.",ro:"FINPLAST-PRIM SRL colectează, sortează și reciclează plastic și alte deșeuri de ambalaje într-o gamă diferențiată de granule din plastic reciclat vândute producătorilor.",hy:"FINPLAST-PRIM SRL-ը հավաքում, տեսակավորում և վերամշակում է պլաստմասե և այլ փաթեթավորման թափոնները վերամշակված պլաստիկ հատիկների տարբերակված տեսականիով, որոնք վաճառվում են արտադրողներին։"},description:{en:"FINPLAST-PRIM SRL operates a circular business model based on converting plastic waste into commercially valuable secondary raw materials. Based in Bălți, northern Moldova, the company is a producer and supplier of recycled plastic granules and an authorised operator for the collection, sorting and recycling of packaging and other recyclable waste. || The model connects two customer groups within the plastics value chain. On the supply side, FINPLAST-PRIM provides waste-management services to companies that need their plastic and packaging waste collected and processed. On the demand side, it supplies manufacturers with recycled high-density polyethylene (HDPE), low-density polyethylene (LDPE), polypropylene (PP), polystyrene (PS) and polyethylene terephthalate (PET/PETE) granules that can substitute part of their virgin raw-material input. Value is therefore created both by managing waste streams and by converting recovered plastics into marketable feedstock for new production. || Collected plastic film and rigid plastics are segregated by polymer type and quality, cleaned, shredded and reprocessed into different grades of recycled granules. The company's commercial portfolio comprises 17 recycled-plastic products, including four high-density polyethylene (HDPE), six low-density polyethylene (LDPE), five polypropylene (PP), one polystyrene (PS) and one polyethylene terephthalate (PET/PETE) variant. This differentiated portfolio enables FINPLAST-PRIM to respond to varying manufacturing requirements rather than selling recovered plastic as an undifferentiated waste material. || The company also manages paper and cardboard, wood, glass and metal packaging, offering business clients a consolidated solution for several recyclable waste streams. Its website reports processed quantities of 2,640 tonnes of plastic, 8,280 tonnes of paper and cardboard, 620 tonnes of wood and 560 tonnes of glass, although the reporting period should be confirmed. || The model closes material loops, diverts recyclable waste from disposal and strengthens Moldova's domestic market for secondary raw materials. EU and United Nations Development Programme (UNDP) support awarded in 2026 will help modernise or expand its recycling capacity. The principal lesson is that recycling generates greater circular and economic value when recovered waste is converted into differentiated, market-ready raw materials linked to identifiable manufacturing demand.",uk:"FINPLAST-PRIM SRL працює за циркулярною бізнес-моделлю, що ґрунтується на перетворенні пластикових відходів на комерційно цінну вторинну сировину. Компанія розташована в Бєльцях на півночі Молдови, виробляє та постачає гранули з вторинного пластику, а також має дозвіл на збирання, сортування та перероблення паковання й інших відходів, придатних до перероблення. || Модель поєднує дві групи клієнтів у межах ланцюга створення вартості пластику. З боку постачання FINPLAST-PRIM надає послуги з управління відходами компаніям, яким потрібно збирати та обробляти пластикові й пакувальні відходи. З боку попиту компанія постачає виробникам гранули з вторинного поліетилену високої щільності (HDPE), поліетилену низької щільності (LDPE), поліпропілену (PP), полістиролу (PS) та поліетилентерефталату (PET/PETE), які можуть замінювати частину первинної сировини у виробництві. Тож цінність створюється як завдяки управлінню потоками відходів, так і завдяки перетворенню зібраного пластику на придатну для продажу сировину для нового виробництва. || Зібрану поліетиленову плівку та жорсткий пластик сортують за типом полімеру та якістю, очищають, подрібнюють і переробляють на різні види гранул із вторинного пластику. Комерційний асортимент компанії охоплює 17 видів продукції з вторинного пластику, зокрема чотири види поліетилену високої щільності (HDPE), шість – поліетилену низької щільності (LDPE), п’ять – поліпропілену (PP), один – полістиролу (PS) та один – поліетилентерефталату (PET/PETE). Такий диференційований асортимент дає FINPLAST-PRIM змогу задовольняти різні потреби виробників, а не продавати зібраний пластик як несортовані відходи. || Компанія також управляє папером і картоном, дерев’яною, скляною та металевою тарою, пропонуючи бізнес-клієнтам консолідоване рішення для кількох потоків відходів, які можна переробити. На його веб-сайті повідомляється про оброблену кількість 2640 тонн пластику, 8280 тонн паперу та картону, 620 тонн деревини та 560 тонн скла, хоча звітний період має бути підтверджений. || Ця модель замикає матеріальні цикли, запобігає потраплянню придатних до перероблення відходів на сміттєзвалища та зміцнює внутрішній ринок вторинної сировини Молдови. Підтримка з боку ЄС і Програми розвитку Організації Об’єднаних Націй (ПРООН), надана у 2026 році, допоможе модернізувати або розширити потужності з перероблення. Головний висновок полягає в тому, що перероблення створює більшу циркулярну та економічну цінність, коли зібрані відходи перетворюють на диференційовану, готову до використання вторинну сировину, пов’язану з конкретним попитом з боку виробників.",ro:"FINPLAST-PRIM SRL operează un model de afaceri circular bazat pe transformarea deșeurilor de plastic în materii prime secundare valoroase din punct de vedere comercial. Cu sediul în Bălți, nordul Moldovei, compania este producător și furnizor de granule de plastic reciclat și operator autorizat pentru colectarea, sortarea și reciclarea ambalajelor și a altor deșeuri reciclabile. || Modelul conectează două grupuri de clienți în cadrul lanțului valoric al materialelor plastice. În ceea ce privește oferta, FINPLAST-PRIM oferă servicii de gestionare a deșeurilor companiilor care au nevoie de colectarea și procesarea deșeurilor din plastic și ambalaje. În ceea ce privește cererea, furnizează producătorilor granule de polietilenă de înaltă densitate (HDPE), polietilenă de joasă densitate (LDPE), polipropilenă (PP), polistiren (PS) și polietilen tereftalat (PET/PETE) care pot înlocui o parte din aportul lor virgin de materie primă. Prin urmare, valoarea este creată atât prin gestionarea fluxurilor de deșeuri, cât și prin transformarea materialelor plastice recuperate în materie primă comercializabilă pentru producție nouă. || Filmele de plastic colectate și materialele plastice rigide sunt separate în funcție de tipul și calitatea polimerului, curățate, mărunțite și reprocesate în diferite grade de granule reciclate. Portofoliul comercial al companiei cuprinde 17 produse din plastic reciclat, inclusiv patru polietilenă de înaltă densitate (HDPE), șase polietilenă de joasă densitate (LDPE), cinci polipropilenă (PP), o variantă de polistiren (PS) și o variantă de polietilen tereftalat (PET/PETE). Acest portofoliu diferențiat permite FINPLAST-PRIM să răspundă la diferite cerințe de producție, mai degrabă decât să vândă plastic recuperat ca deșeu nediferențiat. || De asemenea, compania gestionează ambalaje din hârtie și carton, lemn, sticlă și metal, oferind clienților de afaceri o soluție consolidată pentru mai multe fluxuri de deșeuri reciclabile. Site-ul său web raportează cantități procesate de 2.640 de tone de plastic, 8.280 de tone de hârtie și carton, 620 de tone de lemn și 560 de tone de sticlă, deși perioada de raportare ar trebui confirmată. || Modelul închide buclele materiale, deturnează deșeurile reciclabile de la eliminare și întărește piața internă a Republicii Moldova de materii prime secundare. Sprijinul acordat de UE și Programul Națiunilor Unite pentru Dezvoltare (PNUD) în 2026 va contribui la modernizarea sau extinderea capacității sale de reciclare. Lecția principală este că reciclarea generează o valoare circulară și economică mai mare atunci când deșeurile recuperate sunt convertite în materii prime diferențiate, pregătite pentru piață, legate de cererea de producție identificabilă.",hy:"FINPLAST-PRIM SRL-ը գործում է շրջանաձև բիզնես մոդել, որը հիմնված է պլաստիկ թափոնները կոմերցիոն արժեքավոր երկրորդական հումքի վերածելու վրա: Հյուսիսային Մոլդովայի Բալցիում գտնվող ընկերությունը հանդիսանում է վերամշակված պլաստիկ հատիկների արտադրող և մատակարար և փաթեթավորման և այլ վերամշակվող թափոնների հավաքման, տեսակավորման և վերամշակման լիազորված օպերատոր։ || Մոդելը կապում է երկու հաճախորդների խմբեր պլաստիկի արժեքային շղթայի շրջանակներում: Մատակարարման կողմում FINPLAST-PRIM-ը տրամադրում է թափոնների կառավարման ծառայություններ այն ընկերություններին, որոնք իրենց պլաստիկ և փաթեթավորման թափոնների հավաքագրման և մշակման կարիք ունեն: Պահանջարկի կողմից այն արտադրողներին մատակարարում է վերամշակված բարձր խտության պոլիէթիլեն (HDPE), ցածր խտության պոլիէթիլեն (LDPE), պոլիպրոպիլեն (PP), պոլիստիրոլ (PS) և պոլիէթիլենային տերեֆտալատ (PET/PETE) հատիկներ, որոնք կարող են փոխարինել իրենց կուսական հումքի մի մասը: Հետևաբար, արժեք է ստեղծվում ինչպես թափոնների հոսքերը կառավարելու, այնպես էլ վերականգնված պլաստմասսաները նոր արտադրության համար շուկայական հումքի վերածելու միջոցով։ || Հավաքված պլաստիկ թաղանթը և կոշտ պլաստմասսաները տարանջատվում են ըստ պոլիմերների տեսակի և որակի, մաքրվում, մանրացված և վերամշակվում են տարբեր կարգի վերամշակված հատիկներ: Ընկերության առևտրային պորտֆելը ներառում է 17 վերամշակված պլաստիկ արտադրանք, ներառյալ չորս բարձր խտության պոլիէթիլեն (HDPE), վեց ցածր խտության պոլիէթիլեն (LDPE), հինգ պոլիպրոպիլեն (PP), մեկ պոլիստիրոլ (PS) և մեկ պոլիէթիլենային տերեֆտալատ (PET/PETE): Այս տարբերակված պորտֆելը հնարավորություն է տալիս FINPLAST-PRIM-ին արձագանքել արտադրության տարբեր պահանջներին, այլ ոչ թե վաճառել վերականգնված պլաստիկը որպես չտարբերակված թափոն։ || Ընկերությունը նաև կառավարում է թղթի և ստվարաթղթի, փայտի, ապակու և մետաղի փաթեթավորում՝ բիզնես հաճախորդներին առաջարկելով մի քանի վերամշակվող թափոնների համախմբված լուծում: Նրա կայքը հաղորդում է 2640 տոննա պլաստմասսա, 8280 տոննա թուղթ և ստվարաթուղթ, 620 տոննա փայտ և 560 տոննա ապակի վերամշակված քանակներ, թեև հաշվետու ժամանակաշրջանը պետք է հաստատվի։ || Մոդելը փակում է նյութական փակ շրջափուլերը, շեղում է վերամշակվող թափոնները հեռացումից և ուժեղացնում է երկրորդային հումքի Մոլդովայի ներքին շուկան: ԵՄ-ի և ՄԱԿ-ի Զարգացման ծրագրի (ՄԱԶԾ) աջակցությունը, որը տրվել է 2026 թվականին, կօգնի արդիականացնել կամ ընդլայնել իր վերամշակման կարողությունները: Հիմնական դասն այն է, որ վերամշակումը առաջացնում է ավելի մեծ շրջանաձև և տնտեսական արժեք, երբ վերականգնված թափոնները վերածվում են տարբերակված, շուկայի համար պատրաստ հումքի, որը կապված է արտադրության հստակ պահանջարկի հետ։"},caseLink:"https://finplast.md/",image:"/images/cases/moldova/finplast-prim-srl.jpg",imageAlt:{en:"FINPLAST-PRIM SRL case image",uk:"Зображення корпусу FINPLAST-PRIM SRL",ro:"Imagine carcasa FINPLAST-PRIM SRL",hy:"FINPLAST-PRIM SRL պատյան պատկեր"}}),e({id:"case-003",slug:"s-r-l-refurb",companyName:{en:'S.R.L. "REFURB"',uk:"",ro:"",hy:""},country:"Republic of Moldova",sector:["Electronics and ICT"],rStrategies:["Refurbish (R5)","Reuse (R3)"],rStrategyDescription:{en:"Used devices are evaluated, tested, repaired or upgraded, graded by condition and resold with a warranty; refurbishment is the dominant strategy, with reuse occurring when the refurbished device returns to active use for its original function.",uk:"Вживані пристрої оцінюють, тестують, ремонтують або модернізують, класифікують за станом і продають із гарантією; домінантною стратегією – відновлення, а повторне використання відбувається тоді, коли відновлений пристрій повертається до активного використання за своїм початковим призначенням.",ro:"Dispozitivele folosite sunt evaluate, testate, reparate sau modernizate, clasificate în funcție de stare și revândute cu garanție; renovarea este strategia dominantă, reutilizarea având loc atunci când dispozitivul recondiționat revine la utilizarea activă pentru funcția sa inițială.",hy:"Օգտագործված սարքերը գնահատվում, փորձարկվում, վերանորոգվում կամ արդիականացվում են, գնահատվում են ըստ վիճակի և վերավաճառվում երաշխիքով. Վերանորոգումը գերիշխող ռազմավարությունն է, երբ վերաօգտագործումը տեղի է ունենում, երբ վերանորոգված սարքը վերադառնում է ակտիվ օգտագործման իր սկզբնական գործառույթի համար։"},summary:{en:'S.R.L. "REFURB" refurbishes, repairs and resells used electronics and Information and Communication Technology (ICT) equipment, extending their useful life through a warranted resale model and a laptop Trade-In programme.',uk:"S.R.L. «REFURB» відновлює, ремонтує та перепродає вживану електроніку й обладнання інформаційно-комунікаційних технологій, подовжуючи термін їхньої експлуатації завдяки моделі перепродажу з гарантією та програмі Trade-In для ноутбуків.",ro:"S.R.L. „REFURB” recondiționează, repara și revinde electronice uzate și echipamente pentru Tehnologia Informației și Comunicațiilor (TIC), prelungindu-le viața utilă printr-un model de revânzare garantat și un program de schimb de laptop.",hy:"Ս.Ռ.Լ. «REFURB»-ը վերանորոգում, վերանորոգում և վերավաճառում է օգտագործված էլեկտրոնիկա և Տեղեկատվական և հաղորդակցական տեխնոլոգիաների (ՏՀՏ) սարքավորումներ՝ երկարացնելով դրանց օգտակար կյանքը երաշխավորված վերավաճառքի մոդելի և նոութբուքի Trade-In ծրագրի միջոցով։"},description:{en:`S.R.L. "REFURB" operates a circular retail and service model that extends the useful life of electronics and Information and Communication Technology (ICT) equipment through refurbishment, resale, repair and Trade-In. Based in Chișinău, the company sells both new and refurbished smartphones, laptops, desktop computers, monitors, servers, televisions and audio equipment through its physical store and online platform, refurb.md. || The circular value proposition is to offer professionally refurbished devices as a reliable and more affordable alternative to newly manufactured equipment. According to the company, IT equipment undergoes a refurbishment process that includes, but is not limited to, testing, cleaning, repairing, reconfiguring, retesting and repackaging. Following this process, devices are returned to the market as functional products intended to perform similarly to new equipment. Refurbished products are presented with detailed technical specifications, condition grades such as Refurbished A or B, and a minimum 12-month warranty in accordance with applicable legal requirements. These features differentiate the model from informal second-hand resale by reducing customer uncertainty regarding functionality, quality and after-sales protection. || The company's Trade-In programme strengthens the return loop by allowing customers to exchange an old laptop for a refurbished one. Devices are tested and evaluated by the company's engineers, after which their assessed value is deducted from the replacement product's price. According to REFURB, more than 500 customers have used this service. Products may also be purchased through interest-free instalment options, while the company advertises savings of up to 50% on selected equipment. || The model generates value by recovering the remaining functional and economic value of existing devices instead of directing them prematurely to electronic-waste treatment. It makes technology more financially accessible while delaying e-waste generation and demand for new equipment. The case demonstrates that a standardised refurbishment process, warranties, condition grading and convenient Trade-In arrangements are essential for building consumer confidence and turning refurbished electronics into a credible commercial alternative to new products.`,uk:"S.R.L. «REFURB» працює за циркулярною роздрібною та сервісною моделлю, яка продовжує термін експлуатації електроніки й обладнання інформаційно-комунікаційних технологій (ІКТ) завдяки відновленню, повторному продажу, ремонту та програмі Trade-In. Компанія розташована в Кишиневі та продає як нові, так і відновлені смартфони, ноутбуки, настільні комп’ютери, монітори, сервери, телевізори й аудіообладнання через фізичний магазин та онлайн-платформу refurb.md. || Ціннісна пропозиція циркулярної моделі – професійно відновлені пристрої як надійна та доступніша за ціною альтернатива новому обладнанню. За інформацією компанії, ІТ-обладнання проходить процес відновлення, який охоплює, зокрема, тестування, очищення, ремонт, повторне налаштування, повторне тестування та повторне пакування. Після цього процесу пристрої повертаються на ринок як функціональні вироби, призначені для роботи на рівні, подібному до нового обладнання. Відновлені вироби супроводжуються детальними технічними характеристиками, класифікацією за станом, наприклад Refurbished A або B, та гарантією щонайменше на 12 місяців відповідно до чинних законодавчих вимог. Ці характеристики відрізняють цю модель від неформального продажу вживаної техніки, зменшуючи невизначеність для покупців щодо її функціональності, якості та післяпродажного обслуговування. || Програма Trade-In компанії посилює цикл повернення, даючи клієнтам змогу обміняти старий ноутбук на відновлений. Пристрої тестують та оцінюють інженери компанії, після чого визначену вартість старого пристрою віднімають від ціни нового для клієнта. За інформацією REFURB, цією послугою скористалися понад 500 клієнтів. Продукцію також можна придбати з можливістю безвідсоткової оплати частинами, а компанія заявляє про економію до 50% на окремих видах обладнання. || Модель створює цінність завдяки збереженню функціональної та економічної цінності наявних пристроїв замість передчасного спрямування їх на оброблення електронних відходів. Вона робить технології доступнішими за ціною, водночас відтерміновуючи утворення електронних відходів і зменшуючи попит на нове обладнання. Цей приклад демонструє, що стандартизований процес відновлення, гарантії, класифікація за станом і зручні умови Trade-In мають важливе значення для формування довіри споживачів і перетворення відновленої електроніки на повноцінну комерційну альтернативу новій продукції.",ro:"S.R.L. „REFURB” operează un model circular de vânzare cu amănuntul și servicii care prelungește durata de viață utilă a echipamentelor electronice și a tehnologiei informației și comunicațiilor (TIC) prin recondiționare, revânzare, reparare și schimb. Cu sediul în Chișinău, compania vinde atât smartphone-uri, laptop-uri, computere desktop, monitoare, servere, televizoare și echipamente audio noi, cât și recondiționate prin intermediul magazinului său fizic și platformei online, refurb.md. || Propunerea de valoare circulară este de a oferi dispozitive recondiționate profesional ca o alternativă fiabilă și mai accesibilă la echipamentele nou fabricate. Potrivit companiei, echipamentele IT sunt supuse unui proces de recondiționare care include, dar nu se limitează la, testarea, curățarea, repararea, reconfigurarea, retestarea și reambalarea. În urma acestui proces, dispozitivele sunt returnate pe piață ca produse funcționale destinate să funcționeze similar cu echipamentele noi. Produsele recondiționate sunt prezentate cu specificații tehnice detaliate, grade de stare precum Refurbished A sau B și o garanție de minim 12 luni în conformitate cu cerințele legale aplicabile. Aceste caracteristici diferențiază modelul de revânzarea informală la mâna a doua prin reducerea incertitudinii clienților în ceea ce privește funcționalitatea, calitatea și protecția post-vânzare. || Programul Trade-In al companiei întărește bucla de returnare, permițând clienților să schimbe un laptop vechi cu unul recondiționat. Dispozitivele sunt testate și evaluate de către inginerii companiei, după care valoarea lor evaluată este dedusă din prețul produsului de înlocuire. Potrivit REFURB, peste 500 de clienți au folosit acest serviciu. Produsele pot fi achiziționate și prin opțiuni de rate fără dobândă, în timp ce compania face publicitate pentru economii de până la 50% la echipamentele selectate. || Modelul generează valoare prin recuperarea valorii funcționale și economice rămase a dispozitivelor existente în loc să le direcționeze prematur către tratarea deșeurilor electronice. Face tehnologia mai accesibilă financiar, în timp ce întârzie generarea deșeurilor electronice și cererea de echipamente noi. Cazul demonstrează că un proces de recondiționare standardizat, garanții, clasificarea stării și aranjamente convenabile de schimb sunt esențiale pentru construirea încrederii consumatorilor și pentru transformarea electronicelor recondiționate într-o alternativă comercială credibilă la produsele noi.",hy:"Ս.Ռ.Լ. «REFURB»-ը գործում է մանրածախ և սպասարկման շրջանաձև մոդել, որը երկարացնում է էլեկտրոնիկայի և Տեղեկատվական և հաղորդակցական տեխնոլոգիաների (ՏՀՏ) սարքավորումների օգտակար կյանքը վերանորոգման, վերավաճառքի, վերանորոգման և առևտրի միջոցով: Քիշնևում հիմնված ընկերությունն իր ֆիզիկական խանութի և առցանց հարթակի՝ refurb.md-ի միջոցով վաճառում է ինչպես նոր, այնպես էլ վերանորոգված սմարթֆոններ, դյուրակիր համակարգիչներ, սեղանադիր համակարգիչներ, մոնիտորներ, սերվերներ, հեռուստացույցներ և աուդիո սարքավորումներ։ || Շրջանաձև արժեքային առաջարկն է՝ առաջարկել պրոֆեսիոնալ վերանորոգված սարքեր՝ որպես նոր արտադրված սարքավորումների հուսալի և ավելի մատչելի այլընտրանք: Ընկերության տվյալներով՝ ՏՏ սարքավորումները ենթարկվում են վերանորոգման գործընթացի, որը ներառում է, բայց չի սահմանափակվում դրանով, փորձարկում, մաքրում, վերանորոգում, վերակազմավորում, վերստուգում և փաթեթավորում: Այս գործընթացից հետո սարքերը վերադարձվում են շուկա՝ որպես գործունակ արտադրանք, որոնք նախատեսված են նոր սարքավորումների նման աշխատանքի համար: Վերանորոգված ապրանքները ներկայացված են մանրամասն տեխնիկական բնութագրերով, վիճակի աստիճաններով, ինչպիսիք են Վերանորոգված A կամ B, և նվազագույնը 12-ամսյա երաշխիք՝ համապատասխան օրենսդրական պահանջներին համապատասխան: Այս հատկանիշները տարբերակում են մոդելը ոչ պաշտոնական երկրորդ ձեռքի վերավաճառքից՝ նվազեցնելով հաճախորդի անորոշությունը գործունակության, որակի և վաճառքից հետո պաշտպանության վերաբերյալ։ || Ընկերության Trade-In ծրագիրը ուժեղացնում է վերադարձի օղակը՝ թույլ տալով հաճախորդներին փոխանակել հին նոութբուքը վերանորոգվածի հետ: Սարքերը փորձարկվում և գնահատվում են ընկերության ինժեներների կողմից, որից հետո դրանց գնահատված արժեքը հանվում է փոխարինող ապրանքի գնից: Ըստ REFURB-ի՝ այս ծառայությունից օգտվել է ավելի քան 500 հաճախորդ։ Ապրանքները կարելի է ձեռք բերել նաև անտոկոս ապառիկ տարբերակով, մինչդեռ ընկերությունը գովազդում է մինչև 50% խնայողություն ընտրված սարքավորումների վրա։ || Մոդելը արժեք է ստեղծում՝ վերականգնելով առկա սարքերի մնացած գործառնական և տնտեսական արժեքը՝ դրանք ժամանակից շուտ էլեկտրոնային թափոնների մշակմանն ուղղելու փոխարեն: Այն տեխնոլոգիան դարձնում է ֆինանսապես ավելի մատչելի՝ միաժամանակ հետաձգելով էլեկտրոնային թափոնների առաջացումը և նոր սարքավորումների պահանջարկը: Օրինակը ցույց է տալիս, որ ստանդարտացված վերանորոգման գործընթացը, երաշխիքները, պայմանների դասակարգումը և առևտրի հարմար պայմանավորվածությունները կարևոր են սպառողների վստահությունը ձևավորելու և վերանորոգված էլեկտրոնիկան նոր ապրանքների համար վստահելի կոմերցիոն այլընտրանքի վերածելու համար։"},caseLink:"https://refurb.md/"}),e({id:"case-004",slug:"asociatia-obsteasca-banca-de-alimente-banca-de-alimente-moldova",companyName:{en:"Banca de Alimente Moldova",uk:"",ro:"",hy:""},country:"Republic of Moldova",sector:["Food and Agriculture"],rStrategies:["Reuse (R3)"],rStrategyDescription:{en:"Safe, edible products that can no longer be sold are redirected for their original purpose, human consumption; this also constitutes food-waste prevention, as products are recovered before becoming waste.",uk:"Безпечні для споживання продукти, які вже не можна продати, спрямовують за їхнім первісним призначенням – для споживання людьми. Така практика також сприяє запобіганню утворенню харчових відходів, оскільки продукти вилучають із надлишків до того, як вони стануть відходами.",ro:"Produsele sigure, comestibile care nu mai pot fi vândute sunt redirecționate pentru scopul lor inițial, consumul uman; aceasta constituie și prevenirea risipei alimentare, deoarece produsele sunt valorificate înainte de a deveni deșeuri.",hy:"Անվտանգ, ուտելի արտադրանքները, որոնք այլևս չեն կարող վաճառվել, վերահասցեավորվում են իրենց սկզբնական նպատակի համար՝ մարդու սպառման համար. սա նաև սննդամթերքի թափոնների կանխարգելում է, քանի որ արտադրանքը վերականգնվում է մինչև թափոն դառնալը։"},summary:{en:"Banca de Alimente Moldova recovers safe, edible surplus food from agri-food companies and redistributes it through a national network of social services supporting vulnerable people.",uk:"Banca de Alimente Moldova вилучає безпечні їстівні надлишки харчових продуктів у агропродовольчих компаній та перерозподіляє їх через національну мережу соціальних служб для підтримки вразливих верств населення.",ro:"Banca de Alimente Moldova recuperează surplusul de alimente sigure, comestibile de la companiile agroalimentare și le redistribuie printr-o rețea națională de servicii sociale care sprijină persoanele vulnerabile.",hy:"Banca de Alimente Moldova-ն վերականգնում է անվտանգ, ուտելի սննդի ավելցուկը ագրոպարենային ընկերություններից և վերաբաշխում այն սոցիալական ծառայությունների ազգային ցանցի միջոցով, որն աջակցում է խոցելի մարդկանց։"},description:{en:"Banca de Alimente Moldova operates a nonprofit circular redistribution model that recovers safe, edible surplus food and redirects it to social services supporting vulnerable people. Established in 2021 as Moldova's first food bank, the organisation connects agri-food producers, distributors and retailers holding unsold products with charities, canteens, placement centres and other social-service providers. || Its circular value proposition is based on preserving food at its highest value — human consumption — rather than allowing it to become waste. Surplus products are collected from donor companies, checked and managed according to food-safety requirements, stored using appropriate facilities, including cold storage where necessary, and redistributed according to remaining shelf life and beneficiary needs. The model therefore depends on coordinated logistics, food-flow management and durable partnerships, not simply on accepting occasional donations. || During its first five years, Banca de Alimente recovered and redistributed 583 tonnes of food, equivalent to approximately 1,166,000 meal portions. Its national network grew to 95 donor companies and 105 partner social services, reaching more than 12,500 beneficiaries. The organisation estimates that its food-recovery activity has also avoided approximately 1,450 tonnes of greenhouse-gas emissions, while preserving the water, energy, land, labour and transport embedded in food production. || The model creates environmental value by preventing food waste, social value by improving access to food and economic value by helping donor companies avoid disposal and associated management costs. Since 2022, Banca de Alimente has been an associate member of the European Food Banks Federation, supporting peer learning and alignment with European practice. The principal lesson is that preventing food waste at scale requires reliable logistics, food-safety controls and coordinated partnerships across the entire food value chain.",uk:"Banca de Alimente Moldova працює за неприбутковою циркулярною моделлю перерозподілу, у межах якої збирає безпечні для споживання надлишки харчових продуктів і передає їх соціальним службам, що підтримують вразливі верстви населення. Організацію засновано у 2021 році як перший у Молдові продовольчий банк. Вона об’єднує виробників, дистриб’юторів і роздрібних продавців агропродовольчої продукції, у яких залишаються непродані продукти, з благодійними організаціями, їдальнями, центрами розміщення та іншими надавачами соціальних послуг. || Ціннісна пропозиція циркулярної моделі ґрунтується на збереженні продуктів на найвищому рівні їхньої цінності – для споживання людьми – замість того, щоб вони ставали відходами. Надлишки продуктів збирають у компаній-донорів, перевіряють і зберігають відповідно до вимог безпечності харчових продуктів, використовуючи належні умови, зокрема холодильне обладнання за потреби, а потім перерозподіляють з урахуванням залишкового терміну придатності та потреб отримувачів. Отже, ця модель потребує скоординованої логістики, управління потоками харчових продуктів і сталих партнерств, а не просто приймання періодичних пожертв. || За перші п’ять років роботи Banca de Alimente зібрала та перерозподілила 583 тонни харчових продуктів, що еквівалентно приблизно 1 166 000 порцій їжі. Національна мережа організації зросла до 95 компаній-донорів і 105 партнерських соціальних служб, охопивши понад 12 500 отримувачів допомоги. За оцінкою організації, завдяки діяльності зі збирання харчових продуктів також вдалося уникнути приблизно 1 450 тонн викидів парникових газів, одночасно зберігши воду, енергію, земельні ресурси, працю та транспортні ресурси, використані для виробництва харчових продуктів. || Модель створює екологічну цінність завдяки запобіганню утворенню харчових відходів, соціальну цінність – завдяки покращенню доступу до харчових продуктів, а економічну – допомагаючи компаніям-донорам уникати витрат на видалення відходів та пов’язаних із цим витрат. Із 2022 року Banca de Alimente – асоційований член Європейської федерації продовольчих банків, що сприяє обміну досвідом та узгодженню з європейськими практиками. Головний висновок полягає в тому, що запобігання утворенню харчових відходів у великих масштабах потребує надійної логістики, контролю безпечності харчових продуктів і скоординованого партнерства на всьому ланцюгу створення вартості харчових продуктів.",ro:"Banca de Alimente Moldova operează un model de redistribuire circulară nonprofit care recuperează surplusul de alimente sigure, comestibile și le redirecționează către serviciile sociale care sprijină persoanele vulnerabile. Înființată în 2021 ca prima bancă de alimente din Moldova, organizația conectează producătorii agroalimentari, distribuitorii și comercianții cu amănuntul care dețin produse nevândute cu organizații caritabile, cantine, centre de plasament și alți furnizori de servicii sociale. || Propunerea sa de valoare circulară se bazează pe conservarea alimentelor la cea mai mare valoare - consumul uman - mai degrabă decât pe a le permite să devină deșeuri. Produsele excedentare sunt colectate de la companiile donatoare, verificate și gestionate în conformitate cu cerințele de siguranță alimentară, depozitate folosind instalații adecvate, inclusiv depozitare la rece acolo unde este necesar, și redistribuite în funcție de termenul de valabilitate rămas și de nevoile beneficiarului. Prin urmare, modelul depinde de logistică coordonată, managementul fluxului alimentar și parteneriate durabile, nu doar de acceptarea unor donații ocazionale. || În primii cinci ani, Banca de Alimente a recuperat și redistribuit 583 de tone de alimente, echivalentul a aproximativ 1.166.000 de porții de masă. Rețeaua sa națională a crescut la 95 de companii donatoare și 105 de servicii sociale partenere, ajungând la peste 12.500 de beneficiari. Organizația estimează că activitatea sa de recuperare a alimentelor a evitat, de asemenea, aproximativ 1.450 de tone de emisii de gaze cu efect de seră, păstrând în același timp apa, energia, pământul, forța de muncă și transportul încorporate în producția de alimente. || Modelul creează valoare de mediu prin prevenirea risipei de alimente, valoare socială prin îmbunătățirea accesului la alimente și valoare economică, ajutând companiile donatoare să evite eliminarea și costurile de management asociate. Din 2022, Banca de Alimente este membru asociat al Federației Europene a Băncilor Alimentare, susținând învățarea de la egal la egal și alinierea la practica europeană. Principala lecție este că prevenirea risipei alimentare la scară necesită o logistică fiabilă, controale privind siguranța alimentelor și parteneriate coordonate de-a lungul întregului lanț valoric alimentar.",hy:"Banca de Alimente Moldova-ն շահույթ չհետապնդող շրջանաձև վերաբաշխման մոդել է գործում, որը վերականգնում է անվտանգ, ուտելի սննդի ավելցուկը և այն ուղղորդում սոցիալական ծառայություններին, որոնք աջակցում են խոցելի մարդկանց: Հիմնադրվելով 2021 թվականին որպես Մոլդովայի առաջին պարենային բանկ՝ կազմակերպությունը կապում է ագրոպարենային արտադրողներին, դիստրիբյուտորներին և մանրածախ առևտրականներին, որոնք պահում են չվաճառված ապրանքները բարեգործական կազմակերպությունների, ճաշարանների, տեղաբաշխման կենտրոնների և սոցիալական ծառայություններ մատուցողների հետ։ || Նրա շրջանաձև արժեքային առաջարկը հիմնված է սննդամթերքի ամենաբարձր արժեքով` մարդու սպառման, պահպանման վրա, այլ ոչ թե թույլ տալով, որ այն դառնա թափոն: Ավելցուկային արտադրանքը հավաքվում է դոնոր ընկերություններից, ստուգվում և կառավարվում է սննդամթերքի անվտանգության պահանջներին համապատասխան, պահվում են համապատասխան հարմարանքներով, ներառյալ սառնարանային պահեստները, որտեղ անհրաժեշտ է, և վերաբաշխվում՝ ըստ մնացած պահպանման ժամկետի և շահառուների կարիքների: Հետևաբար, մոդելը կախված է համակարգված լոգիստիկայից, սննդի հոսքի կառավարումից և տեւական գործընկերություններից, ոչ թե պարզապես երբեմն-երբեմն նվիրատվություններ ընդունելուց։ || Իր առաջին հինգ տարիների ընթացքում Banca de Alimente-ն վերականգնել և վերաբաշխել է 583 տոննա սննդամթերք, որը համարժեք է մոտավորապես 1,166,000 սննդի բաժին: Նրա ազգային ցանցն աճել է մինչև 95 դոնոր ընկերություններ և 105 գործընկեր սոցիալական ծառայություններ՝ հասնելով ավելի քան 12,500 շահառուի: Կազմակերպությունը գնահատում է, որ սննդամթերքի վերականգնման իր գործունեությունը նաև խուսափել է մոտավորապես 1450 տոննա ջերմոցային գազերի արտանետումներից՝ միաժամանակ պահպանելով սննդի արտադրության մեջ ներառված ջուրը, էներգիան, հողը, աշխատուժը և տրանսպորտը։ || Մոդելը ստեղծում է բնապահպանական արժեք՝ կանխելով սննդի թափոնները, սոցիալական արժեք՝ բարելավելով սննդամթերքի հասանելիությունը և տնտեսական արժեքը՝ օգնելով դոնոր ընկերություններին խուսափել հեռացումից և դրա հետ կապված կառավարման ծախսերից: 2022 թվականից Banca de Alimente-ն հանդիսանում է Եվրոպական պարենային բանկերի ֆեդերացիայի ասոցիացված անդամ՝ աջակցելով գործընկերների ուսուցմանը և համապատասխանեցմանը եվրոպական պրակտիկային: Հիմնական դասն այն է, որ սննդամթերքի մասշտաբային թափոնների կանխարգելումը պահանջում է հուսալի լոգիստիկա, սննդամթերքի անվտանգության վերահսկում և համակարգված համագործակցություն ողջ սննդի արժեքային շղթայում։"},caseLink:"https://bancadealimente.md/",image:"/images/cases/moldova/asociatia-obsteasca-banca-de-alimente-banca-de-alimente-moldova.jpg",imageAlt:{en:"Asociația Obștească Banca de Alimente – Banca de Alimente Moldova case image",uk:"Asociația Obștească Banca de Alimente – Banca de Alimente Moldova case image",ro:"Asociația Obștească Banca de Alimente – Imagine de caz Banca de Alimente Moldova",hy:"Associația Obștească Banca de Alimente – Banca de Alimente Moldova գործի պատկեր"}}),e({id:"case-005",slug:"garma-grup-srl",companyName:{en:"Garma-Grup SRL",uk:"",ro:"",hy:""},country:"Republic of Moldova",sector:["Food and Agriculture"],rStrategies:["Recycle (R8)","Reduce (R2)"],rStrategyDescription:{en:"Biodegradable residues are biologically processed and their nutrients returned to agricultural use as organic fertilizer (Recycle); the model also decreases demand for conventional energy and synthetic fertilizers (Reduce).",uk:"Біорозкладні залишки піддають біологічному переробленню, а поживні речовини повертають у сільськогосподарське виробництво у вигляді органічних добрив (Перероблення, R8); модель також зменшує потребу у традиційних джерелах енергії та синтетичних добривах (Скорочення, R2).",ro:"Reziduurile biodegradabile sunt procesate biologic, iar nutrienții lor returnați utilizării agricole ca îngrășământ organic (Reciclare); modelul scade, de asemenea, cererea de energie convențională și îngrășăminte sintetice (Reduce).",hy:"Կենսաքայքայվող մնացորդները կենսաբանորեն վերամշակվում են, և դրանց սնուցիչները վերադարձվում են գյուղատնտեսական օգտագործման՝ որպես օրգանական պարարտանյութ (Վերամշակում); մոդելը նաև նվազեցնում է սովորական էներգիայի և սինթետիկ պարարտանյութերի պահանջարկը (Reduce)։"},summary:{en:"Garma-Grup SRL converts manure, alcohol-production residues and slaughterhouse waste into biogas, renewable electricity and organic fertilizer through anaerobic digestion.",uk:"Garma-Grup SRL переробляє гній, залишки спиртового виробництва та відходи забійних цехів на біогаз, відновлювану електроенергію та органічні добрива за допомогою анаеробного зброджування.",ro:"Garma-Grup SRL transformă gunoiul de grajd, reziduurile din producția de alcool și deșeurile de la abator în biogaz, energie electrică regenerabilă și îngrășământ organic prin digestie anaerobă.",hy:"Garma-Grup SRL-ը անաէրոբ մարսողության միջոցով փոխակերպում է գոմաղբը, ալկոհոլի արտադրության մնացորդները և սպանդանոցային թափոնները կենսագազի, վերականգնվող էլեկտրաէներգիայի և օրգանական պարարտանյութի։"},description:{en:"Garma-Grup SRL is an integrated agrifood company based in Fîrlădeni, Hîncești district, whose activities include crop cultivation, feed production, cattle farming, grain and pasta processing, ethyl-alcohol production and renewable-energy generation. Its circular business model connects these operations so that biological residues from one activity become productive inputs for another. || Manure from the company's cattle farm and organic residues from alcohol production are used as the principal feedstock for its anaerobic-digestion facility. Garma-Grup also processes organic waste received from nearby slaughterhouses, creating industrial symbiosis between livestock farming, food processing, waste management and energy production. Instead of being discarded or left to decompose, these materials are converted into biogas. According to the company, the facility can produce up to 50,000 m³ of biogas per day. The biogas is used to generate steam for alcohol production and renewable electricity through three Jenbacher cogeneration units with a combined reported capacity exceeding 3 MW. The electricity supplies the company's operations, while surplus production is delivered to the national grid. || The remaining organic material is used as fertilizer on approximately 500 hectares of company-managed agricultural land, returning nutrients to crop production and reducing dependence on synthetic fertilizers. This closes biological resource loops while improving the efficiency of the company's integrated production system. || The model generates environmental benefits by diverting organic residues from uncontrolled disposal, reducing potential soil and water pollution and replacing part of the company's conventional energy and fertilizer requirements. Economically, it transforms waste-management costs into energy savings, productive agricultural inputs and potential revenue from surplus electricity. The case demonstrates how an agrifood producer can embed circularity in its core business model by combining internal resource recovery, renewable-energy generation, nutrient recycling and partnerships with external waste generators.",uk:"Garma-Grup SRL – інтегрована агропродовольча компанія, розташована у Фирледенах, Хинчештському районі, діяльність якої охоплює вирощування сільськогосподарських культур, виробництво кормів, розведення великої рогатої худоби, перероблення зерна та виробництво макаронних виробів, виробництво етилового спирту та генерацію відновлюваної енергії. Її циркулярна бізнес-модель поєднує ці види діяльності у такий спосіб, щоби біологічні залишки від одного процесу ставали корисною сировиною для іншого. || Гній із тваринницької ферми компанії та органічні залишки спиртового виробництва використовують як основну сировину для установки анаеробного зброджування. Garma-Grup також переробляє органічні відходи, які надходять із розташованих поблизу м’ясопереробних підприємств, створюючи промисловий симбіоз між тваринництвом, харчовим виробництвом, управлінням відходами та виробництвом енергії. || Замість того щоб потрапляти у відходи або розкладатися без належного контролю, ці матеріали перетворюються на біогаз. За інформацією компанії, установка може виробляти до 50 000 м³ біогазу на добу. Біогаз використовують для виробництва пари для спиртового виробництва та відновлюваної електроенергії за допомогою трьох когенераційних установок Jenbacher із сукупною заявленою потужністю понад 3 МВт. Електроенергія забезпечує потреби самої компанії, а надлишок виробленої електроенергії подається до національної електромережі. ||  Залишковий органічний матеріал використовують як добриво приблизно на 500 гектарах сільськогосподарських земель, якими управляє компанія, повертаючи поживні речовини у рослинництво та зменшуючи залежність від синтетичних добрив. Таким способом замикаються біологічні цикли ресурсів і підвищується ефективність інтегрованої виробничої системи компанії. || Модель створює екологічні переваги завдяки запобіганню неконтрольованому потраплянню органічних залишків у довкілля, зменшенню ризику забруднення ґрунтів і води та заміщенню частини традиційних енергоресурсів і добрив. З економічного погляду вона перетворює витрати на управління відходами на економію енергії, корисні ресурси для сільськогосподарського виробництва та потенційний дохід від продажу надлишкової електроенергії. Цей приклад демонструє, як агропродовольча компанія може інтегрувати циркулярні підходи у свою основну бізнес-модель, поєднуючи внутрішнє відновлення ресурсів, виробництво відновлюваної енергії, повернення поживних речовин у виробничий цикл і партнерство із зовнішніми постачальниками органічних відходів.",ro:"Garma-Grup SRL este o companie agroalimentară integrată cu sediul în Fîrlădeni, raionul Hîncești, ale cărei activități includ cultivarea culturilor, producția de furaje, creșterea vitelor, prelucrarea cerealelor și pastelor, producția de alcool etilic și generarea de energie regenerabilă. Modelul său circular de afaceri conectează aceste operațiuni, astfel încât reziduurile biologice dintr-o activitate să devină inputuri productive pentru alta. || Gunoiul de grajd de la ferma de vite a companiei și reziduurile organice din producția de alcool sunt utilizate ca materie primă principală pentru instalația de digestie anaerobă a acesteia. Garma-Grup prelucrează și deșeurile organice primite de la abatoarele din apropiere, creând simbioză industrială între creșterea animalelor, procesarea alimentelor, managementul deșeurilor și producția de energie. În loc să fie aruncate sau lăsate să se descompună, aceste materiale sunt transformate în biogaz. Potrivit companiei, instalația poate produce până la 50.000 m³ de biogaz pe zi. Biogazul este folosit pentru a genera abur pentru producerea de alcool și energie electrică regenerabilă prin trei unități de cogenerare Jenbacher cu o capacitate raportată combinată de peste 3 MW. Energia electrică alimentează operațiunile companiei, în timp ce surplusul de producție este livrat la rețeaua națională. || Materialul organic rămas este folosit ca îngrășământ pe aproximativ 500 de hectare de teren agricol administrat de companie, returnând nutrienții producției agricole și reducând dependența de îngrășămintele sintetice. Acest lucru închide buclele de resurse biologice, îmbunătățind în același timp eficiența sistemului de producție integrat al companiei. || Modelul generează beneficii de mediu prin deturnarea reziduurilor organice de la eliminarea necontrolată, reducerea potențialului poluare a solului și a apei și înlocuirea unei părți din cerințele convenționale de energie și îngrășăminte ale companiei. Din punct de vedere economic, transformă costurile de gestionare a deșeurilor în economii de energie, inputuri agricole productive și venituri potențiale din surplusul de energie electrică. Cazul demonstrează modul în care un producător agroalimentar poate încorpora circularitatea în modelul său de afaceri de bază, combinând recuperarea resurselor interne, generarea de energie regenerabilă, reciclarea nutrienților și parteneriate cu generatorii externi de deșeuri.",hy:"Garma-Grup SRL-ը ինտեգրված ագրոպարենային ընկերություն է, որը հիմնված է Ֆիրլադենիում, Հինչեստի շրջանում, որի գործունեությունը ներառում է կուլտուրաների մշակում, անասնակերի արտադրություն, անասնաբուծություն, հացահատիկի և մակարոնեղենի վերամշակում, էթիլ-ալկոհոլի արտադրություն և վերականգնվող էներգիայի արտադրություն: Նրա շրջանաձև բիզնես մոդելը միացնում է այս գործողությունները, որպեսզի մի գործունեության կենսաբանական մնացորդները մյուսի համար դառնան արդյունավետ միջոցներ։ || Ընկերության անասնաբուծական ֆերմայից ստացված գոմաղբը և ալկոհոլի արտադրության օրգանական մնացորդները օգտագործվում են որպես անաէրոբ մարսողության հիմնական հումք: Garma-Grup-ը նաև վերամշակում է մոտակա սպանդանոցներից ստացված օրգանական թափոնները՝ ստեղծելով արդյունաբերական սիմբիոզ անասնաբուծության, սննդի վերամշակման, թափոնների կառավարման և էներգիայի արտադրության միջև: Այս նյութերը դեն նետվելու կամ քայքայվելու փոխարեն վերածվում են կենսագազի։ Ընկերության տվյալներով՝ օբյեկտը կարող է օրական արտադրել մինչև 50000 մ³ կենսագազ։ Կենսագազն օգտագործվում է ալկոհոլի արտադրության և վերականգնվող էլեկտրաէներգիայի համար գոլորշու առաջացման համար Jenbacher-ի երեք համակցված էներգաբլոկների միջոցով, որոնց ընդհանուր հզորությունը գերազանցում է 3 ՄՎտ: Էլեկտրաէներգիան ապահովում է ընկերության աշխատանքը, իսկ ավելցուկային արտադրությունը մատակարարվում է ազգային ցանց։ || Մնացած օրգանական նյութը օգտագործվում է որպես պարարտանյութ ընկերության կողմից կառավարվող մոտ 500 հեկտար գյուղատնտեսական հողերի վրա՝ սննդանյութերը վերադարձնելով բերքի արտադրությանը և նվազեցնելով կախվածությունը սինթետիկ պարարտանյութերից: Սա փակում է կենսաբանական ռեսուրսների օղակները՝ միաժամանակ բարելավելով ընկերության ինտեգրված արտադրական համակարգի արդյունավետությունը։ || Մոդելը բնապահպանական օգուտներ է բերում՝ շեղելով օրգանական մնացորդները անվերահսկելի հեռացումից, նվազեցնելով հողի և ջրի հնարավոր աղտոտումը և փոխարինելով ընկերության սովորական էներգիայի և պարարտանյութերի պահանջները: Տնտեսական առումով այն վերածում է թափոնների կառավարման ծախսերը էներգիայի խնայողության, գյուղատնտեսական արդյունավետ միջոցների և ավելցուկային էլեկտրաէներգիայի հնարավոր եկամուտների: Օրինակը ցույց է տալիս, թե ինչպես ագրոպարեն արտադրողը կարող է ներդնել շրջանաձևությունը իր հիմնական բիզնես մոդելում՝ համատեղելով ներքին ռեսուրսների վերականգնումը, վերականգնվող էներգիայի արտադրությունը, սննդանյութերի վերամշակումը և համագործակցությունը արտաքին թափոնների գեներատորների հետ։"},caseLink:"https://garma-grup.md/en/about-us/",image:"/images/cases/moldova/garma-grup-srl.jpg",imageAlt:{en:"Garma-Grup SRL case image",uk:"Зображення справи Garma-Grup SRL",ro:"Imagine caz Garma-Grup SRL",hy:"Garma-Grup SRL գործի պատկերը"}}),e({id:"case-006",slug:"unfloria-srl",companyName:{en:"Unfloria SRL",uk:"",ro:"",hy:""},country:"Republic of Moldova",sector:["Textiles"],rStrategies:["Repair (R4)","Refurbish (R5)","Reduce (R2)"],rStrategyDescription:{en:"Professional textile care maintains product quality and extends useful life (Repair); cleaning and restoration of feather pillows (Refurbish); lower demand for replacement textiles and in-house laundry resources (Reduce).",uk:"Професійний догляд за текстильними виробами допомагає зберігати їхню якість і продовжувати термін експлуатації (Ремонт); чищення та відновлення пір’яних подушок (Відновлення); зменшення потреби в заміні текстильних виробів і ресурсах для їхнього прання власними силами (Скорочення).",ro:"Îngrijirea profesională a textilelor menține calitatea produsului și prelungește durata de viață utilă (Reparație); curățarea și restaurarea pernelor din pene (Refurbish); cerere mai scăzută pentru textile de înlocuire și resurse de spălătorie interne (Reducere).",hy:"Տեքստիլի պրոֆեսիոնալ խնամքը պահպանում է արտադրանքի որակը և երկարացնում է օգտակար ծառայության ժամկետը (Վերանորոգում); փետուր բարձերի մաքրում և վերականգնում (Refurbish); փոխարինող տեքստիլի և ներքին լվացքի ռեսուրսների ավելի ցածր պահանջարկ (Նվազեցնել)։"},summary:{en:"UNFLORIA SRL provides professional textile laundry, cleaning and restoration services that extend the useful life of clients' garments, linens, carpets and feather pillows.",uk:"UNFLORIA SRL (ТОВ «УНФЛОРІЯ») надає професійні послуги із прання, чищення та реставрації текстилю, подовжуючи термін корисного використання одягу, білизни, килимів і пір'яних подушок клієнтів.",ro:"UNFLORIA SRL furnizează servicii profesionale de spălătorie textile, curățenie și restaurare care prelungesc durata de viață utilă a articolelor de îmbrăcăminte, lenjerii, covoarelor și pernelor din pene ale clienților.",hy:"UNFLORIA SRL-ը տրամադրում է պրոֆեսիոնալ տեքստիլ լվացքի, մաքրման և վերականգնման ծառայություններ, որոնք երկարացնում են հաճախորդների հագուստի, սպիտակեղենի, գորգերի և փետուր բարձերի օգտակար կյանքը։"},description:{en:"UNFLORIA SRL is a textile-service company based in Ungheni that provides professional laundry, ecological dry-cleaning and textile-maintenance services to private companies, public institutions and individual customers. Its activities include washing and caring for garments, linen, workwear, knitwear, carpets and other household or institutional textiles, as well as the specialised cleaning, sanitisation and restoration of feather pillows. || The company operates through a product-as-a-service-oriented circular business model, generating value through professional textile care rather than relying exclusively on the sale of new products. Through service contracts, UNFLORIA assumes responsibility for washing, cleaning, sanitising and maintaining textiles used by its clients. The products are treated according to their material characteristics and care requirements and are returned hygienised, in good condition and suitable for continued use. || Outsourcing these activities to a specialised provider enables companies and public institutions to avoid or reduce the resources required for an in-house laundry, including investments in washing and drying equipment, energy and water consumption, detergents, maintenance costs and dedicated personnel. At the same time, clients benefit from professionally cleaned textiles that meet high hygiene and quality standards. Appropriate treatment helps preserve textile structure, appearance and functionality, extending product lifetimes and reducing replacement frequency and related expenditure. || The cleaning, sanitisation and restoration of feather pillows is particularly relevant to circularity. Existing pillows and their natural filling are recovered and restored for continued use instead of being prematurely discarded and replaced. || UNFLORIA reports using biodegradable detergents and solvents and integrating solar energy into its operations. These practices complement the service model by reducing the environmental impact of textile maintenance. || The case demonstrates how specialised and centralised textile-care services can create economic benefits for clients while slowing textile consumption and waste generation. By combining professional maintenance, high-quality sanitisation, resource-efficient service delivery and pillow restoration, UNFLORIA helps keep textile products functional and in use for longer.",uk:"UNFLORIA SRL – компанія, що надає текстильні послуги та розташована в Унгенах. Вона пропонує професійне прання, екологічне хімічне чищення та догляд за текстильними виробами для приватних компаній, державних установ і фізичних осіб. Послуги охоплюють прання та догляд за одягом, постільною білизною, робочим одягом, трикотажем, килимами та іншими побутовими й інституційними текстильними виробами, а також спеціалізоване чищення, санітарне оброблення та відновлення пір’яних подушок. || Компанія працює за циркулярною бізнес-моделлю, орієнтованою на «продукт як послугу», створюючи цінність завдяки професійному догляду за текстильними виробами, а не лише завдяки продажу нової продукції. За договорами на надання послуг UNFLORIA бере на себе прання, чищення, санітарне оброблення та догляд за текстильними виробами, якими користуються її клієнти. Вироби обробляють відповідно до характеристик матеріалу та вимог щодо догляду, після чого повертають клієнтам гігієнічно чистими, у належному стані та придатними для подальшого використання. || Передавання цих послуг спеціалізованому постачальнику дає компаніям і державним установам змогу уникнути або скоротити обсяг ресурсів, необхідних для організації власної пральні, зокрема інвестиції в обладнання для прання та сушіння, споживання енергії та води, витрати на мийні засоби й технічне обслуговування, а також витрати на утримання спеціалізованого персоналу. Водночас клієнти отримують професійно очищені текстильні вироби, що відповідають високим стандартам гігієни та якості. Належний догляд допомагає зберігати структуру, зовнішній вигляд і функціональність текстильних виробів, продовжуючи термін їхньої експлуатації та зменшуючи частоту їх заміни й пов’язані з цим витрати. || Чищення, санітарне оброблення та відновлення пір’яних подушок мають особливе значення для циркулярності. Наявні подушки та їхній натуральний наповнювач відновлюють для подальшого використання, замість того щоб передчасно викидати їх і замінювати новими. || UNFLORIA повідомляє про використання біорозкладних мийних засобів і розчинників, а також про використання сонячної енергії у своїй діяльності. Ці практики доповнюють сервісну модель, зменшуючи вплив догляду за текстильними виробами на довкілля. || Цей приклад демонструє, як спеціалізовані централізовані послуги з догляду за текстильними виробами можуть створювати економічні переваги для клієнтів, водночас сповільнюючи споживання текстилю та утворення відходів. Поєднуючи професійний догляд, якісне санітарне оброблення, ресурсоефективне надання послуг і відновлення подушок, UNFLORIA допомагає довше зберігати текстильні вироби функціональними та придатними до використання.",ro:"UNFLORIA SRL este o firmă de servicii textile cu sediul în Ungheni care oferă servicii profesionale de spălătorie, curățătorie ecologică și întreținere textile companiilor private, instituțiilor publice și clienților persoane fizice. Activitățile sale includ spălarea și îngrijirea articolelor de îmbrăcăminte, lenjerie, îmbrăcăminte de lucru, tricotaje, covoare și alte textile de uz casnic sau instituțional, precum și curățarea, igienizarea și restaurarea de specialitate a pernelor din pene. || Compania operează printr-un model de afaceri circular orientat spre produs ca serviciu, generând valoare prin îngrijirea profesională a textilelor, mai degrabă decât să se bazeze exclusiv pe vânzarea de produse noi. Prin contracte de servicii, UNFLORIA își asumă responsabilitatea pentru spălarea, curățarea, igienizarea și întreținerea textilelor folosite de clienții săi. Produsele sunt tratate în funcție de caracteristicile lor materiale și de cerințele de îngrijire și se returnează igienizate, în stare bună și adecvate pentru utilizare în continuare. || Externalizarea acestor activități către un furnizor specializat permite companiilor și instituțiilor publice să evite sau să reducă resursele necesare unei spălătorii interne, inclusiv investiții în echipamente de spălat și uscare, consum de energie și apă, detergenți, costuri de întreținere și personal dedicat. În același timp, clienții beneficiază de textile curățate profesional, care îndeplinesc standarde ridicate de igienă și calitate. Tratamentul adecvat ajută la păstrarea structurii, aspectului și funcționalității textilelor, prelungind durata de viață a produsului și reducând frecvența înlocuirii și cheltuielile aferente. || Curățarea, igienizarea și restaurarea pernelor din pene sunt deosebit de relevante pentru circularitate. Pernele existente și umplutura lor naturală sunt recuperate și restaurate pentru utilizare continuă, în loc să fie aruncate prematur și înlocuite. || UNFLORIA raportează că folosește detergenți și solvenți biodegradabili și integrează energia solară în operațiunile sale. Aceste practici completează modelul de servicii prin reducerea impactului asupra mediului al întreținerii textilelor. || Cazul demonstrează modul în care serviciile specializate și centralizate de îngrijire a textilelor pot crea beneficii economice pentru clienți, încetinind în același timp consumul de textile și generarea de deșeuri. Combinând întreținerea profesională, igienizarea de înaltă calitate, livrarea de servicii eficientă din punct de vedere al resurselor și restaurarea pernelor, UNFLORIA ajută la menținerea produselor textile funcționale și utilizate pentru mai mult timp.",hy:"UNFLORIA SRL-ը տեքստիլ ծառայություններ մատուցող ընկերություն է, որը հիմնված է Ունհենիում, որը մատուցում է պրոֆեսիոնալ լվացք, էկոլոգիական քիմմաքրում և տեքստիլի տեխնիկական սպասարկում մասնավոր ընկերություններին, հանրային հաստատություններին և անհատ հաճախորդներին: Նրա գործունեությունը ներառում է հագուստի, սպիտակեղենի, աշխատանքային հագուստի, տրիկոտաժի, գորգերի և այլ կենցաղային կամ ինստիտուցիոնալ գործվածքների լվացում և խնամք, ինչպես նաև փետուրների բարձերի մասնագիտացված մաքրում, ախտահանում և վերականգնում։ || Ընկերությունը գործում է ապրանքը որպես ծառայություն ուղղված շրջանաձև բիզնես մոդելի միջոցով, որն արժեք է ստեղծում տեքստիլի պրոֆեսիոնալ խնամքի միջոցով, այլ ոչ թե հիմնվելով բացառապես նոր ապրանքների վաճառքի վրա: Ծառայությունների պայմանագրերի միջոցով UNFLORIA-ն պատասխանատվություն է կրում իր հաճախորդների կողմից օգտագործվող տեքստիլի լվացման, մաքրման, ախտահանման և պահպանման համար: Ապրանքները մշակվում են ըստ իրենց նյութական բնութագրերի և խնամքի պահանջների և վերադարձվում են հիգիենիկ, լավ վիճակում և պիտանի շարունակական օգտագործման համար։ || Այս գործողությունների աութսորսինգը մասնագիտացված մատակարարին հնարավորություն է տալիս ընկերություններին և հանրային հաստատություններին խուսափել կամ նվազեցնել ներքին լվացքի համար պահանջվող ռեսուրսները, ներառյալ ներդրումները լվացքի և չորացման սարքավորումների, էներգիայի և ջրի սպառման, լվացող միջոցների, պահպանման ծախսերի և նվիրված անձնակազմի մեջ: Միևնույն ժամանակ, հաճախորդները օգտվում են պրոֆեսիոնալ մաքրված տեքստիլից, որը համապատասխանում է բարձր հիգիենայի և որակի չափանիշներին: Համապատասխան բուժումը օգնում է պահպանել տեքստիլի կառուցվածքը, տեսքը և գործունակությունը, երկարացնելով արտադրանքի ժամկետը և նվազեցնելով փոխարինման հաճախականությունը և հարակից ծախսերը։ || Փետրավոր բարձերի մաքրումը, ախտահանումը և վերականգնումը հատկապես կարևոր է շրջանաձևության համար: Առկա բարձերը և դրանց բնական լցոնումը վերականգնվում և վերականգնվում են շարունակական օգտագործման համար՝ ժամանակից շուտ դեն նետվելու և փոխարինելու փոխարեն։ || UNFLORIA-ն հաղորդում է, որ օգտագործում է կենսաքայքայվող լվացող միջոցներ և լուծիչներ և ինտեգրում է արևային էներգիան իր գործունեության մեջ: Այս գործելակերպերը լրացնում են սպասարկման մոդելը՝ նվազեցնելով տեքստիլի պահպանման ազդեցությունը շրջակա միջավայրի վրա։ || Օրինակը ցույց է տալիս, թե ինչպես տեքստիլի խնամքի մասնագիտացված և կենտրոնացված ծառայությունները կարող են տնտեսական օգուտներ ստեղծել հաճախորդների համար՝ միաժամանակ դանդաղեցնելով տեքստիլի սպառումը և թափոնների արտադրությունը: Համատեղելով պրոֆեսիոնալ սպասարկումը, բարձրորակ ախտահանումը, ռեսուրսաարդյունավետ ծառայությունների մատուցումը և բարձի վերականգնումը, UNFLORIA-ն օգնում է տեքստիլ արտադրանքը պահել գործունակ և երկար ժամանակ օգտագործելու համար։"},caseLink:"https://unfloria.md/",image:"/images/cases/moldova/unfloria-srl.webp",imageAlt:{en:"Unfloria SRL case image",uk:"Зображення корпусу Unfloria SRL",ro:"Imagine caz Unfloria SRL",hy:"Unfloria SRL գործի պատկեր"}}),e({id:"case-007",slug:"by-botany",companyName:{en:"By Botany",uk:"",ro:"",hy:""},country:"Armenia",sector:["Textiles"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Fibrous plant material (nettle) is processed into a new raw textile input, substituting virgin cotton or synthetic fiber inputs in garment manufacturing.",uk:"Волокнисту рослинну сировину – кропиву – переробляють на нову текстильну сировину, замінюючи первинну бавовну або синтетичні волокна у виробництві одягу.",ro:"Materialul vegetal fibros (urzica) este procesat într-un nou input textil brut, înlocuind inputurile de bumbac virgin sau fibre sintetice în fabricarea confecțiilor.",hy:"Մանրաթելային բուսանյութը (եղինջը) վերամշակվում է նոր հումքի տեքստիլի ներմուծման մեջ՝ փոխարինելով կույս բամբակը կամ սինթետիկ մանրաթելերը հագուստի արտադրության մեջ։"},summary:{en:"By Botany is developing Armenia's first domestically produced textile fiber from nettle plants, offering a sustainable, low-impact alternative to conventional cotton and synthetic fibers for the fashion industry.",uk:"Компанія By Botany створює перше у Вірменії текстильне волокно власного виробництва із кропиви, пропонуючи індустрії моди екологічну альтернативу традиційній бавовні та синтетичним волокнам із низьким впливом на довкілля.",ro:"By Botany dezvoltă prima fibră textilă din Armenia produsă pe plan intern din plante de urzică, oferind o alternativă durabilă, cu impact redus, la bumbacul convențional și fibrele sintetice pentru industria modei.",hy:"By Botany-ը մշակում է Հայաստանում առաջին տեղական արտադրության տեքստիլ մանրաթելը՝ եղինջի բույսերից՝ առաջարկելով կայուն, ցածր ազդեցության այլընտրանք սովորական բամբակի և սինթետիկ մանրաթելերին նորաձևության արդյունաբերության համար։"},description:{en:"By Botany is an Armenian circular startup working to establish the country's first locally sourced nettle-fiber textile supply chain. Nettle, a resilient plant requiring minimal irrigation, pesticides, or chemical treatment compared to cotton, is processed into spinnable fiber suitable for sustainable fashion products. By building out this value chain domestically, the company aims to reduce Armenia's reliance on imported textile fibers while offering designers and brands a lower-impact input material. The venture was supported through the CirculUP! circular startup grant programme, which backs early-stage Armenian businesses developing circular economy solutions. This case illustrates how novel bio-based feedstocks can be substituted for resource-intensive materials within an established industry.",uk:"By Botany – вірменський циркулярний стартап, який працює над створенням першого в країні ланцюга постачання текстильного волокна з кропиви місцевого виробництва. Кропива – витривала рослина, яка порівняно з бавовною потребує мінімального зрошення, використання пестицидів і хімічного оброблення. Її переробляють на волокно, придатне для прядіння та використання у виробництві екологічніших модних виробів. Розбудовуючи цей ланцюг створення вартості всередині країни, компанія прагне зменшити залежність Вірменії від імпортного текстильного волокна та запропонувати дизайнерам і брендам сировину з меншим впливом на довкілля. Проєкт отримав підтримку в межах грантової програми CirculUP! для циркулярних стартапів, яка підтримує вірменські компанії на ранніх етапах розвитку, що розробляють рішення для циркулярної економіки. Цей приклад демонструє, як нові види біосировини можуть замінювати ресурсоємні матеріали в межах уже сформованої галузі.",ro:"By Botany este un startup circular armean care lucrează pentru a stabili primul lanț de aprovizionare cu fibre de urzică din țară din surse locale. Urzica, o plantă rezistentă care necesită irigare minimă, pesticide sau tratament chimic în comparație cu bumbacul, este procesată în fibre filabile potrivite pentru produse de modă durabile. Prin construirea acestui lanț valoric pe plan intern, compania își propune să reducă dependența Armeniei de fibrele textile importate, oferind în același timp designerilor și mărcilor un material de intrare cu impact mai redus. Aventura a fost susținută prin intermediul CirculUP! Programul de granturi pentru pornire circulară, care sprijină întreprinderile armene în stadiu incipient care dezvoltă soluții de economie circulară. Acest caz ilustrează modul în care materiile prime noi pe bază de bio pot fi înlocuite cu materialele mari consumatoare de resurse într-o industrie consacrată.",hy:"By Botany-ը հայկական շրջանաձև ստարտափ է, որն աշխատում է երկրում եղինջի մանրաթելից տեքստիլ մատակարարման առաջին ցանցը ստեղծելու ուղղությամբ: Եղինջը` ճկուն բույս, որը պահանջում է նվազագույն ոռոգում, թունաքիմիկատներ կամ քիմիական մշակում` համեմատած բամբակի հետ, վերամշակվում է մանվող մանրաթելի վերածվում է կայուն նորաձևության արտադրանքի համար: Կառուցելով այս արժեքային շղթան ներքին շուկայում՝ ընկերությունը նպատակ ունի նվազեցնել Հայաստանի կախվածությունը ներմուծվող տեքստիլ մանրաթելերից՝ միաժամանակ դիզայներներին և բրենդներին առաջարկելով ավելի քիչ ազդեցություն ունեցող մուտքային նյութ: Ձեռնարկությունն ապահովվել է CirculUP-ի միջոցով: շրջանաձև ստարտափների դրամաշնորհային ծրագիր, որն աջակցում է վաղ փուլի հայկական բիզնեսներին, որոնք մշակում են շրջանաձև տնտեսության լուծումներ: Այս դեպքը ցույց է տալիս, թե ինչպես կարելի է նոր կենսաբանական հումքը փոխարինել ռեսուրսների ինտենսիվ նյութերով ստեղծված արդյունաբերության մեջ։"},caseLink:"https://bybotany.am"}),e({id:"case-009",slug:"the-rug-code",companyName:{en:"The Rug Code",uk:"",ro:"",hy:""},country:"Armenia",sector:["Textiles"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Zero-waste weaving practices and local wool sourcing minimise material losses and reduce reliance on long-distance, resource-intensive wool supply chains.",uk:"Безвідходні практики ткацтва та використання місцевої вовни мінімізують втрати сировини й зменшують залежність від ресурсомістких ланцюгів постачання вовни на великі відстані.",ro:"Practicile de țesut fără deșeuri și aprovizionarea locală cu lână reduc la minimum pierderile de materiale și reduc dependența de lanțurile de aprovizionare cu lână pe distanțe lungi și consumatoare de resurse.",hy:"Զրոյական թափոնների հյուսման պրակտիկան և բրդի տեղական մատակարարումը նվազագույնի են հասցնում նյութական կորուստները և նվազեցնում կախվածությունը հեռավոր, ռեսուրսներ պահանջող բրդի մատակարարման շղթայից։"},summary:{en:"The Rug Code revives traditional Armenian rug weaving techniques using a zero-waste production approach and locally sourced wool, combining cultural heritage preservation with circular material practices.",uk:"The Rug Code відроджує традиційні вірменські техніки килимарства, використовуючи безвідходний підхід до виробництва та вовну місцевого походження, поєднуючи збереження культурної спадщини з практиками циркулярного використання матеріалів.",ro:"Codul covoarelor reînvie tehnicile tradiționale de țesut a covoarelor armenești, folosind o abordare de producție fără deșeuri și lână de proveniență locală, combinând conservarea patrimoniului cultural cu practicile materiale circulare.",hy:"Գորգերի օրենսգիրքը վերակենդանացնում է հայկական ավանդական գորգագործության տեխնիկան՝ օգտագործելով զրոյական թափոնների արտադրության մոտեցումը և տեղական ծագման բուրդը՝ համատեղելով մշակութային ժառանգության պահպանումը շրջանաձև նյութական պրակտիկայի հետ։"},description:{en:"The Rug Code combines Armenia's centuries-old rug-weaving tradition with modern zero-waste design principles. By sourcing wool locally and designing production processes to minimise offcuts and material loss, the business reduces the resource footprint typically associated with textile and rug manufacturing. The model also supports local wool producers and traditional artisans, linking economic and cultural sustainability with resource efficiency. This case shows how heritage crafts can be repositioned as circular economy businesses by tightening material sourcing and minimising waste at the production stage, rather than relying on end-of-life recycling.",uk:"The Rug Code поєднує багатовікову вірменську традицію килимарства із сучасними принципами безвідходного дизайну. Використовуючи вовну місцевого походження та організовуючи виробничі процеси так, щоб мінімізувати обрізки й втрати матеріалу, компанія зменшує ресурсний вплив, типовий для виробництва текстилю та килимів. Така модель також підтримує місцевих виробників вовни й традиційних майстрів, поєднуючи економічну та культурну сталість із ресурсоефективністю. Цей приклад демонструє, як традиційні ремесла можуть розвиватися як бізнеси циркулярної економіки завдяки оптимізації постачання матеріалів і мінімізації відходів уже на етапі виробництва, а не завдяки переробленню виробів після завершення їхнього терміну експлуатації.",ro:"Codul de covoare combină tradiția de secole de țesut de covoare a Armeniei cu principiile moderne de design fără deșeuri. Prin aprovizionarea cu lână la nivel local și prin proiectarea proceselor de producție pentru a minimiza tăieturile și pierderile de materiale, afacerea reduce amprenta resurselor asociată în mod obișnuit cu producția de textile și covoare. Modelul sprijină, de asemenea, producătorii locali de lână și artizanii tradiționali, legând sustenabilitatea economică și culturală cu eficiența resurselor. Acest caz arată modul în care meșteșugurile de patrimoniu pot fi repoziționate ca afaceri ale economiei circulare prin restrângerea aprovizionării cu materiale și minimizarea deșeurilor în etapa de producție, mai degrabă decât bazându-se pe reciclarea la sfârșitul vieții.",hy:"Գորգերի օրենսգիրքը համատեղում է Հայաստանի դարավոր գորգագործության ավանդույթը և ժամանակակից զրոյական թափոնների դիզայնի սկզբունքները: Տեղական բուրդ հայթայթելով և արտադրական գործընթացներ նախագծելով՝ կրճատումներն ու նյութական կորուստները նվազագույնի հասցնելու համար, բիզնեսը նվազեցնում է ռեսուրսների հետքը, որը սովորաբար կապված է տեքստիլի և գորգերի արտադրության հետ: Մոդելը նաև աջակցում է բրդի տեղական արտադրողներին և ավանդական արհեստավորներին՝ կապելով տնտեսական և մշակութային կայունությունը ռեսուրսների արդյունավետության հետ: Այս դեպքը ցույց է տալիս, թե ինչպես ժառանգական արհեստները կարող են վերադիրքավորվել որպես շրջանաձև տնտեսության բիզնեսներ՝ խստացնելով նյութերի մատակարարումը և նվազագույնի հասցնելով թափոնները արտադրության փուլում, այլ ոչ թե հենվելով կյանքի վերջում վերամշակման վրա։"},caseLink:"https://therugcode.com"}),e({id:"case-010",slug:"permaculture-in-armenia",companyName:{en:"Permaculture in Armenia",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Regenerative, closed-loop agricultural design reduces the need for external inputs (synthetic fertilizer, irrigation) by working with natural ecosystem cycles.",uk:"Регенеративне сільське господарство із замкненими циклами зменшує потребу у зовнішніх ресурсах – синтетичних добривах та зрошенні – завдяки використанню природних екосистемних циклів.",ro:"Proiectarea agricolă regenerativă, în buclă închisă, reduce nevoia de aporturi externe (îngrășăminte sintetice, irigații) prin lucrul cu ciclurile ecosistemelor naturale.",hy:"Վերականգնողական, փակ շրջանով գյուղատնտեսական դիզայնը նվազեցնում է արտաքին միջոցների կարիքը (սինթետիկ պարարտանյութ, ոռոգում)՝ աշխատելով բնական էկոհամակարգի ցիկլերի հետ։"},summary:{en:"This initiative establishes food forests in the community of Berdavan using regenerative agriculture techniques that restore soil health, increase biodiversity, and create long-term, low-input food production systems.",uk:"Ця ініціатива створює продовольчі ліси в громаді Бердаван, використовуючи методи регенеративного сільського господарства, які відновлюють родючість ґрунтів, підвищують біорізноманіття та формують довгострокові системи виробництва продуктів харчування з низьким рівнем витрат ресурсів.",ro:"Această inițiativă înființează păduri alimentare în comunitatea Berdavan folosind tehnici de agricultură regenerativă care restabilesc sănătatea solului, cresc biodiversitatea și creează sisteme de producție alimentară pe termen lung, cu aport redus.",hy:"Այս նախաձեռնությամբ Բերդավան համայնքում հիմնվում են պարենային անտառներ՝ օգտագործելով վերականգնողական գյուղատնտեսության մեթոդները, որոնք վերականգնում են հողի առողջությունը, բարձրացնում կենսաբազմազանությունը և ստեղծում սննդամթերքի արտադրության երկարաժամկետ, ցածր ներդրումային համակարգեր։"},description:{en:"This project applies permaculture design principles to establish food forests in Berdavan, a rural Armenian community. Food forests are multi-layered planting systems that mimic natural ecosystems, combining fruit and nut trees, shrubs, and ground cover crops to produce food with minimal external inputs once established. Compared to conventional agriculture, the approach reduces dependency on synthetic fertilizers, irrigation, and other external inputs over time, while improving soil health and local biodiversity. The initiative was featured as a CirculUP! grantee case, highlighting how regenerative land-use models can be integrated into Armenia's circular economy transition, particularly in rural and agricultural contexts.",uk:"Цей проєкт застосовує принципи пермакультурного дизайну для створення продовольчих лісів у Бердавані – сільській громаді Вірменії. Продовольчі ліси –це багатоярусні системи вирощування, що імітують природні екосистеми та поєднують плодові й горіхові дерева, чагарники та ґрунтопокривні культури для виробництва харчових продуктів із мінімальним використанням зовнішніх ресурсів після формування системи. Порівняно з традиційним сільським господарством такий підхід із часом зменшує залежність від синтетичних добрив, зрошення та інших зовнішніх ресурсів, водночас покращуючи стан ґрунтів і місцеве біорізноманіття. Ініціативу представлено як приклад отримувача гранту CirculUP!, що демонструє, як регенеративні моделі землекористування можуть інтегруватися у перехід Вірменії до циркулярної економіки, зокрема в сільських і аграрних громадах.",ro:"Acest proiect aplică principiile de proiectare a permaculturii pentru a stabili păduri alimentare în Berdavan, o comunitate rurală armeană. Pădurile alimentare sunt sisteme de plantare cu mai multe straturi care imită ecosistemele naturale, combinând pomi fructiferi și nuci, arbuști și culturi de acoperire a solului pentru a produce hrană cu inputuri externe minime odată stabilite. În comparație cu agricultura convențională, abordarea reduce dependența de îngrășăminte sintetice, irigare și alte inputuri externe în timp, îmbunătățind în același timp sănătatea solului și biodiversitatea locală. Inițiativa a fost prezentată ca CirculUP! cazul beneficiarului, evidențiind modul în care modelele regenerative de utilizare a terenurilor pot fi integrate în tranziția către economia circulară a Armeniei, în special în contexte rurale și agricole.",hy:"Այս նախագիծը կիրառում է պերմակուլտուրայի նախագծման սկզբունքները` Բերդավան գյուղական հայկական համայնքում սննդի անտառներ հիմնելու համար: Սննդի անտառները բազմաշերտ տնկման համակարգեր են, որոնք ընդօրինակում են բնական էկոհամակարգերը՝ միավորելով պտղատու և ընկուզենի ծառերը, թփերը և գետնածածկ մշակաբույսերը՝ հաստատվելուց հետո նվազագույն արտաքին միջոցներով սնունդ արտադրելու համար: Համեմատած սովորական գյուղատնտեսության հետ՝ մոտեցումը ժամանակի ընթացքում նվազեցնում է կախվածությունը սինթետիկ պարարտանյութերից, ոռոգումից և այլ արտաքին միջոցներից՝ միաժամանակ բարելավելով հողի առողջությունը և տեղական կենսաբազմազանությունը: Նախաձեռնությունը ներկայացվել է որպես CirculUP! դրամաշնորհառուի գործը, որն ընդգծում է, թե ինչպես կարող են վերականգնող հողօգտագործման մոդելները ինտեգրվել Հայաստանի շրջանաձև տնտեսության անցումային փուլին, հատկապես գյուղական և գյուղատնտեսական համատեքստերում։"},caseLink:"https://circulup.am/2025/03/31/permaculture-in-armenia"}),e({id:"case-011",slug:"bio-oil-llc",companyName:{en:"Bio Oil LLC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Waste Management"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Used cooking oil, a hazardous waste stream if disposed of improperly, is chemically reprocessed into biodiesel, substituting fossil-derived diesel fuel.",uk:"Використану кулінарну олію, яка в разі неналежного поводження становить небезпечний потік відходів, хімічно переробляють на біодизель, замінюючи дизельне паливо з викопної сировини.",ro:"Uleiul de gătit uzat, un flux de deșeuri periculoase, dacă este eliminat în mod necorespunzător, este reprocesat chimic în biomotorină, înlocuind motorina derivată din fosile.",hy:"Օգտագործված ճաշ պատրաստելու յուղը, որը վտանգավոր թափոնների հոսք է, եթե ոչ պատշաճ կերպով հեռացվի, քիմիապես վերամշակվում է բիոդիզել՝ փոխարինելով հանածոներից ստացված դիզելային վառելիքը։"},summary:{en:"Bio Oil LLC transforms used cooking oil collected from households and food businesses into biodiesel, operating Armenia's first EU-certified recycling system for this waste stream.",uk:"Bio Oil LLC перетворює відпрацьовану кулінарну олію, зібрану в домогосподарств і закладів харчування, на біодизель, забезпечуючи роботу першої у Вірменії сертифікованої за стандартами ЄС системи перероблення цього типу відходів.",ro:"Bio Oil LLC transformă uleiul de gătit uzat colectat de la gospodării și întreprinderile alimentare în biomotorină, utilizând primul sistem de reciclare certificat de UE din Armenia pentru acest flux de deșeuri.",hy:"«Բիո Օյլ» ՍՊԸ-ն տնային տնտեսություններից և սննդի ձեռնարկություններից հավաքված օգտագործված յուղը վերածում է բիոդիզելի՝ գործարկելով այս թափոնների հոսքի վերամշակման առաջին համակարգը ԵՄ կողմից վավերացված Հայաստանում։"},description:{en:"Bio Oil LLC addresses the environmental risks posed by improperly discarded cooking oil, which can contaminate water systems and clog municipal infrastructure. The company has established Armenia's first EU-certified collection and recycling system for used cooking oil, gathering the waste from households, restaurants, and other food-service businesses. The collected oil is processed into biodiesel, a renewable fuel that can substitute for conventional diesel in various applications. This creates both an environmental benefit, by keeping a hazardous waste stream out of the environment, and an economic one, by generating a marketable fuel product. The case was recognised as a CirculUP! grantee for demonstrating a scalable circular solution to an underserved waste stream.",uk:"Bio Oil LLC працює над екологічними ризиками, пов’язаними з неналежним поводженням із використаною кулінарною олією, яка може забруднювати водні системи та спричиняти засмічення міської інфраструктури. Компанія створила першу у Вірменії сертифіковану ЄС систему збирання та перероблення використаної кулінарної олії, збираючи її в домогосподарствах, ресторанах та інших закладах харчування. Зібрану олію переробляють на біодизель – відновлюване паливо, яке може замінювати звичайне дизельне паливо в різних сферах застосування. Це створює екологічні переваги завдяки тому, що небезпечний потік відходів не потрапляє у довкілля, а також економічні – завдяки виробництву пального, яке можна реалізовувати на ринку. Цей приклад отримав підтримку в межах CirculUP! як приклад масштабованого циркулярного рішення для недостатньо охопленого системами збирання та перероблення потоку відходів.",ro:"Bio Oil LLC abordează riscurile de mediu prezentate de uleiul de gătit aruncat în mod necorespunzător, care poate contamina sistemele de apă și poate înfunda infrastructura municipală. Compania a creat primul sistem de colectare și reciclare certificat de UE din Armenia pentru uleiul de gătit uzat, colectând deșeurile din gospodării, restaurante și alte întreprinderi de servicii alimentare. Uleiul colectat este procesat în biodiesel, un combustibil regenerabil care poate înlocui motorina convențională în diverse aplicații. Acest lucru creează atât un beneficiu de mediu, prin menținerea unui flux de deșeuri periculoase în afara mediului, cât și unul economic, prin generarea unui produs combustibil comercializabil. Cazul a fost recunoscut drept CirculUP! beneficiar pentru demonstrarea unei soluții circulare scalabile pentru un flux de deșeuri insuficient deservit.",hy:"«Բիո Օյլ» ՍՊԸ-ն անդրադառնում է անպատշաճ կերպով դեն նետված պատրաստման յուղից բխող բնապահպանական ռիսկերին, որոնք կարող են աղտոտել ջրային համակարգերը և խցանել քաղաքային ենթակառուցվածքները: Ընկերությունը ստեղծել է Հայաստանում ԵՄ կողմից վավերացված առաջին համակարգը՝ օգտագործված կերակուրի յուղի, տնային տնտեսություններից, ռեստորաններից և սննդի ծառայություններ մատուցող այլ ձեռնարկություններից թափոնների հավաքման համար: Հավաքված յուղը վերամշակվում է բիոդիզելի՝ վերականգնվող վառելիքի, որը կարող է փոխարինել սովորական դիզելին տարբեր կիրառություններում: Սա ստեղծում է և՛ բնապահպանական օգուտ՝ վտանգավոր թափոնների հոսքը շրջակա միջավայրից հեռու պահելով, և՛ տնտեսական՝ արտադրելով շուկայական վառելիքի արտադրանք: Գործը ճանաչվել է որպես CirculUP! դրամաշնորհառու՝ թերսպասարկվող թափոնների հոսքի մասշտաբային շրջանաձև լուծում ցուցադրելու համար։"},caseLink:"https://circulup.am/2025/03/31/bio-oil-llc"}),e({id:"case-013",slug:"biohumus-production",companyName:{en:"Biohumus Production",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Agricultural organic waste is biologically converted (vermicomposting) into a fertilizer product, returning nutrients to agricultural use and substituting synthetic fertilizer inputs.",uk:"Сільськогосподарські органічні відходи біологічно перетворюються (вермікомпостування) на добриво, повертаючи поживні речовини для сільськогосподарського використання та замінюючи синтетичні добрива.",ro:"Deșeurile organice agricole sunt transformate biologic (vermicompostare) într-un produs fertilizator, returnând nutrienții utilizării agricole și înlocuind inputurile de îngrășăminte sintetice.",hy:"Գյուղատնտեսական օրգանական թափոնները կենսաբանորեն վերածվում են պարարտանյութի (վերմիկոմպոստավորում)՝ վերադարձնելով սննդանյութերը գյուղատնտեսական օգտագործմանը և փոխարինելով սինթետիկ պարարտանյութերի մուտքերը։"},summary:{en:"This business produces organic fertilizer from agricultural waste through vermicomposting, a biological process using worms to break down organic material into nutrient-rich compost.",uk:"Цей бізнес виробляє органічні добрива із сільськогосподарських відходів шляхом вермікомпостування, біологічного процесу, використовуючи черв’яків для розщеплення органічних матеріалів у багатий поживними речовинами компост.",ro:"Această afacere produce îngrășăminte organice din deșeuri agricole prin vermicompostare, un proces biologic care utilizează viermi pentru a descompune materialul organic în compost bogat în nutrienți.",hy:"Այս բիզնեսը օրգանական պարարտանյութ է արտադրում գյուղատնտեսական թափոններից՝ վերմիկոմպոստավորման միջոցով՝ կենսաբանական գործընթաց, որն օգտագործում է որդերը՝ օրգանական նյութերը տարրալուծելու համար սննդանյութերով հարուստ պարարտանյութի։"},description:{en:"Based in the village of Sers, this venture uses vermicomposting — a controlled biological process in which worms digest organic agricultural waste — to produce biohumus, a high-quality organic fertilizer. This approach diverts agricultural residues from disposal or burning and converts them into a marketable soil amendment that can replace synthetic fertilizers for local farmers. Vermicomposting requires relatively low capital investment and can be scaled to match available waste volumes, making it well suited to rural Armenian agricultural communities. The initiative was supported as a CirculUP! grantee, reflecting the broader push to close nutrient loops within Armenia's agricultural sector.",uk:"Це підприємство, розташоване в селі Серс, використовує вермікомпостування – контрольований біологічний процес, під час якого черви перетравлюють органічні сільськогосподарські відходи, – для виробництва біогумусу, високоякісного органічного добрива. Такий підхід дає змогу уникати захоронення чи спалювання сільськогосподарських решток та перетворювати їх на ґрунтополіпшувач, який можна реалізовувати на ринку та використовувати місцевим фермерам замість синтетичних добрив. Вермікомпостування потребує відносно невеликих капіталовкладень і може масштабуватися відповідно до доступних обсягів відходів, що робить цей підхід придатним для сільських аграрних громад Вірменії. Ініціативу підтримано в межах CirculUP! як отримувача гранту, що відображає ширші зусилля, спрямовані на замкнення циклів поживних речовин у сільськогосподарському секторі Вірменії.",ro:"Cu sediul în satul Sers, această întreprindere folosește vermicompostarea - un proces biologic controlat în care viermii digeră deșeurile agricole organice - pentru a produce biohumus, un îngrășământ organic de înaltă calitate. Această abordare deturnează reziduurile agricole de la eliminare sau ardere și le transformă într-un amendament de sol comercializabil care poate înlocui îngrășămintele sintetice pentru fermierii locali. Vermicompostarea necesită investiții de capital relativ scăzute și poate fi scalată pentru a se potrivi cu volumele disponibile de deșeuri, făcându-l bine potrivit comunităților agricole armene rurale. Inițiativa a fost susținută ca CirculUP! beneficiar, reflectând eforturile mai ample de a închide buclele de nutrienți în sectorul agricol al Armeniei.",hy:"Սերս գյուղում հիմնված այս ձեռնարկությունը օգտագործում է վերմիկոմպոստինգ՝ վերահսկվող կենսաբանական գործընթաց, որի ընթացքում որդերը մարսում են օրգանական գյուղատնտեսական թափոնները՝ կենսահումուս՝ բարձրորակ օրգանական պարարտանյութ արտադրելու համար: Այս մոտեցումը շեղում է գյուղատնտեսական մնացորդները հեռացումից կամ այրումից և վերածում դրանք շուկայական հողի փոփոխման, որը կարող է փոխարինել սինթետիկ պարարտանյութերին տեղական ֆերմերների համար: Վերմիկոմպոստավորումը պահանջում է համեմատաբար ցածր կապիտալ ներդրումներ և կարող է մասշտաբավորվել՝ համապատասխանեցնելով առկա թափոնների ծավալներին՝ այն լավ հարմարեցնելով Հայաստանի գյուղական գյուղատնտեսական համայնքներին: Նախաձեռնությունը աջակցվեց որպես CirculUP! դրամաշնորհառու, որն արտացոլում է Հայաստանի գյուղատնտեսության ոլորտում սննդանյութերի օղակները փակելու ավելի լայն մղումը։"},caseLink:"https://www.facebook.com/people/Sers-village/100066974256776/"}),e({id:"case-014",slug:"baby-gear-armenia",companyName:{en:"Baby Gear Armenia",uk:"",ro:"",hy:""},country:"Armenia",sector:["Retail"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"A product-as-a-service rental model reduces the total volume of baby equipment manufactured and purchased by enabling shared, repeated use of the same items across multiple users.",uk:"Модель «продукт як послуга» на основі оренди зменшує загальний обсяг виробництва та придбання дитячого спорядження, оскільки одні й ті самі речі можуть багаторазово використовуватися різними користувачами.",ro:"Un model de închiriere de produs ca serviciu reduce volumul total de echipamente pentru bebeluși produse și achiziționate, permițând utilizarea partajată și repetată a acelorași articole pentru mai mulți utilizatori.",hy:"«Ապրանք որպես ծառայություն» վարձակալության մոդելը նվազեցնում է արտադրված և գնված մանկական սարքավորումների ընդհանուր ծավալը՝ մի քանի օգտատերերի միջև միևնույն ապրանքների կրկնակի օգտագործման հնարավորություն տալով։"},summary:{en:"Baby Gear Armenia offers a circular equipment rental service for traveling families, providing cribs, strollers, car seats, and other baby gear on a temporary-use basis rather than requiring purchase.",uk:"Baby Gear Armenia пропонує циркулярну послугу оренди дитячого спорядження для сімей, які подорожують, – ліжечок, візочків, автокрісел та іншого дитячого приладдя на тимчасове користування, тож купувати ці речі не потрібно.",ro:"Baby Gear Armenia oferă un serviciu de închiriere de echipamente circulare pentru familiile care călătoresc, oferind pătuțuri, cărucioare, scaune pentru mașină și alte echipamente pentru bebeluși pe o bază temporară, în loc să necesite cumpărare.",hy:"Baby Gear Armenia-ն առաջարկում է սարքավորումների վարձույթի շրջանաձև ծառայություն շրջագայող ընտանիքների համար՝ տրամադրելով օրորոցներ, մանկասայլակներ, մեքենայի նստատեղեր և այլ մանկական պարագաներ ժամանակավոր օգտագործման հիմունքներով, այլ ոչ թե գնելու պահանջով։"},description:{en:"Baby Gear Armenia operates a rental service that allows traveling parents to hire baby equipment — such as cribs, strollers, and car seats — for the duration of their stay, rather than purchasing or transporting their own. This product-as-a-service model extends the useful life of each item by enabling repeated use across many families instead of single-household ownership, reducing the overall volume of baby gear that needs to be manufactured. It also removes the burden and cost for traveling families of transporting or buying bulky, short-term-use items. The business was recognised as a CirculUP! grantee for applying access-over-ownership principles to a high-turnover consumer product category.",uk:"Baby Gear Armenia надає послуги оренди, завдяки яким батьки, що подорожують, можуть орендувати дитяче спорядження – зокрема ліжечка, візочки та автокрісла – на весь період перебування замість того, щоб купувати або перевозити власне спорядження. Така модель «продукт як послуга» продовжує термін експлуатації кожного виробу, оскільки ним можуть послідовно користуватися багато сімей, замість того щоб він перебував у власності однієї сім’ї, і в такий спосіб зменшує загальний обсяг дитячого спорядження, яке потрібно виробляти. Вона також позбавляє сім’ї, які подорожують, необхідності перевозити із собою або купувати громіздке дитяче спорядження, яке потрібне лише на короткий час, заощаджуючи їхні кошти та звільняючи від зайвих клопотів. Бізнес отримав грантову підтримку в межах CirculUP! за застосування принципу доступу до продукту замість володіння ним у сфері споживчих товарів, які мають короткий термін використання та часто замінюються.",ro:"Baby Gear Armenia operează un serviciu de închiriere care le permite părinților care călătoresc să închirieze echipamente pentru bebeluși - cum ar fi pătuțuri, cărucioare și scaune auto - pe durata șederii lor, în loc să-și cumpere sau să le transporte pe ale lor. Acest model de produs ca serviciu prelungește durata de viață utilă a fiecărui articol, permițând utilizarea repetată în mai multe familii în loc de proprietatea unei singure gospodării, reducând volumul total de echipament pentru bebeluși care trebuie fabricat. De asemenea, elimină povara și costurile pentru familiile care călătoresc de a transporta sau cumpăra articole voluminoase, de utilizare pe termen scurt. Afacerea a fost recunoscută ca CirculUP! beneficiar pentru aplicarea principiilor accesului asupra proprietății unei categorii de produse de larg consum.",hy:"Baby Gear Armenia-ն գործում է վարձակալության ծառայություն, որը թույլ է տալիս ճանապարհորդող ծնողներին վարձել մանկական սարքավորումներ, ինչպիսիք են օրորոցները, մանկասայլակները և մեքենայի նստատեղերը, իրենց գտնվելու ընթացքում, այլ ոչ թե գնելու կամ տեղափոխելու իրենց: Արտադրանք՝ որպես ծառայություն այս մոդելը երկարացնում է յուրաքանչյուր ապրանքի օգտակար կյանքը՝ հնարավորություն տալով բազմիցս օգտագործել բազմաթիվ ընտանիքներում՝ մեկ տնային սեփականության փոխարեն՝ նվազեցնելով մանկական հանդերձանքի ընդհանուր ծավալը, որը պետք է արտադրվի: Այն նաև հանում է ճանապարհորդող ընտանիքների ծանրաբեռնվածությունը և ծախսերը՝ կապված մեծածավալ, կարճաժամկետ օգտագործման իրերի փոխադրման կամ գնման հետ: Բիզնեսը ճանաչվել է որպես CirculUP! դրամաշնորհառու՝ սպառողական ապրանքների բարձր շրջանառություն ունեցող ապրանքների կատեգորիայի նկատմամբ սեփականության իրավունքի հասանելիության սկզբունքները կիրառելու համար։"},caseLink:"https://babygeararmenia.com"}),e({id:"case-015",slug:"skesoor-mama-home",companyName:{en:"Skesoor Mama Home",uk:"",ro:"",hy:""},country:"Armenia",sector:["Textiles"],rStrategies:["Repurpose (R7)"],rStrategyDescription:{en:"Textile waste that would otherwise be discarded is redesigned and remanufactured into a different type of product (home decor items) with a new function.",uk:"Текстильні відходи, які в іншому разі були б видалені, перетворюють на вироби іншого типу – предмети декору для оселі – з новою функцією.",ro:"Deșeurile textile care altfel ar fi aruncate sunt reproiectate și refabricate într-un alt tip de produs (articole de decor pentru casă) cu o nouă funcție.",hy:"Տեքստիլ թափոնները, որոնք այլապես պետք է դեն նետվեին, վերանախագծվում և վերամշակվում են այլ տեսակի արտադրանքի (տան դեկորների իրեր) նոր գործառույթով։"},summary:{en:"Skesoor Mama Home upcycles textile waste into functional home decor items such as pillows and baskets, giving discarded fabric a new purpose as finished household products.",uk:"Skesoor Mama Home здійснює вторинне використання текстильних відходів для створення функціональних елементів домашнього декору (подушок, кошиків), даючи списаній тканині нове життя у вигляді готових виробів для оселі (метод апсайклінгу).",ro:"Skesoor Mama Home reciclează deșeurile textile în articole funcționale de decor, cum ar fi perne și coșuri, oferind țesăturii aruncate un nou scop ca produse de uz casnic finite.",hy:"Skesoor Mama Home-ը տեքստիլ թափոնները վերածում է տնային գործունակ դեկորների, ինչպիսիք են բարձերը և զամբյուղները՝ դեն նետված գործվածքին նոր նպատակ տալով որպես պատրաստի կենցաղային արտադրանք։"},description:{en:"Skesoor Mama Home collects discarded textile material and transforms it into handcrafted home decor products, including pillows, baskets, and related items. Rather than recycling the fabric back into raw fiber, the business repurposes the material directly into new finished goods, retaining more of its original value and reducing the energy-intensive reprocessing typically required for textile recycling. This approach also supports local craft production and offers consumers sustainably made home goods as an alternative to conventionally manufactured products. The venture is a CirculUP! grantee, part of the broader programme supporting Armenian circular startups working with textile waste streams.",uk:"Skesoor Mama Home збирає використані текстильні матеріали та перетворює їх на виготовлені вручну предмети декору для оселі, зокрема подушки, кошики та інші подібні вироби. Замість того щоб переробляти тканину назад у волокно, компанія безпосередньо надає матеріалу нове призначення, перетворюючи його на готові вироби. Це дає змогу зберегти більшу частину первісної цінності матеріалу та зменшити потребу в енергоємному переробленні, яке зазвичай необхідне для перероблення текстилю. Такий підхід також підтримує місцеве ремісниче виробництво та пропонує споживачам екологічніші товари для домівки як альтернативу традиційно виготовленій продукції. Підприємство отримало грант у межах програми CirculUP!, яка підтримує вірменські циркулярні стартапи, що працюють із потоками текстильних відходів.",ro:"Skesoor Mama Home colectează material textil aruncat și îl transformă în produse de decor pentru casă realizate manual, inclusiv perne, coșuri și articole conexe. În loc să recicleze țesătura înapoi în fibră brută, afacerea reutilizează materialul direct în produse finite noi, păstrând mai mult din valoarea sa inițială și reducând reprocesarea consumatoare de energie necesară de obicei pentru reciclarea textilelor. Această abordare sprijină, de asemenea, producția artizanală locală și oferă consumatorilor bunuri de casă realizate în mod durabil, ca alternativă la produsele fabricate în mod convențional. Aventura este un CirculUP! beneficiar, parte a programului mai larg de sprijinire a startup-urilor circulare armene care lucrează cu fluxurile de deșeuri textile.",hy:"Skesoor Mama Home-ը հավաքում է դեն նետված տեքստիլ նյութը և այն վերածում տնային դեկորների ձեռքով պատրաստված ապրանքների, ներառյալ բարձեր, զամբյուղներ և հարակից իրեր: Գործվածքը հում մանրաթելի վերածելու փոխարեն, բիզնեսը նյութը վերափոխում է ուղղակիորեն նոր պատրաստի ապրանքների մեջ՝ պահպանելով իր սկզբնական արժեքից ավելի շատ և նվազեցնելով էներգատար վերամշակումը, որը սովորաբար պահանջվում է տեքստիլի վերամշակման համար: Այս մոտեցումը նաև աջակցում է տեղական արհեստագործական արտադրությանը և սպառողներին առաջարկում է կայուն կերպով պատրաստված տնային ապրանքներ՝ որպես սովորական արտադրված արտադրանքի այլընտրանք: Ձեռնարկությունը CirculUP է: դրամաշնորհառու՝ տեքստիլ թափոնների հոսքերի հետ աշխատող հայկական շրջանաձև ստարտափներին աջակցող ավելի լայն ծրագրի մի մասը։"},caseLink:"https://www.facebook.com/skesoormama"}),e({id:"case-016",slug:"natural-self-cleaning-pool",companyName:{en:"Natural Self-Cleaning Pool",uk:"",ro:"",hy:""},country:"Armenia",sector:["Construction"],rStrategies:["Rethink (R1)"],rStrategyDescription:{en:"The product rethinks conventional pool design by replacing chemical water treatment with a natural filtration system, reducing chemical inputs and their associated environmental impact.",uk:"Конструкцію басейну переосмислено: хімічне очищення води замінено природною системою фільтрації, що зменшує потребу в хімічних речовинах та пов’язаний із ними вплив на довкілля.",ro:"Produsul regândește designul convențional al piscinei prin înlocuirea tratamentului chimic al apei cu un sistem natural de filtrare, reducând aporturile chimice și impactul lor asupra mediului asociat.",hy:"Արտադրանքը վերանայում է ավանդական լողավազանի դիզայնը՝ ջրի քիմիական մաքրումը փոխարինելով բնական ֆիլտրման համակարգով, նվազեցնելով քիմիական նյութերը և դրանց հարակից շրջակա միջավայրի ազդեցությունը։"},summary:{en:"This business builds chemical-free swimming pools that rely on natural biological filtration systems instead of chlorine or other synthetic chemicals to maintain water quality.",uk:"Natural Self-Cleaning Pool будує басейни без використання хімікатів, які покладаються на природні системи біологічної фільтрації замість хлору чи інших синтетичних речовин для підтримання якості води.",ro:"Această companie construiește piscine fără substanțe chimice care se bazează pe sisteme naturale de filtrare biologică în loc de clor sau alte substanțe chimice sintetice pentru a menține calitatea apei.",hy:"Այս բիզնեսը կառուցում է առանց քիմիական նյութերի լողավազաններ, որոնք հիմնված են բնական կենսաբանական ֆիլտրման համակարգերի վրա՝ քլորի կամ այլ սինթետիկ քիմիական նյութերի փոխարեն ջրի որակը պահպանելու համար։"},description:{en:"This venture designs and builds swimming pools that use natural filtration — typically involving aquatic plants and biological filter zones — to maintain water clarity and hygiene without the addition of chlorine or other synthetic chemicals. This reduces the ongoing chemical inputs required for pool maintenance, lowers the associated environmental discharge when pool water is drained or replaced, and can reduce the health impacts associated with chemical exposure for swimmers. The approach reflects a rethinking of a conventional, resource- and chemical-intensive product category. The case was highlighted as a CirculUP! grantee for introducing a lower-impact alternative into Armenia's construction and leisure sector.",uk:"Це підприємство проєктує та будує басейни з природною системою фільтрації, яка зазвичай передбачає використання водних рослин і зон біологічної фільтрації для підтримання прозорості та санітарної безпечності води без додавання хлору чи інших синтетичних хімічних речовин. Такий підхід зменшує постійну потребу в хімічних речовинах для догляду за басейном, знижує пов’язане з ними забруднення довкілля під час зливання або заміни води та може зменшувати вплив хімічних речовин на здоров’я плавців. Цей підхід передбачає переосмислення традиційної категорії продукції, яка потребує значних ресурсів і хімічних речовин. Цей приклад отримав підтримку в межах CirculUP! як рішення з меншим впливом на довкілля для будівельного сектору та сфери відпочинку у Вірменії.",ro:"Această întreprindere proiectează și construiește piscine care utilizează filtrarea naturală - implicând de obicei plante acvatice și zone de filtrare biologică - pentru a menține limpezimea și igiena apei fără adăugarea de clor sau alte substanțe chimice sintetice. Acest lucru reduce aportul chimic continuu necesar pentru întreținerea piscinei, scade deversarea asociată mediului atunci când apa din piscină este drenată sau înlocuită și poate reduce impactul asupra sănătății asociat cu expunerea chimică a înotătorilor. Abordarea reflectă o regândire a unei categorii de produse convenționale, intensive în resurse și substanțe chimice. Cazul a fost evidențiat ca CirculUP! beneficiar pentru introducerea unei alternative cu impact redus în sectorul construcțiilor și al agrementului din Armenia.",hy:"Այս ձեռնարկությունը նախագծում և կառուցում է լողավազաններ, որոնք օգտագործում են բնական ֆիլտրացիա, որոնք սովորաբար ներառում են ջրային բույսեր և կենսաբանական զտիչ գոտիներ՝ ջրի մաքրությունը և հիգիենան պահպանելու համար՝ առանց քլորի կամ այլ սինթետիկ քիմիական նյութերի ավելացման: Սա նվազեցնում է լողավազանի պահպանման համար պահանջվող շարունակական քիմիական նյութերը, նվազեցնում է շրջակա միջավայրի արտանետումը, երբ լողավազանի ջուրը ջրահեռացվում կամ փոխարինվում է, և կարող է նվազեցնել լողորդների համար քիմիական ազդեցության հետ կապված առողջության վրա ազդեցությունները: Մոտեցումն արտացոլում է սովորական, ռեսուրսների և քիմիական ինտենսիվ արտադրանքի կատեգորիայի վերաիմաստավորումը: Գործը ընդգծվեց որպես CirculUP! դրամաշնորհառու՝ Հայաստանի շինարարության և ժամանցի ոլորտում ավելի քիչ ազդեցություն ունեցող այլընտրանքի ներդրման համար։"},caseLink:"https://circulup.am/2025/03/31/natural-self-cleaning-pool"}),e({id:"case-017",slug:"redline",companyName:{en:"RedLine",uk:"",ro:"",hy:""},country:"Armenia",sector:["Furniture"],rStrategies:["Reuse (R3)","Recycle (R8)"],rStrategyDescription:{en:"A trade-in programme keeps furniture in use for longer by facilitating its return and resale or refurbishment (Reuse); wood waste that can no longer be reused is processed into new modular furniture components (Recycle).",uk:"Програма Trade-In дає змогу довше використовувати меблі, забезпечуючи їх повернення для повторного продажу або відновлення (Повторне використання); деревні відходи, які вже не можна повторно використати, переробляють на нові компоненти модульних меблів (Перероблення).",ro:"Un program de schimb menține mobila în uz mai mult timp facilitând returnarea și revânzarea sau recondiționarea acesteia (Reutilizare); deșeurile de lemn care nu mai pot fi refolosite sunt procesate în noi componente modulare de mobilier (Reciclare).",hy:"Առևտրային ծրագիրն ավելի երկար է պահում կահույքը օգտագործման մեջ՝ հեշտացնելով դրա վերադարձը և վերավաճառքը կամ վերանորոգումը (Վերօգտագործում); Փայտի թափոնները, որոնք այլևս չեն կարող կրկին օգտագործվել, վերամշակվում են նոր մոդուլային կահույքի բաղադրիչների (Վերամշակում)։"},summary:{en:"RedLine repurposes wood waste into modular furniture and has launched a furniture trade-in programme that allows customers to return used pieces, extending the material's useful life across multiple product cycles.",uk:"RedLine перепрофільовує відходи деревини на модульні меблі та запустила програму Trade-In, яка дозволяє клієнтам повертати вживані вироби, подовжуючи термін експлуатації матеріалу впродовж кількох життєвих циклів продукції.",ro:"RedLine reutilizează deșeurile de lemn în mobilier modular și a lansat un program de schimb de mobilă care permite clienților să returneze piesele uzate, prelungind durata de viață utilă a materialului pe mai multe cicluri de produs.",hy:"RedLine-ը վերափոխում է փայտի թափոնները մոդուլային կահույքի մեջ և գործարկել է կահույքի առևտրի ծրագիր, որը թույլ է տալիս հաճախորդներին վերադարձնել օգտագործված կտորները՝ երկարացնելով նյութի օգտակար կյանքը մի քանի ապրանքների ցիկլերում։"},description:{en:"RedLine is a circular furniture business that combines two complementary strategies. First, it manufactures modular furniture using recovered wood waste as an input material, reducing demand for virgin timber. Second, it operates a trade-in programme through which customers can return furniture at the end of its use cycle, allowing RedLine to refurbish, resell, or reprocess the material rather than have it discarded. Together, these approaches extend the useful life of both the wood material and the finished furniture products, forming a closed loop between production, use, and end-of-life recovery. The business was supported as a CirculUP! grantee for demonstrating an integrated circular SME model in the furniture sector.",uk:"RedLine – циркулярний меблевий бізнес, який поєднує дві взаємодоповнювальні стратегії. По-перше, компанія виробляє модульні меблі, використовуючи відновлені деревні відходи як сировину, що зменшує потребу в первинній деревині. По-друге, вона реалізує програму Trade-In, у межах якої клієнти можуть повертати меблі після завершення їхнього циклу використання. Це дає RedLine змогу відновлювати меблі, повторно продавати їх або переробляти матеріал замість того, щоб він ставав відходами. У сукупності ці підходи продовжують термін використання як деревини, так і готових меблів, формуючи замкнений цикл між виробництвом, використанням і відновленням матеріалів після завершення терміну експлуатації. Бізнес отримав підтримку в межах CirculUP! як отримувач гранту за демонстрацію інтегрованої циркулярної моделі для МСП у меблевій галузі.",ro:"RedLine este o afacere circulară de mobilă care combină două strategii complementare. În primul rând, produce mobilier modular utilizând deșeuri de lemn recuperate ca material de intrare, reducând cererea de cherestea virgină. În al doilea rând, operează un program de schimb prin care clienții pot returna mobila la sfârșitul ciclului său de utilizare, permițând RedLine să recondiționeze, să revinde sau să reproceseze materialul, mai degrabă decât să-l arunce. Împreună, aceste abordări prelungesc durata de viață utilă atât a materialului lemnos, cât și a produselor finite de mobilier, formând o buclă închisă între producție, utilizare și recuperarea la sfârșitul vieții. Afacerea a fost susținută ca CirculUP! beneficiar pentru demonstrarea unui model circular integrat de IMM în sectorul mobilei.",hy:"RedLine-ը կահույքի շրջանաձև բիզնես է, որը համատեղում է երկու փոխլրացնող ռազմավարություն: Նախ, այն արտադրում է մոդուլային կահույք՝ օգտագործելով վերականգնված փայտի թափոնները որպես մուտքային նյութ՝ նվազեցնելով կուսական փայտանյութի պահանջարկը: Երկրորդ, այն գործարկում է առևտրի ծրագիր, որի միջոցով հաճախորդները կարող են վերադարձնել կահույքն իր օգտագործման ցիկլի ավարտին, ինչը թույլ է տալիս RedLine-ին վերանորոգել, վերավաճառել կամ վերամշակել նյութը, այլ ոչ թե այն դեն նետել: Միասին այս մոտեցումները երկարացնում են ինչպես փայտանյութի, այնպես էլ պատրաստի կահույքի արտադրանքի օգտակար կյանքը՝ փակ օղակ կազմելով արտադրության, օգտագործման և ժամկետի ավարտի վերականգնման միջև: Բիզնեսին աջակցում էին որպես CirculUP: դրամաշնորհառու՝ կահույքի ոլորտում ինտեգրված շրջանաձև ՓՄՁ մոդելի ցուցադրման համար։"},caseLink:"https://www.facebook.com/RedLineArmenia?locale=ru_RU"}),e({id:"case-019",slug:"hdif-homeland-development-initiative-foundation",companyName:{en:"HDIF (Homeland Development Initiative Foundation)",uk:"",ro:"",hy:""},country:"Armenia",sector:["Textiles"],rStrategies:["Rethink (R1)"],rStrategyDescription:{en:"Blockchain-based traceability rethinks supply chain transparency and trust mechanisms in the wool industry, enabling better material tracking that can support more circular and responsible sourcing decisions.",uk:"Відстежуваність на основі блокчейну переосмислює підходи до прозорості та довіри в ланцюгу постачання вовни, забезпечуючи ефективніше відстеження матеріалів, що може сприяти більш циркулярним і відповідальним рішенням щодо їх постачання.",ro:"Trasabilitatea bazată pe blockchain regândește transparența lanțului de aprovizionare și mecanismele de încredere în industria lânii, permițând o urmărire mai bună a materialelor care poate sprijini decizii de aprovizionare mai circulare și responsabile.",hy:"Բլոկչեյնի վրա հիմնված հետագծելիությունը վերանայում է մատակարարման շղթայի թափանցիկությունը և վստահության մեխանիզմները բրդի արդյունաբերության մեջ՝ հնարավորություն տալով նյութերի ավելի լավ հետևել, որը կարող է աջակցել ավելի շրջանաձև և պատասխանատու աղբյուրների որոշումներին։"},summary:{en:"HDIF uses blockchain technology to create a fully transparent, traceable supply chain for Armenia's wool industry, connecting wool producers, processors, and buyers through a verifiable digital record.",uk:"HDIF (Homeland Development Initiative Foundation) використовує технологію блокчейн для створення повністю прозорого та відстежуваного ланцюга постачання у вовняній промисловості Вірменії, об'єднуючи виробників, переробників і покупців вовни за допомогою верифікованого цифрового реєстру.",ro:"HDIF folosește tehnologia blockchain pentru a crea un lanț de aprovizionare complet transparent și trasabil pentru industria lânii din Armenia, conectând producătorii de lână, procesatorii și cumpărătorii printr-o înregistrare digitală verificabilă.",hy:"HDIF-ն օգտագործում է բլոկչեյն տեխնոլոգիան Հայաստանի բրդի արդյունաբերության համար լիովին թափանցիկ, հետագծելի մատակարարման շղթա ստեղծելու համար՝ միացնելով բուրդ արտադրողներին, վերամշակողներին և գնորդներին ստուգելի թվային գրառումների միջոցով։"},description:{en:"HDIF has developed a blockchain-based traceability system for Armenia's wool supply chain, allowing each stage of production — from raising livestock through processing and sale — to be recorded on a verifiable digital ledger. This transparency helps address common challenges in textile supply chains, including unclear material provenance and difficulty verifying sustainable or ethical sourcing claims. For a circular economy, better traceability can support more informed decisions about material reuse, quality grading, and end-of-life recovery of wool products. The initiative was recognised as a CirculUP! grantee for applying digital tools to strengthen sustainability and transparency in a traditional Armenian industry.",uk:"HDIF розробила систему відстежуваності ланцюга постачання вовни у Вірменії на основі блокчейну, яка дає змогу фіксувати кожен етап виробництва – від вирощування та утримання худоби до перероблення і продажу – у цифровому реєстрі, дані якого можна перевірити. Така прозорість допомагає розв’язувати поширені проблеми текстильних ланцюгів постачання, зокрема відсутність чіткої інформації про походження матеріалів і складність перевірки заяв щодо сталого та етичного постачання. Для циркулярної економіки краща відстежуваність може сприяти більш обґрунтованим рішенням щодо повторного використання матеріалів, оцінювання їхньої якості та відновлення вовняних виробів після завершення терміну експлуатації. Ініціатива отримала підтримку в межах CirculUP! як приклад застосування цифрових інструментів для підвищення сталості та прозорості традиційної галузі Вірменії.",ro:"HDIF a dezvoltat un sistem de trasabilitate bazat pe blockchain pentru lanțul de aprovizionare cu lână din Armenia, permițând ca fiecare etapă a producției – de la creșterea animalelor până la procesare și vânzare – să fie înregistrată într-un registru digital verificabil. Această transparență ajută la abordarea provocărilor comune din lanțurile de aprovizionare cu textile, inclusiv proveniența neclară a materialului și dificultățile de verificare a declarațiilor de aprovizionare durabilă sau etică. Pentru o economie circulară, o trasabilitate mai bună poate sprijini decizii mai informate cu privire la reutilizarea materialelor, clasificarea calității și recuperarea la sfârșitul vieții produselor din lână. Inițiativa a fost recunoscută drept CirculUP! beneficiar pentru aplicarea instrumentelor digitale pentru a consolida durabilitatea și transparența într-o industrie tradițională armeană.",hy:"HDIF-ը մշակել է բլոկչեյնի վրա հիմնված հետագծելիության համակարգ Հայաստանի բրդի մատակարարման շղթայի համար, որը թույլ է տալիս արտադրության յուրաքանչյուր փուլ՝ անասնապահությունից մինչև վերամշակում և վաճառք, գրանցել ստուգելի թվային մատյանում: Այս թափանցիկությունը օգնում է լուծել ընդհանուր մարտահրավերները տեքստիլ մատակարարման շղթաներում, ներառյալ նյութական ծագման անհասկանալիությունը և կայուն կամ էթիկական աղբյուրների պահանջները ստուգելու դժվարությունը: Շրջանաձև տնտեսության համար ավելի լավ հետագծելիությունը կարող է աջակցել նյութերի վերաօգտագործման, որակի դասակարգման և բրդյա արտադրանքի ժամկետի ավարտի վերականգնման վերաբերյալ ավելի տեղեկացված որոշումների կայացմանը: Նախաձեռնությունը ճանաչվեց որպես CirculUP! դրամաշնորհառու՝ թվային գործիքների կիրառման համար՝ ամրապնդելու կայունությունն ու թափանցիկությունը հայկական ավանդական ոլորտում։"},caseLink:"https://hdif.org"}),e({id:"case-021",slug:"antaram",companyName:{en:"Antaram",uk:"",ro:"",hy:""},country:"Armenia",sector:["Cosmetics"],rStrategies:["Repurpose (R7)"],rStrategyDescription:{en:"Organic residues from herbal tea production, previously a low-value waste stream, are processed into higher-value cosmetics and essential oil products through a different production pathway.",uk:"Органічні залишки від виробництва трав’яного чаю, які раніше були маловартісним потоком відходів, переробляють за іншим виробничим процесом на косметичну продукцію та ефірні олії з вищою доданою вартістю.",ro:"Reziduurile organice din producția de ceai din plante, anterior un flux de deșeuri cu valoare scăzută, sunt procesate în produse cosmetice și uleiuri esențiale de valoare mai mare printr-o cale de producție diferită.",hy:"Բուսական թեյի արտադրության օրգանական մնացորդները, որոնք նախկինում ցածրարժեք թափոնների հոսք էին, վերամշակվում են ավելի բարձր արժեք ունեցող կոսմետիկայի և եթերայուղերի արտադրական այլ ճանապարհների միջոցով։"},summary:{en:"Antaram extracts high-value cosmetics ingredients and essential oils from organic waste generated during herbal tea production, turning a processing by-product into a marketable consumer product line.",uk:"Antaram вилучає цінні косметичні інгредієнти та ефірні олії з органічних відходів, які утворюються під час виробництва трав'яного чаю, перетворюючи побічний продукт перероблення на лінійку комерційної споживчої продукції.",ro:"Antaram extrage ingrediente cosmetice de mare valoare și uleiuri esențiale din deșeurile organice generate în timpul producției de ceaiuri din plante, transformând un produs secundar de procesare într-o linie de produse de larg consum.",hy:"Անթառամը արդյունահանում է բարձրարժեք կոսմետիկայի բաղադրիչները և եթերայուղերը բուսական թեյի արտադրության ընթացքում առաջացած օրգանական թափոններից՝ վերամշակվող կողմնակի արտադրանքը վերածելով սպառողական ապրանքների վաճառքի։"},description:{en:"Antaram has developed a process to extract essential oils and cosmetic-grade ingredients from the organic waste generated during herbal tea processing, such as spent plant material and residues. This upcycling approach captures additional value from a waste stream that would otherwise be discarded, while diversifying the business's product offering into the higher-margin cosmetics sector. By linking two Armenian sectors — herbal/agricultural processing and cosmetics manufacturing — the venture demonstrates how by-product valorisation can create new revenue streams for producers while reducing overall waste generation. The initiative was featured as a CirculUP! grantee.",uk:"Antaram розробила процес отримання ефірних олій та інгредієнтів для косметичної продукції з органічних відходів, що утворюються під час перероблення трав’яного чаю, зокрема використаної рослинної сировини та інших залишків. Такий підхід дає змогу перетворювати відходи, які в іншому разі були б видалені, на цінну сировину для нової продукції та водночас розширювати асортимент компанії, додаючи продукцію косметичної галузі, яка приносить вищий прибуток. Поєднуючи два вірменські сектори – перероблення трав’яної та сільськогосподарської сировини й виробництво косметики – підприємство демонструє, як підвищення цінності побічних продуктів може створювати нові джерела доходу для виробників і водночас зменшувати загальний обсяг відходів. Ініціатива отримала підтримку в межах CirculUP! як отримувач гранту.",ro:"Antaram a dezvoltat un proces de extragere a uleiurilor esențiale și a ingredientelor de calitate cosmetică din deșeurile organice generate în timpul procesării ceaiului din plante, cum ar fi materialul vegetal uzat și reziduurile. Această abordare de upcycling captează valoare suplimentară dintr-un flux de deșeuri care altfel ar fi aruncat, diversificând în același timp oferta de produse a companiei în sectorul cosmeticelor cu marjă mai mare. Prin legarea a două sectoare armene – prelucrarea plantelor/agricole și producția de cosmetice – afacerea demonstrează modul în care valorificarea subproduselor poate crea noi fluxuri de venituri pentru producători, reducând în același timp generarea generală de deșeuri. Inițiativa a fost prezentată ca CirculUP! concesionar.",hy:"Անթառամը մշակել է եթերային յուղեր և կոսմետիկ որակի բաղադրիչներ արդյունահանելու գործընթացը բուսական թեյի մշակման ընթացքում առաջացած օրգանական թափոններից, ինչպիսիք են՝ օգտագործված բուսանյութը և մնացորդները: Վերամշակման այս մոտեցումը լրացուցիչ արժեք է ստանում թափոնների հոսքից, որը հակառակ դեպքում կդիտարկվեր՝ միաժամանակ դիվերսիֆիկացնելով բիզնեսի արտադրանքի առաջարկը դեպի ավելի բարձր մարժա կոսմետիկայի հատված: Միացնելով հայկական երկու ոլորտները՝ բուսական/գյուղատնտեսական մշակման և կոսմետիկայի արտադրությունը, ձեռնարկությունը ցույց է տալիս, թե ինչպես են կողմնակի արտադրանքի արժեքավորումը կարող է նոր եկամուտներ ստեղծել արտադրողների համար՝ միաժամանակ նվազեցնելով ընդհանուր թափոնների արտադրությունը: Նախաձեռնությունը ներկայացվել է որպես CirculUP! դրամաշնորհառու."},caseLink:"https://circulup.am/2025/03/31/antaram"}),e({id:"case-022",slug:"lukashin-agricultural-cooperative",companyName:{en:"Lukashin Agricultural Cooperative",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Fruit processing residues (pits and peels) are reprocessed into new consumer products (oils, drinks, nutritional bars), recovering material value that would otherwise be lost to disposal.",uk:"Залишки від перероблення фруктів – кісточки та шкірки – переробляють на нові споживчі продукти: олії, напої та поживні батончики. Так вдається використати цінні властивості матеріалів, які зазвичай просто стають відходами.",ro:"Reziduurile de prelucrare a fructelor (sâmburi și coji) sunt reprocesate în noi produse de consum (uleiuri, băuturi, batoane nutritive), recuperând valoarea materială care altfel ar fi pierdută la eliminare.",hy:"Մրգերի վերամշակման մնացորդները (փոսերը և կեղևները) վերամշակվում են նոր սպառողական ապրանքների (յուղեր, ըմպելիքներ, սննդային ձուլակտորներ)՝ վերականգնելով նյութական արժեքը, որը այլապես կկորցներ հեռացման համար։"},summary:{en:"The Lukashin Agricultural Cooperative transforms fruit pits and peels, typically discarded during processing, into valuable oils, drinks, and nutritional bars, applying a zero-waste approach to fruit processing.",uk:"Lukashin Agricultural Cooperative перетворює кісточки та шкірку фруктів (які зазвичай викидаються під час перероблення) на цінні олії, напої та поживні батончики, застосовуючи безвідходний підхід до перероблення фруктів.",ro:"Cooperativa agricolă Lukashin transformă sâmburii și cojile de fructe, de obicei aruncate în timpul procesării, în uleiuri valoroase, băuturi și batoane nutritive, aplicând o abordare fără deșeuri la prelucrarea fructelor.",hy:"«Լուկաշին» գյուղատնտեսական կոոպերատիվը վերափոխում է մրգի կորիզներն ու կեղևները, որոնք սովորաբար վերամշակման ընթացքում թափվում են, արժեքավոր յուղերի, ըմպելիքների և սննդային սալիկների՝ կիրառելով մրգի վերամշակման զրոյական թափոնների մոտեցում։"},description:{en:"The Lukashin Agricultural Cooperative has implemented a zero-waste approach to fruit processing, developing product lines that use fruit pits and peels — by-products normally discarded during juice, jam, or dried-fruit production. These residues are processed into oils (from pits, which often contain usable fats), beverages, and nutritional bars, creating additional revenue streams from material that would otherwise represent a pure cost to dispose of. This model increases the overall value captured from each unit of raw fruit processed and reduces the volume of organic waste generated by the cooperative's operations. The case was supported as a CirculUP! grantee for demonstrating value-chain-wide resource efficiency in Armenia's agricultural cooperative sector.",uk:"Lukashin Agricultural Cooperative застосовує безвідходний підхід до перероблення фруктів, розробляючи нові види продукції з кісточок і шкірок – побічних продуктів, які зазвичай викидають під час виробництва соків, варення чи сушених фруктів. Ці залишки переробляють на олії з кісточок, які часто містять придатні для використання жири, а також на напої та поживні батончики. Замість витрачати кошти на видалення цих залишків, кооператив використовує їх для виробництва продукції та отримує додатковий дохід. Такий підхід дає змогу отримувати більшу цінність із кожної одиниці фруктової сировини, що надходить на перероблення, та водночас зменшувати обсяг органічних відходів, які утворюються в діяльності кооперативу. Цей приклад отримав підтримку в межах CirculUP! за демонстрацію ресурсоефективності на всьому ланцюгу створення вартості в секторі сільськогосподарських кооперативів Вірменії.",ro:"Cooperativa agricolă Lukashin a implementat o abordare fără deșeuri a procesării fructelor, dezvoltând linii de produse care folosesc sâmburi și coajă de fructe - produse secundare aruncate în mod normal în timpul producției de suc, dulceață sau fructe uscate. Aceste reziduuri sunt procesate în uleiuri (din gropi, care conțin adesea grăsimi utilizabile), băuturi și batoane nutritive, creând fluxuri de venituri suplimentare din material care altfel ar reprezenta un cost pur de eliminat. Acest model crește valoarea totală captată din fiecare unitate de fructe crude procesate și reduce volumul deșeurilor organice generate de operațiunile cooperativei. Cazul a fost susținut ca CirculUP! beneficiar pentru demonstrarea eficienței resurselor la nivelul întregului lanț valoric în sectorul cooperativ agricol al Armeniei.",hy:"«Լուկաշին» գյուղատնտեսական կոոպերատիվը կիրառել է մրգի վերամշակման զրոյական թափոնների մոտեցում՝ մշակելով արտադրանքի գծեր, որոնք օգտագործում են մրգի կորիզներ և կեղևներ՝ ենթամթերք, որոնք սովորաբար դեն նետվում են հյութի, ջեմի կամ չոր մրգերի արտադրության ժամանակ: Այս մնացորդները վերամշակվում են յուղերի (փոսերից, որոնք հաճախ պարունակում են օգտագործելի ճարպեր), ըմպելիքների և սննդային ձուլակտորների մեջ՝ ստեղծելով լրացուցիչ եկամուտների հոսքեր նյութերից, որոնք այլ կերպ կներկայացնեն ոչնչացման մաքուր ծախսեր: Այս մոդելը մեծացնում է մշակված հումքի յուրաքանչյուր միավորից ստացված ընդհանուր արժեքը և նվազեցնում է կոոպերատիվի գործունեության արդյունքում առաջացած օրգանական թափոնների ծավալը: Գործը պաշտպանվել է որպես CirculUP: դրամաշնորհառու՝ Հայաստանի գյուղատնտեսական կոոպերատիվների ոլորտում արժեշղթայի ողջ ռեսուրսների արդյունավետությունը ցուցադրելու համար։"},caseLink:"https://www.facebook.com/people/Lukashincoop/100064446382302/"}),e({id:"case-023",slug:"kindergartens-in-yerevan-retrofitting-case-study",companyName:{en:"Kindergartens in Yerevan Retrofitting Case Study",uk:"",ro:"",hy:""},country:"Armenia",sector:["Construction"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Energy-efficient retrofitting (insulation, heating system upgrades) reduces the energy consumption of existing public buildings, lowering resource use without requiring new construction.",uk:"Енергоефективна реконструкція – утеплення будівель, модернізація систем опалення – зменшує споживання енергії наявними громадськими будівлями та скорочує використання ресурсів без необхідності нового будівництва.",ro:"Modernizarea eficientă din punct de vedere energetic (izolație, modernizarea sistemului de încălzire) reduce consumul de energie al clădirilor publice existente, reducând utilizarea resurselor fără a necesita noi construcții.",hy:"Էներգաարդյունավետ վերազինումը (մեկուսացում, ջեռուցման համակարգի արդիականացում) նվազեցնում է գոյություն ունեցող հասարակական շենքերի էներգիայի սպառումը` նվազեցնելով ռեսուրսների օգտագործումը` առանց նոր շինարարության պահանջի։"},summary:{en:"This case study documents the social, energy, and gender-related benefits of retrofitting kindergartens in Yerevan for improved energy efficiency, as part of the United Nations Development Programme (UNDP)-Green Climate Fund (GCF) building retrofit programme.",uk:"Kindergartens in Yerevan Retrofitting Case Study – це практичний приклад, в якому описано соціальні, енергетичні та гендерні переваги модернізації дитячих садків у Єревані з метою підвищення енергоефективності. Модернізацію було виконано в межах програми ПРООН і Зеленого кліматичного фонду (GCF) з модернізації будівель.",ro:"Acest studiu de caz documentează beneficiile sociale, energetice și legate de gen ale modernizării grădinițelor din Erevan pentru o eficiență energetică îmbunătățită, ca parte a programului de modernizare a clădirilor Programului Națiunilor Unite pentru Dezvoltare (PNUD)-Fondul Verde pentru Climă (GCF).",hy:"Այս դեպքի ուսումնասիրությունը փաստում է Երևանի մանկապարտեզների վերազինման սոցիալական, էներգետիկ և գենդերային օգուտները էներգաարդյունավետության բարելավման համար՝ որպես Միավորված ազգերի զարգացման ծրագրի (ՄԱԶԾ)-Կանաչ կլիմայի հիմնադրամի (GCF) շենքերի վերազինման ծրագրի մաս։"},description:{en:"Produced under the Mershenq / United Nations Development Programme (UNDP)-Green Climate Fund (GCF) 'De-risking and Scaling-up Investment in Energy Efficient Building Retrofits' project, this case study assesses the outcomes of retrofitting kindergartens across Yerevan for improved energy performance. Beyond the direct energy savings from improved insulation and heating systems, the study documents wider social and gender-related benefits, such as improved indoor comfort and health conditions for children and staff, and the differentiated impacts on women, who make up the majority of childcare and facility staff. The study forms part of a broader evidence base supporting Armenia's public building retrofit programme, illustrating how resource-efficiency interventions in public infrastructure can generate co-benefits beyond direct energy reduction.",uk:"Цей приклад підготовлено в межах проєкту Mershenq / ПРООН і Зеленого кліматичного фонду (GCF) «Зниження ризиків та масштабування інвестицій в енергоефективну модернізацію будівель». У ньому оцінено результати реконструкції дитячих садків у Єревані з метою підвищення енергоефективності будівель. Окрім безпосередньої економії енергії завдяки покращенню теплоізоляції та модернізації систем опалення, у дослідженні описано ширші соціальні та гендерні переваги, зокрема підвищення комфорту в приміщеннях і покращення умов для здоров’я дітей та працівників, а також різний вплив цих заходів на жінок, які становлять більшість працівників дитячих садків і персоналу, що забезпечує їх функціонування. Дослідження є частиною ширшої доказової бази для програми модернізації громадських будівель Вірменії та демонструє, як заходи з підвищення ресурсоефективності громадської інфраструктури можуть давати додаткові переваги, що виходять за межі безпосереднього скорочення споживання енергії.",ro:"Produs în cadrul proiectului Mershenq / Programul Națiunilor Unite pentru Dezvoltare (UNDP)-Fondul verde pentru climă (GCF) „Reducerea riscurilor și extinderea investițiilor în modernizarea clădirilor eficiente din punct de vedere energetic”, acest studiu de caz evaluează rezultatele modernizării grădinițelor din Erevan pentru o performanță energetică îmbunătățită. Dincolo de economiile directe de energie din sistemele de izolație și încălzire îmbunătățite, studiul documentează beneficii sociale și legate de gen mai largi, cum ar fi confortul interior îmbunătățit și condițiile de sănătate pentru copii și personal, precum și impactul diferențiat asupra femeilor, care alcătuiesc majoritatea personalului de îngrijire a copiilor și a personalului din instituții. Studiul face parte dintr-o bază de dovezi mai amplă care susține programul de modernizare a clădirilor publice din Armenia, ilustrând modul în care intervențiile de utilizare eficientă a resurselor în infrastructura publică pot genera co-beneficii dincolo de reducerea directă a energiei.",hy:"Ստեղծված Մերշենք/ՄԱԿ-ի Զարգացման ծրագիր (ՄԱԶԾ)-Կանաչ կլիմայի հիմնադրամ (GCF) «Վտանգավոր և ընդլայնվող ներդրումները էներգաարդյունավետ շենքերի վերազինման համար» ծրագրի շրջանակներում, այս դեպքի ուսումնասիրությունը գնահատում է Երևանի մանկապարտեզների վերազինման արդյունքները էներգետիկ արդյունավետության բարելավման համար: Բարելավված ջերմամեկուսացման և ջեռուցման համակարգերից ուղղակի էներգիայի խնայողությունից բացի, ուսումնասիրությունը փաստում է ավելի լայն սոցիալական և գենդերային օգուտներ, ինչպիսիք են երեխաների և անձնակազմի ներքին հարմարավետության և առողջության բարելավված պայմանները, ինչպես նաև տարբեր ազդեցությունները կանանց վրա, որոնք կազմում են երեխաների խնամքի և հաստատությունների անձնակազմի մեծ մասը: Ուսումնասիրությունը կազմում է Հայաստանի հանրային շենքերի վերազինման ծրագրին աջակցող ավելի լայն ապացույցների բազայի մի մասը, որը ցույց է տալիս, թե ինչպես ռեսուրսների արդյունավետության հետ կապված միջամտությունները հանրային ենթակառուցվածքներում կարող են առաջացնել համատեղ օգուտներ, բացի էներգիայի ուղղակի կրճատումից։"},caseLink:"https://www.mershenq.am/en/publications/assessment-of-social-and-gender-benefits-of-energy-ecient-retrofitting-of-kindergartens"}),e({id:"case-024",slug:"residential-buildings-retrofits-impact-assessment",companyName:{en:"Residential Buildings Retrofits Impact Assessment",uk:"",ro:"",hy:""},country:"Armenia",sector:["Construction"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Retrofitting existing multi-apartment buildings for improved thermal performance reduces ongoing energy consumption compared to unretrofitted housing stock.",uk:"Модернізація наявних багатоквартирних будинків для підвищення їхньої теплової ефективності дає змогу зменшити подальше споживання енергії порівняно з будинками, де такі заходи не впроваджувалися.",ro:"Modernizarea clădirilor existente cu mai multe apartamente pentru o performanță termică îmbunătățită reduce consumul de energie curent în comparație cu fondul de locuințe neretrofit.",hy:"Գոյություն ունեցող բազմաբնակարան շենքերի վերազինումը ջերմային արդյունավետության բարելավման համար նվազեցնում է ընթացիկ էներգիայի սպառումը` համեմատած չվերազինված բնակարանային ֆոնդի հետ։"},summary:{en:"This impact assessment analyzes household survey data on the outcomes of energy-efficient retrofits in multi-apartment residential buildings across Armenia, evaluating both energy and quality-of-life effects.",uk:"Ця оцінка аналізує дані опитувань домогосподарств щодо результатів енергоефективної термомодернізації багатоквартирних житлових будинків у всій Вірменії, оцінюючи як енергетичні показники, так і вплив на якість життя.",ro:"Această evaluare a impactului analizează datele sondajului în gospodării cu privire la rezultatele modernizărilor eficiente din punct de vedere energetic în clădirile rezidențiale cu mai multe apartamente din Armenia, evaluând atât efectele asupra energiei, cât și asupra calității vieții.",hy:"Ազդեցության այս գնահատումը վերլուծում է տնային տնտեսությունների հետազոտության տվյալները Հայաստանի բազմաբնակարան բնակելի շենքերի էներգաարդյունավետ վերազինման արդյունքների վերաբերյալ՝ գնահատելով ինչպես էներգիայի, այնպես էլ կյանքի որակի վրա ազդեցությունները։"},description:{en:"This publication, part of the Mershenq / United Nations Development Programme (UNDP)-Green Climate Fund (GCF) building retrofit project, presents findings from household surveys assessing the impact of energy-efficient retrofits carried out in Armenia's multi-apartment residential buildings, a housing type that makes up a significant share of the country's urban building stock. The assessment evaluates changes in energy consumption, heating costs, and resident-reported comfort and satisfaction following retrofit interventions such as building envelope insulation and heating system upgrades. As Armenia's residential building stock is largely aging Soviet-era construction with poor thermal performance, this case provides evidence for scaling similar retrofit investments nationally, supporting both emissions reduction and improved living conditions.",uk:"Це дослідження, підготовлене в межах проєкту Mershenq / ПРООН і Зеленого кліматичного фонду (GCF) з модернізації будівель, містить результати опитування домогосподарств щодо впливу енергоефективної модернізації багатоквартирних житлових будинків у Вірменії – типу житла, який становить значну частину міської забудови країни. У дослідженні оцінено зміни у споживанні енергії, витратах на опалення, а також комфорті та задоволеності мешканців після впровадження заходів із модернізації, як-от утеплення огороджувальних конструкцій будівель і модернізація систем опалення. Оскільки житловий фонд Вірменії значною мірою складається зі старих будівель радянського періоду з низькою тепловою ефективністю, цей приклад надає докази на користь масштабування подібних інвестицій у модернізацію в усій країні, що сприятиме як скороченню викидів, так і покращенню умов проживання.",ro:"Această publicație, parte a proiectului de modernizare a clădirilor Mershenq / Programul Națiunilor Unite pentru Dezvoltare (PNUD)-Fondul Verde pentru Climă (GCF), prezintă constatările din sondajele în gospodării care evaluează impactul modernizărilor eficiente din punct de vedere energetic efectuate în clădirile rezidențiale cu mai multe apartamente din Armenia, un tip de locuințe care reprezintă o pondere semnificativă din stocul de clădiri urbane al țării. Evaluarea evaluează schimbările în consumul de energie, costurile de încălzire și confortul și satisfacția raportate de rezidenți în urma intervențiilor de modernizare, cum ar fi izolarea anvelopei clădirii și modernizarea sistemului de încălzire. Deoarece stocul de clădiri rezidențiale din Armenia îmbătrânește în mare măsură construcțiile din epoca sovietică, cu performanțe termice slabe, acest caz oferă dovezi pentru extinderea investițiilor similare de modernizare la nivel național, susținând atât reducerea emisiilor, cât și îmbunătățirea condițiilor de viață.",hy:"Այս հրապարակումը, որը մաս է կազմում Մերշենք/ՄԱԿ-ի զարգացման ծրագրի (ՄԱԶԾ)-Կանաչ կլիմայի հիմնադրամի (GCF) շենքերի վերազինման ծրագրին, ներկայացնում է տնային տնտեսությունների հետազոտությունների արդյունքները, որոնք գնահատում են Հայաստանի բազմաբնակարան բնակելի շենքերի էներգաարդյունավետ վերազինման ազդեցությունը. Գնահատումը գնահատում է էներգիայի սպառման, ջեռուցման ծախսերի և բնակիչների կողմից հաղորդված հարմարավետության և բավարարվածության փոփոխությունները վերազինման միջամտություններից հետո, ինչպիսիք են շենքերի մեկուսացումը և ջեռուցման համակարգի արդիականացումը: Քանի որ Հայաստանի բնակելի շենքերի ֆոնդը հիմնականում ծերանում է խորհրդային ժամանակաշրջանի շինարարությունը վատ ջերմային արդյունավետությամբ, այս դեպքը վկայում է համանման վերազինման ներդրումների մասշտաբի մասին ազգային մակարդակում՝ աջակցելով և՛ արտանետումների նվազեցմանը, և՛ բարելավված կենսապայմաններին։"},caseLink:"https://www.mershenq.am/en/publications/impact-of-energy-efficient-retrofits-in-residential-buildings"}),e({id:"case-025",slug:"energy-efficient-retrofits-in-syunik-region",companyName:{en:"Energy Efficient Retrofits in Syunik Region",uk:"",ro:"",hy:""},country:"Armenia",sector:["Construction"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Regional building retrofits reduce energy consumption in existing housing and public buildings within Syunik, extending the national resource-efficiency programme to a specific geographic area.",uk:"Модернізація наявних житлових і громадських будівель у регіоні Сюніку зменшує споживання енергії та поширює національну програму ресурсоефективності на конкретний регіон.",ro:"Modernizările clădirilor regionale reduc consumul de energie în locuințele existente și clădirile publice din Syunik, extinzând programul național de eficiență a resurselor la o anumită zonă geografică.",hy:"Մարզային շենքերի վերազինումը նվազեցնում է էներգիայի սպառումը Սյունիքի տարածքում գործող բնակարանային և հասարակական շենքերում՝ ընդարձակելով ազգային ռեսուրսների արդյունավետության ծրագիրը որոշակի աշխարհագրական տարածքի վրա։"},summary:{en:"This regional factsheet summarizes the rollout and impact of energy-efficient building retrofits specifically within the Syunik region of Armenia, highlighting localised outcomes of the national retrofit programme.",uk:"Energy Efficient Retrofits in Syunik Region – це регіональний інформаційний бюлетень, який підсумовує впровадження та результати енергоефективної термомодернізації будівель саме в регіоні Сюнік у Вірменії, висвітлюючи локальні досягнення національної програми з модернізації.",ro:"Această fișă informativă regională rezumă implementarea și impactul modernizărilor clădirilor eficiente din punct de vedere energetic, în special în regiunea Syunik din Armenia, evidențiind rezultatele localizate ale programului național de modernizare.",hy:"Այս տարածաշրջանային տեղեկատվական թերթիկը ամփոփում է էներգաարդյունավետ շենքերի վերազինման ներդրումն ու ազդեցությունը հատկապես Հայաստանի Սյունիքի մարզում` ընդգծելով վերազինման ազգային ծրագրի տեղայնացված արդյունքները։"},description:{en:"This factsheet, produced under the Mershenq / United Nations Development Programme (UNDP)-Green Climate Fund (GCF) retrofit project, provides a regional summary of energy-efficient building retrofit activities carried out in Armenia's Syunik region. It documents the scope of interventions delivered locally and the resulting energy and cost outcomes, offering a geographically specific complement to the broader national assessments of the retrofit programme. Regional case studies of this kind help demonstrate how a national resource-efficiency initiative translates into localised results, supporting continued investment and replication across other Armenian regions with differing climate and building-stock conditions.",uk:"Цей інформаційний матеріал підготовлено в межах проєкту Mershenq / ПРООН і Зеленого кліматичного фонду (GCF) з модернізації будівель. У ньому узагальнено результати заходів з енергоефективної модернізації будівель, проведених у регіоні Сюнік (Вірменія). Матеріал містить інформацію про масштаби реалізованих на місцевому рівні заходів, а також результати щодо споживання енергії та витрат, доповнюючи ширші загальнонаціональні оцінювання програми модернізації даними з конкретного регіону. Регіональні приклади такого типу допомагають продемонструвати, як національна ініціатива з підвищення ресурсоефективності дає конкретні результати на місцевому рівні, та сприяють подальшим інвестиціям і поширенню подібних заходів в інших регіонах Вірменії, які мають різні кліматичні умови та стан житлового фонду.",ro:"Această fișă informativă, produsă în cadrul proiectului de modernizare Mershenq / Programul Națiunilor Unite pentru Dezvoltare (UNDP)-Fondul Verde pentru Climă (GCF), oferă un rezumat regional al activităților de modernizare a clădirilor eficiente din punct de vedere energetic desfășurate în regiunea Syunik din Armenia. Documentează domeniul de aplicare al intervențiilor efectuate la nivel local și rezultatele energetice și ale costurilor rezultate, oferind o completare specifică geografic la evaluările naționale mai ample ale programului de modernizare. Studiile de caz regionale de acest fel ajută la demonstrarea modului în care o inițiativă națională de eficiență a resurselor se traduce în rezultate localizate, susținând investițiile continue și replicarea în alte regiuni ale Armeniei cu condiții climatice și stocuri de clădiri diferite.",hy:"Այս տեղեկատվական թերթիկը, որը պատրաստվել է Մերշենք/ՄԱԿ-ի Զարգացման Ծրագրի (ՄԱԶԾ)-Կլիմայի Կանաչ Հիմնադրամի (GCF) վերազինման ծրագրի շրջանակներում, ներկայացնում է Հայաստանի Սյունիքի մարզում իրականացվող էներգաարդյունավետ շենքերի վերազինման աշխատանքների տարածաշրջանային ամփոփագիրը: Այն փաստագրում է տեղում իրականացվող միջամտությունների շրջանակը և դրա արդյունքում էներգիայի և ծախսերի արդյունքները՝ առաջարկելով աշխարհագրորեն հատուկ լրացում վերազինման ծրագրի ավելի լայն ազգային գնահատականներին: Այս տեսակի տարածաշրջանային դեպքերի ուսումնասիրություններն օգնում են ցույց տալ, թե ինչպես է ազգային ռեսուրսների արդյունավետության նախաձեռնությունը վերածվում տեղայնացված արդյունքների՝ աջակցելով շարունակական ներդրումներին և կրկնօրինակմանը Հայաստանի այլ տարածաշրջաններում՝ տարբեր կլիմայական և շենքային պայմաններով։"},caseLink:"https://www.mershenq.am/en/publications/factsheet-syuink-region"}),e({id:"case-026",slug:"arminashogh-llc",companyName:{en:"Arminashogh LLC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Heat-recovery ventilation and resource-efficient baking processes reduce the energy (electricity and natural gas) required per unit of food produced.",uk:"Вентиляція з рекуперацією тепла та ресурсоощадні процеси випікання дають змогу зменшити кількість енергії – електроенергії та природного газу – необхідної для виробництва одиниці харчової продукції.",ro:"Ventilația cu recuperare de căldură și procesele de coacere eficiente din punct de vedere al resurselor reduc energia (electricitate și gaz natural) necesară per unitate de hrană produsă.",hy:"Ջերմային վերականգնող օդափոխությունը և ռեսուրսների համար արդյունավետ թխման գործընթացները նվազեցնում են արտադրվող մթերքի մեկ միավորի համար պահանջվող էներգիան (էլեկտրաէներգիա և բնական գազ)։"},summary:{en:"Arminashogh LLC, a bakery producing cakes, pastries, and bread, modernized its ventilation system with heat recovery and adopted resource-efficient baking methods, reducing electricity use by 2.6% and natural gas use by 3.8%.",uk:"Arminashogh LLC – це пекарня, що виготовляє торти, тістечка та хліб. Вона модернізувала систему вентиляції з рекуперацією тепла та впровадила ресурсоефективні методи випікання, зменшивши споживання електроенергії на 2,6%, а природного газу – на 3,8%.",ro:"Arminashogh LLC, o brutărie care produce prăjituri, produse de patiserie și pâine, și-a modernizat sistemul de ventilație cu recuperare de căldură și a adoptat metode de coacere eficiente din punct de vedere al resurselor, reducând consumul de energie electrică cu 2,6% și consumul de gaze naturale cu 3,8%.",hy:"Տորթերի, խմորեղենի և հացի արտադրությամբ զբաղվող «Արմինաշող» ՍՊԸ-ն արդիականացրել է իր օդափոխության համակարգը ջերմավերականգնմամբ և որդեգրել է ռեսուրսների արդյունավետ թխման մեթոդներ՝ կրճատելով էլեկտրաէներգիայի օգտագործումը 2,6%-ով և բնական գազի սպառումը 3,8%-ով։"},description:{en:"As a participant in the EU4Environment Resource Efficient and Cleaner Production (RECP) programme, Arminashogh LLC, a food production small-medium enterprise (SME) specialising in cakes, pastries, and bread, underwent a resource-efficiency audit that identified opportunities to reduce energy waste in its baking operations. The company modernised its ventilation system to incorporate heat recovery, capturing and reusing heat that would otherwise be lost from baking ovens, and adjusted its baking methods to reduce unnecessary energy use. These measures delivered measurable savings of 2.6% in electricity consumption and 3.8% in natural gas consumption, demonstrating how relatively targeted process improvements can generate meaningful resource savings for food-sector small-medium enterprises (SMEs).",uk:"МСП «Arminashogh LLC» стало учасником програми ЄС EU4Environment, зокрема компоненту «Ресурсоефективне та чисте виробництво». Це підприємство харчової промисловості, що спеціалізується на виробництві тортів, кондитерських виробів та хліба. За результатами РЕЧВ-оцінки було визначено можливості для зменшення втрат енергії у виробничих процесах. Компанія модернізувала систему вентиляції, встановивши систему рекуперації тепла, яка дає змогу вловлювати та повторно використовувати тепло, що інакше втрачалося б під час роботи печей, а також скоригувала методи випікання для зменшення зайвого споживання енергії. Завдяки цим заходам споживання електроенергії скоротилося на 2,6%, а природного газу – на 3,8%, що демонструє, як цілеспрямоване вдосконалення виробничих процесів може забезпечити відчутну економію ресурсів для малих і середніх підприємств харчової промисловості.",ro:"În calitate de participant la programul EU4Environment Resource Efficient and Cleaner Production (RECP), Arminashogh LLC, o întreprindere mică-medie (IMM) de producție alimentară specializată în prăjituri, produse de patiserie și pâine, a fost supusă unui audit de eficiență a resurselor care a identificat oportunități de reducere a risipei de energie în operațiunile sale de panificație. Compania și-a modernizat sistemul de ventilație pentru a încorpora recuperarea căldurii, captarea și reutilizarea căldurii care altfel s-ar pierde din cuptoarele de coacere și și-a ajustat metodele de coacere pentru a reduce consumul de energie inutil. Aceste măsuri au generat economii măsurabile de 2,6% la consumul de energie electrică și 3,8% la consumul de gaze naturale, demonstrând modul în care îmbunătățirile relativ direcționate ale procesului pot genera economii semnificative de resurse pentru întreprinderile mici-mijlocii (IMM-uri) din sectorul alimentar.",hy:"Որպես EU4Environment ռեսուրսների արդյունավետ և մաքուր արտադրություն (RECP) ծրագրի մասնակից՝ «Արմինաշող» ՍՊԸ-ն՝ սննդամթերքի արտադրությամբ զբաղվող փոքր-միջին ձեռնարկություն (ՓՄՁ), որը մասնագիտացած է թխվածքների, խմորեղենի և հացի մեջ, ենթարկվել է ռեսուրսների արդյունավետության աուդիտի, որը հայտնաբերել է էներգիայի թափոնների նվազեցման հնարավորություններ իր թխման աշխատանքներում: Ընկերությունը արդիականացրել է իր օդափոխության համակարգը՝ ներառելով ջերմության վերականգնումը, որսալով և վերօգտագործելով ջերմությունը, որն այլապես կկորցներ թխման վառարաններից, և հարմարեցրեց իր թխման մեթոդները՝ նվազեցնելու ավելորդ էներգիայի օգտագործումը: Այս միջոցառումներն ապահովել են 2,6% էլեկտրաէներգիայի սպառման և 3,8% բնական գազի սպառման չափելի խնայողություններ՝ ցույց տալով, թե գործընթացների համեմատաբար նպատակային բարելավումները կարող են զգալի ռեսուրսների խնայողություններ առաջացնել սննդի ոլորտի փոքր և միջին ձեռնարկությունների համար (ՓՄՁ)։"},caseLink:"https://www.eu4environment.org/app/uploads/2024/02/Arminashogh-LLC.pdf"}),e({id:"case-027",slug:"ashtarak-dzoo-llc",companyName:{en:"Ashtarak Dzoo LLC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Fuel switching, lighting upgrades, and improved insulation collectively reduce the energy intensity of poultry house heating and lighting operations.",uk:"Заміна виду палива, модернізація освітлення та покращення теплоізоляції в комплексі зменшують енергоємність опалення та освітлення пташників.",ro:"Comutarea combustibilului, îmbunătățirea iluminatului și izolarea îmbunătățită reduc în mod colectiv intensitatea energetică a operațiunilor de încălzire și iluminare a caselor de păsări.",hy:"Վառելիքի փոխարկումը, լուսավորության արդիականացումը և բարելավված մեկուսացումը միասին նվազեցնում են թռչնաբուծական տան ջեռուցման և լուսավորության գործողությունների էներգիայի ինտենսիվությունը։"},summary:{en:"Ashtarak Dzoo, a leading Armenian egg production and poultry company, adopted Resource Efficient and Cleaner Production (RECP) measures including switching from electric to natural gas heating, upgrading to light-emitting diode (LED) lighting, and improving poultry house insulation.",uk:"Ashtarak Dzoo, провідна вірменська компанія з виробництва яєць і птахівництва, запровадила заходи ресурсоефективного та чистого виробництва (RECP), включаючи перехід з електричного опалення на природний газ, модернізацію світлодіодного (LED) освітлення та покращення ізоляції пташників.",ro:"Ashtarak Dzoo, o companie armeană de top în producția de ouă și păsări de curte, a adoptat măsuri de producție eficientă și mai curată din punct de vedere al resurselor (RECP), inclusiv trecerea de la încălzirea electrică la încălzirea pe gaz natural, trecerea la iluminatul cu diode emițătoare de lumină (LED) și îmbunătățirea izolației adăpostului de păsări.",hy:"Ձվի արտադրության և թռչնաբուծության հայկական առաջատար «Աշտարակի ձո» ընկերությունն ընդունել է ռեսուրսների արդյունավետ և մաքուր արտադրության (RECP) միջոցառումներ՝ ներառյալ էլեկտրականությունից բնական գազի ջեռուցման, լուսադիոդային (LED) լուսավորության արդիականացում և թռչնանոցների մեկուսացման բարելավում։"},description:{en:"Ashtarak Dzoo LLC is one of Armenia's leading egg production and poultry companies, and participated in the EU4Environment Resource Efficient and Cleaner Production (RECP) programme to address the significant energy demands of maintaining controlled-temperature poultry houses. The company implemented several measures identified through its Resource Efficient and Cleaner Production (RECP) audit: replacing electric heaters with natural gas heating (a lower-cost and often lower-emission energy source), upgrading lighting systems to light-emitting diode (LED) lighting to reduce electricity consumption, and improving the thermal insulation of poultry houses to reduce heat loss. Together, these interventions significantly reduced the company's overall energy footprint, illustrating how targeted efficiency measures can be applied across an intensive livestock operation.",uk:"Ashtarak Dzoo LLC – одна з провідних вірменських компаній із виробництва яєць і продукції птахівництва. Компанія взяла участь у програмі ЄС EU4Environment, зокрема у компоненті «Ресурсоефективне та чисте виробництво», щоб зменшити значне споживання енергії, необхідної для підтримання контрольованої температури у пташниках. За результатами РЕЧВ-оцінки компанія впровадила кілька визначених заходів: замінила електричні обігрівачі на газове опалення, яке має нижчу вартість і часто супроводжується меншими викидами; замінила освітлення на світлодіодне, щоб зменшити споживання електроенергії; а також покращила теплоізоляцію пташників для зменшення втрат тепла. У сукупності ці заходи суттєво зменшили загальне енергоспоживання компанії та продемонстрували, як цілеспрямовані заходи з підвищення ефективності можна застосовувати у виробничих процесах інтенсивного тваринництва.",ro:"Ashtarak Dzoo LLC este una dintre cele mai importante companii de producție de ouă și păsări de curte din Armenia și a participat la programul EU4Environment Resource Efficient and Cleaner Production (RECP) pentru a aborda cerințele semnificative de energie pentru menținerea adăposturilor de păsări la temperatură controlată. Compania a implementat mai multe măsuri identificate prin auditul său de producție eficientă și mai curată a resurselor (RECP): înlocuirea încălzitoarelor electrice cu încălzire pe gaz natural (o sursă de energie cu costuri mai mici și adesea cu emisii mai mici), modernizarea sistemelor de iluminat la iluminat cu diode emițătoare de lumină (LED) pentru a reduce consumul de energie electrică și îmbunătățirea izolației termice a adăposturilor de păsări pentru a reduce pierderile de căldură. Împreună, aceste intervenții au redus semnificativ amprenta energetică globală a companiei, ilustrând modul în care măsurile de eficiență direcționate pot fi aplicate într-o exploatare intensivă a animalelor.",hy:"«Աշտարակի Ձոո» ՍՊԸ-ն Հայաստանի ձվի արտադրության և թռչնաբուծության առաջատար ընկերություններից է և մասնակցել է EU4Environment Resource Efficient and Cleaner Production (RECP) ծրագրին՝ վերահսկվող ջերմաստիճանի թռչնատների պահպանման էներգիայի զգալի պահանջները լուծելու համար: Ընկերությունն իրականացրել է մի շարք միջոցառումներ, որոնք բացահայտվել են ռեսուրսների արդյունավետ և մաքուր արտադրության (RECP) աուդիտի միջոցով՝ փոխարինել էլեկտրական ջեռուցիչները բնական գազով ջեռուցմամբ (էժան և հաճախ ավելի ցածր արտանետվող էներգիայի աղբյուր), լուսավորության համակարգերի արդիականացում մինչև լուսադիոդային (LED) լուսավորության՝ էլեկտրաէներգիայի սպառումը նվազեցնելու և թռչնաբուծական տների ջերմամեկուսացման բարելավումը՝ նվազեցնելու ջերմային կորուստները: Միասին այս միջամտությունները զգալիորեն նվազեցրին ընկերության ընդհանուր էներգիայի հետքը՝ ցույց տալով, թե ինչպես կարող են կիրառվել արդյունավետության նպատակային միջոցառումներ ինտենսիվ անասնաբուծության ընթացքում։"},caseLink:"https://www.eu4environment.org/app/uploads/2024/02/Ashtarak-Dzoo-LLC.pdf"}),e({id:"case-028",slug:"elbat-cjsc",companyName:{en:"ELBAT CJSC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Manufacturing"],rStrategies:["Reduce (R2)","Recycle (R8)"],rStrategyDescription:{en:"Closed-loop water reuse recycles process water within the facility rather than discharging and re-sourcing fresh water (Recycle), reducing overall water and resource consumption (Reduce).",uk:"Повторне використання води із замкнутим циклом дає змогу повертати технологічну воду у виробничий цикл замість її скидання та забору нової води із зовнішніх джерел (Перероблення), що зменшує загальне споживання води та інших ресурсів (Скорочення).",ro:"Reutilizarea apei în buclă închisă reciclează apa de proces în cadrul instalației, mai degrabă decât descărcarea și re-aprovizionarea cu apă dulce (Reciclare), reducând consumul general de apă și resurse (Reducere).",hy:"Փակ շղթայով ջրի վերօգտագործումը վերամշակում է ջուրը օբյեկտի ներսում, այլ ոչ թե թարմ ջուր լիցքաթափում և վերամշակում (Վերամշակում), նվազեցնում ջրի և ռեսուրսների ընդհանուր սպառումը (Նվազեցնում)։"},summary:{en:"ELBAT CJSC, a lead-acid battery manufacturer, implemented closed-loop water reuse and cooling systems following a Resource Efficient and Cleaner Production (RECP) audit, reducing industrial water usage and improving the sustainability of its heavy manufacturing processes.",uk:"ЗАТ «ЕЛБАТ», виробник свинцево-кислотних акумуляторів, впровадив замкнуті системи повторного використання води та охолодження після аудиту ресурсоефективного та чистішого виробництва (RECP), зменшивши промислове використання води та підвищивши стабільність важких виробничих процесів.",ro:"ELBAT CJSC, un producător de baterii plumb-acid, a implementat sisteme de reutilizare și răcire a apei în circuit închis în urma unui audit de producție eficientă și mai curată a resurselor (RECP), reducând utilizarea apei industriale și îmbunătățind sustenabilitatea proceselor sale grele de fabricație.",hy:"ELBAT ՓԲԸ-ն՝ կապարաթթվային մարտկոցներ արտադրող, ներդրել է ջրի վերաօգտագործման և հովացման փակ համակարգեր՝ ռեսուրսների արդյունավետ և մաքուր արտադրության (RECP) աուդիտից հետո՝ նվազեցնելով արդյունաբերական ջրի օգտագործումը և բարելավելով իր ծանր արտադրական գործընթացների կայունությունը։"},description:{en:"ELBAT CJSC, a lead-acid battery manufacturer, participated in a Resource Efficient and Cleaner Production (RECP) audit under the EU4Environment programme to assess resource efficiency opportunities within its heavy manufacturing operations. Battery manufacturing is typically water- and energy-intensive, particularly in cooling and process stages. Following the audit, ELBAT implemented closed-loop water reuse and cooling systems, allowing process water to be recirculated and reused rather than continuously drawn from and discharged to external sources. This reduced the company's industrial water consumption and helped optimise its manufacturing processes for lower environmental impact, demonstrating that resource-efficiency principles can be applied even within traditionally resource-intensive heavy industries.",uk:"ELBAT CJSC – виробник свинцево-кислотних акумуляторів, який взяв участь РЕЧВ-оцінці в межах програми EU4Environment, щоб визначити можливості підвищення ресурсоефективності у своїх енергоємних виробничих процесах. Виробництво акумуляторів зазвичай потребує значних обсягів води та енергії, особливо на етапах охолодження та інших технологічних процесах. За результатами РЕЧВ-оцінки ELBAT впровадив замкнені системи повторного використання води та охолодження, які дають змогу циркулювати технологічній воді та використовувати її повторно замість постійного забору води із зовнішніх джерел і скидання відпрацьованої води. Це дало змогу зменшити споживання промислової води та оптимізувати виробничі процеси, зменшуючи їхній вплив на довкілля. Приклад демонструє, що принципи ресурсоефективності можна застосовувати навіть у традиційно ресурсоємних галузях важкої промисловості.",ro:"ELBAT CJSC, un producător de baterii plumb-acid, a participat la un audit de producție eficientă și mai curată a resurselor (RECP) în cadrul programului EU4Environment pentru a evalua oportunitățile de eficiență a resurselor în cadrul operațiunilor sale de producție grele. Fabricarea bateriilor este de obicei consumatoare de apă și energie, în special în etapele de răcire și proces. În urma auditului, ELBAT a implementat sisteme de reutilizare și răcire a apei în circuit închis, permițând recircularea și reutilizarea apei de proces, mai degrabă decât extragerea continuă și evacuarea în surse externe. Acest lucru a redus consumul de apă industrială al companiei și a ajutat la optimizarea proceselor sale de producție pentru un impact mai scăzut asupra mediului, demonstrând că principiile de eficiență a resurselor pot fi aplicate chiar și în industriile grele tradiționale mari consumatoare de resurse.",hy:"ELBAT ՓԲԸ-ն՝ կապարաթթվային մարտկոցներ արտադրող, մասնակցել է ռեսուրսների արդյունավետ և մաքուր արտադրության (RECP) աուդիտին EU4Environment ծրագրի շրջանակներում՝ գնահատելու ռեսուրսների արդյունավետության հնարավորությունները իր ծանր արտադրական գործունեության շրջանակներում: Մարտկոցների արտադրությունը սովորաբար ջրի և էներգիայի խնայողություն է, հատկապես հովացման և գործընթացի փուլերում: Աուդիտից հետո ELBAT-ը ներդրել է ջրի վերաօգտագործման և հովացման փակ օղակով համակարգեր, որոնք թույլ են տալիս վերամշակման և վերաօգտագործման, այլ ոչ թե անընդհատ դուրս բերելու և արտահոսելու արտաքին աղբյուրներից: Սա նվազեցրեց ընկերության արդյունաբերական ջրի սպառումը և օգնեց օպտիմիզացնել արտադրական գործընթացները շրջակա միջավայրի վրա ավելի ցածր ազդեցության համար՝ ցույց տալով, որ ռեսուրսների արդյունավետության սկզբունքները կարող են կիրառվել նույնիսկ ավանդական ռեսուրսներ ինտենսիվ ծանր արդյունաբերություններում։"},caseLink:"https://www.eu4environment.org/app/uploads/2022/04/BC-ELBAT-Armenia.pdf"}),e({id:"case-029",slug:"lukashin-agricultural-association-cc",companyName:{en:"Lukashin Agricultural Association CC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Solar drying and water-heating technology substitutes renewable energy for the electricity previously used in the fruit-drying process, reducing overall electricity consumption.",uk:"Технології сонячного сушіння та нагрівання води замінюють електроенергію, яку раніше використовували для сушіння фруктів, на відновлювану сонячну енергію, що дає змогу скоротити загальне споживання електроенергії.",ro:"Tehnologia de uscare solară și de încălzire a apei înlocuiește energia regenerabilă cu energia electrică utilizată anterior în procesul de uscare a fructelor, reducând consumul total de energie electrică.",hy:"Արևային չորացման և ջրի տաքացման տեխնոլոգիան փոխարինում է վերականգնվող էներգիան մրգերի չորացման գործընթացում նախկինում օգտագործված էլեկտրաէներգիայի փոխարեն՝ նվազեցնելով էլեկտրաէներգիայի ընդհանուր սպառումը։"},summary:{en:"This consumer cooperative of dried-fruit producers installed convective solar dryers and solar water heaters to address high energy costs in fruit drying, cutting electricity usage by 21%.",uk:"Lukashin Agricultural Association CC об’єднує виробників сухофруктів. На території кооперативу встановлено конвективні сонячні сушарки та водонагрівачі, що працюють на сонячній енергії, щоб зменшити високі витрати на енергію під час сушіння фруктів. Завдяки цьому використання електроенергії скоротилося на 21%.",ro:"Această cooperativă de consumatori de producători de fructe uscate a instalat uscătoare solare convective și încălzitoare solare de apă pentru a aborda costurile mari de energie în uscarea fructelor, reducând consumul de energie electrică cu 21%.",hy:"Չոր մրգերի արտադրողների այս սպառողական կոոպերատիվը տեղադրել է կոնվեկտիվ արևային չորանոցներ և արևային ջրատաքացուցիչներ՝ մրգերի չորացման ժամանակ էներգիայի բարձր ծախսերը լուծելու համար՝ նվազեցնելով էլեկտրաէներգիայի օգտագործումը 21%-ով։"},description:{en:"The Lukashin Agricultural Association is a consumer cooperative of farmers producing dried fruit, an energy-intensive process traditionally reliant on electric or fossil-fuel-powered drying equipment. Through participation in the EU4Environment Resource Efficient and Cleaner Production (RECP) programme, the cooperative identified high energy costs associated with fruit drying as a priority area for intervention. It subsequently installed convective solar dryers and solar water heaters, shifting a significant portion of its drying process to renewable solar energy. This resulted in a 21% reduction in electricity usage, a substantial efficiency gain that also reduces the cooperative's exposure to energy price volatility.",uk:"Lukashin Agricultural Association CC – споживчий кооператив фермерів, які виробляють сушені фрукти. Сушіння фруктів – енергоємний процес, який традиційно потребує електричного обладнання або устаткування, що працює на викопному паливі. У межах програми EU4Environment (компоненту «Ресурсоефективне та чисте виробництво») кооператив визначив високі витрати на енергію для сушіння фруктів як пріоритетний напрям для вдосконалення. Згодом кооператив установив конвективні сонячні сушарки та сонячні водонагрівачі, завдяки чому значну частину процесу сушіння було переведено на використання відновлюваної сонячної енергії. Це дозволило скоротити споживання електроенергії на 21%, суттєво підвищити енергоефективність і водночас зменшити залежність кооперативу від коливань цін на енергоносії.",ro:"Asociația Agricolă Lukashin este o cooperativă de consumatori a fermierilor care produc fructe uscate, un proces consumator de energie, bazat în mod tradițional pe echipamente de uscare electrice sau alimentate cu combustibili fosili. Prin participarea la programul EU4Environment Eficient Resource and Cleaner Production (RECP), cooperativa a identificat costurile ridicate ale energiei asociate cu uscarea fructelor ca domeniu prioritar de intervenție. Ulterior, a instalat uscătoare solare convective și încălzitoare solare de apă, transferând o parte semnificativă a procesului său de uscare la energia solară regenerabilă. Acest lucru a dus la o reducere cu 21% a consumului de energie electrică, un câștig substanțial de eficiență care reduce, de asemenea, expunerea cooperativei la volatilitatea prețului energiei.",hy:"Լուկաշին գյուղատնտեսական ասոցիացիան ֆերմերների սպառողական կոոպերատիվ է, որոնք արտադրում են չոր մրգեր, էներգիա պահանջող գործընթաց, որը ավանդաբար կախված է էլեկտրական կամ հանածո վառելիքով աշխատող չորացման սարքավորումներից: EU4Environment Resource Efficient and Cleaner Production (RECP) ծրագրին մասնակցության միջոցով կոոպերատիվը հայտնաբերել է էներգիայի բարձր ծախսերը՝ կապված մրգերի չորացման հետ, որպես միջամտության առաջնահերթ ոլորտ: Այն հետագայում տեղադրեց կոնվեկտիվ արևային չորանոցներ և արևային ջրատաքացուցիչներ՝ չորացման գործընթացի զգալի մասը տեղափոխելով վերականգնվող արևային էներգիա: Սա հանգեցրեց էլեկտրաէներգիայի օգտագործման 21%-ով կրճատմանը, արդյունավետության զգալի աճ, որը նաև նվազեցնում է կոոպերատիվի ազդեցությունը էներգիայի գների անկայունության նկատմամբ։"},caseLink:"https://www.eu4environment.org/app/uploads/2024/02/Lukashin-CC.pdf"}),e({id:"case-030",slug:"galik-llc",companyName:{en:"Galik LLC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Mining and Minerals"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Optimising kiln roasting and crushing processes reduces the energy required per unit of lime produced, lowering the energy share of overall production costs.",uk:"Оптимізація процесів випалювання вапна та дроблення дає змогу зменшити кількість енергії, необхідної для виробництва одиниці продукції, та скоротити частку енергетичних витрат у загальних виробничих витратах.",ro:"Optimizarea proceselor de prăjire și zdrobire în cuptor reduce energia necesară per unitate de var produsă, scăzând ponderea energiei din costurile totale de producție.",hy:"Վառարաններում թրծման և մանրացման գործընթացների օպտիմալացումը նվազեցնում է արտադրվող կրաքարի մեկ միավորի համար պահանջվող էներգիան՝ նվազեցնելով ընդհանուր արտադրության ծախսերի էներգիայի բաժինը։"},summary:{en:"Galik LLC, a lime production facility supplying the metallurgy sector, used Resource Efficient and Cleaner Production (RECP) assessments to optimize its roasting kilns and crushing processes, targeting an energy footprint that made up 22% of total production costs.",uk:"ТОВ «Галік», підприємство з виробництва вапна, яке постачає металургійний сектор, використало оцінку ресурсоефективного та чистого виробництва (RECP) для оптимізації своїх печей випалу та процесів дроблення, орієнтуючись на енергетичний слід, який становив 22% загальних виробничих витрат.",ro:"Galik LLC, o unitate de producție de var care aprovizionează sectorul metalurgic, a folosit evaluări de producție mai curată și eficientă din resurse (RECP) pentru a-și optimiza cuptoarele de prăjire și procesele de zdrobire, vizând o amprentă energetică care a reprezentat 22% din costurile totale de producție.",hy:"«Գալիկ» ՍՊԸ-ն՝ մետալուրգիական ոլորտը մատակարարող կրաքարի արտադրամասը, օգտագործել է ռեսուրսների արդյունավետ և մաքուր արտադրություն (RECP) գնահատումները՝ իր թրծման վառարանները և ջարդման գործընթացները օպտիմալացնելու համար՝ թիրախավորելով էներգիայի թողունակությունը, որը կազմում է արտադրության ընդհանուր ծախսերի 22%-ը։"},description:{en:"Galik LLC operates a lime production facility in Armenia's Ararat region, supplying the domestic metallurgy sector. Lime production is highly energy-intensive due to the high-temperature roasting (calcination) process required, which had previously accounted for approximately 22% of the company's total production costs. Through a Resource Efficient and Cleaner Production (RECP) assessment under the EU4Environment programme, Galik identified opportunities to optimise its roasting kilns and crushing processes to reduce energy consumption per unit of output. This case highlights how resource-efficiency interventions in energy-intensive heavy industry can directly improve cost competitiveness alongside environmental performance.",uk:"Galik LLC – підприємство з виробництва вапна, що постачає продукцію для металургійного сектору, – використало оцінку за методикою РЕЧВ для оптимізації роботи випалювальних печей та процесів подрібнення, зосередившись на зниженні енергетичних витрат, які становили 22% від загальної собівартості продукції. У межах РЕЧВ-оцінки програми EU4Environment, Galik визначила можливості оптимізації процесів випалювання вапна та дроблення для зменшення споживання енергії на одиницю продукції. Цей приклад демонструє, як заходи з підвищення ресурсоефективності в енергоємній важкій промисловості можуть безпосередньо сприяти підвищенню конкурентоспроможності за витратами та одночасно покращувати екологічні показники.",ro:"Galik LLC operează o unitate de producție de var în regiunea Ararat din Armenia, furnizând sectorul metalurgic intern. Producția de var este foarte consumatoare de energie datorită procesului de prăjire la temperatură înaltă (calcinare) necesar, care anterior reprezentase aproximativ 22% din costurile totale de producție ale companiei. Printr-o evaluare a producției eficiente și mai curată a resurselor (RECP) în cadrul programului EU4Environment, Galik a identificat oportunități de a-și optimiza cuptoarele de prăjire și procesele de zdrobire pentru a reduce consumul de energie pe unitatea de producție. Acest caz evidențiază modul în care intervențiile de utilizare eficientă a resurselor în industria grea consumatoare de energie pot îmbunătăți în mod direct competitivitatea costurilor, alături de performanța de mediu.",hy:"«Գալիկ» ՍՊԸ-ն Հայաստանի Արարատի մարզում շահագործում է կրաքարի արտադրություն՝ մատակարարելով ներքին մետալուրգիայի ոլորտը: Կրաքարի արտադրությունը շատ էներգատար է՝ շնորհիվ բարձր ջերմաստիճանի թրծման (կալցինացման) պահանջվող գործընթացի, որը նախկինում կազմում էր ընկերության արտադրության ընդհանուր ծախսերի մոտավորապես 22%-ը: EU4Environment ծրագրի շրջանակներում ռեսուրսների արդյունավետ և մաքուր արտադրության (RECP) գնահատման միջոցով «Գալիկը» հայտնաբերել է իր թրծման վառարանների և ջարդման գործընթացները օպտիմալացնելու հնարավորություններ՝ մեկ միավորի համար էներգիայի սպառումը նվազեցնելու համար: Այս դեպքը ընդգծում է, թե ինչպես էներգատար ծանր արդյունաբերության մեջ ռեսուրսների արդյունավետ միջամտությունները կարող են ուղղակիորեն բարելավել ծախսերի մրցունակությունը բնապահպանական կատարողականի հետ մեկտեղ։"},caseLink:"https://www.eu4environment.org/app/uploads/2024/02/Galik-LLC.pdf"}),e({id:"case-031",slug:"ararat-chanshin-llc",companyName:{en:"Ararat Chanshin LLC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Construction"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Optimised equipment and bitumen-sealing processes reduce the materials and energy consumed per unit of asphalt and gravel produced and per infrastructure contract delivered.",uk:"Оптимізація використання обладнання та процесів бітумного герметизування дає змогу зменшити обсяги матеріалів та енергії, що споживаються на одиницю виробленого асфальту та щебеню і на виконання кожного інфраструктурного контракту.",ro:"Echipamentele optimizate și procesele de etanșare cu bitum reduc materialele și energia consumată per unitate de asfalt și pietriș produsă și pe contract de infrastructură livrat.",hy:"Օպտիմալացված սարքավորումները և բիտումի կնքման գործընթացները նվազեցնում են արտադրվող ասֆալտի և մանրախիճի միավորի և մատակարարված ենթակառուցվածքի պայմանագրով սպառվող նյութերն ու էներգիան։"},summary:{en:"Ararat Chanshin, a road-building and civil construction company producing asphalt and crushed gravel, applied Resource Efficient and Cleaner Production (RECP) methodologies to optimize equipment use and bitumen sealing processes, lowering resource consumption per contract.",uk:"Ararat Chanshin, дорожньо-будівельна компанія, що виробляє асфальт і щебінь, застосувала методологію ресурсоефективного та чистого виробництва (RECP) для оптимізації використання обладнання та процесів ущільнення бітуму, зменшивши споживання ресурсів за контрактом.",ro:"Ararat Chanshin, o companie de construcții de drumuri și construcții civile care produce asfalt și pietriș zdrobit, a aplicat metodologii de producție eficientă și mai curată a resurselor (RECP) pentru a optimiza utilizarea echipamentelor și procesele de etanșare cu bitum, reducând consumul de resurse pe contract.",hy:"«Արարատ Ճանշին»՝ ասֆալտ և մանրացված մանրախիճ արտադրող ճանապարհաշինական և քաղաքացիական շինարարական ընկերությունը, կիրառել է ռեսուրսների արդյունավետ և մաքուր արտադրություն (RECP) մեթոդոլոգիա՝ սարքավորումների օգտագործման և բիտումի կնքման գործընթացները օպտիմալացնելու համար՝ նվազեցնելով ռեսուրսների սպառումը յուրաքանչյուր պայմանագրով։"},description:{en:"Ararat Chanshin LLC is a road-building and civil construction company producing asphalt and crushed gravel for infrastructure projects across Armenia. Through the EU4Environment Resource Efficient and Cleaner Production (RECP) programme, the company applied resource-efficiency methodologies to its production processes, combining more technologically advanced equipment with optimised bitumen sealing techniques. These changes reduced the resource consumption associated with each infrastructure contract, lowering both material waste and energy use in asphalt and gravel production. The case demonstrates how Resource Efficient and Cleaner Production (RECP) principles can be applied within the construction materials sector, where resource intensity is often driven by equipment efficiency and process control.",uk:"Ararat Chanshin LLC – компанія, що займається будівництвом доріг та цивільним будівництвом, виробляє асфальт і щебінь для інфраструктурних проєктів у всій Вірменії. У межах програми EU4Environment (компоненту «Ресурсоефективне та чисте виробництво») компанія застосувала методи підвищення ресурсоефективності у своїх виробничих процесах, поєднавши технологічно досконаліше обладнання з оптимізованими методами бітумного герметизування. Ці зміни дозволили зменшити споживання ресурсів, пов’язане з виконанням кожного інфраструктурного контракту, скоротивши як втрати матеріалів, так і споживання енергії під час виробництва асфальту та щебеню. Приклад демонструє, як принципи РЕЧВ можна застосовувати у секторі будівельних матеріалів, де ресурсоємність часто залежить від ефективності обладнання та контролю виробничих процесів.",ro:"Ararat Chanshin LLC este o companie de construcții de drumuri și construcții civile care produce asfalt și pietriș zdrobit pentru proiecte de infrastructură în Armenia. Prin programul EU4Environment Resource Efficient and Cleaner Production (RECP), compania a aplicat metodologii de eficiență a resurselor proceselor sale de producție, combinând echipamente mai avansate din punct de vedere tehnologic cu tehnici optimizate de etanșare cu bitum. Aceste schimbări au redus consumul de resurse asociat fiecărui contract de infrastructură, reducând atât deșeurile de materiale, cât și utilizarea energiei în producția de asfalt și pietriș. Cazul demonstrează modul în care principiile de producție eficientă și mai curată a resurselor (RECP) pot fi aplicate în sectorul materialelor de construcții, unde intensitatea resurselor este adesea determinată de eficiența echipamentelor și de controlul procesului.",hy:"«Արարատ Ճանշին» ՍՊԸ-ն ճանապարհաշինական և քաղաքացիական շինարարական ընկերություն է, որն արտադրում է ասֆալտ և մանրացված մանրախիճ Հայաստանի ենթակառուցվածքային ծրագրերի համար: EU4Environment Resource Efficient and Cleaner Production (RECP) ծրագրի միջոցով ընկերությունը կիրառել է ռեսուրսների արդյունավետության մեթոդոլոգիաներ իր արտադրական գործընթացներում՝ համատեղելով ավելի տեխնոլոգիապես առաջադեմ սարքավորումները օպտիմիզացված բիտումի կնքման տեխնիկայի հետ: Այս փոփոխությունները նվազեցրին յուրաքանչյուր ենթակառուցվածքի պայմանագրի հետ կապված ռեսուրսների սպառումը` նվազեցնելով ինչպես նյութական թափոնները, այնպես էլ էներգիայի օգտագործումը ասֆալտի և մանրախիճի արտադրության մեջ: Օրինակը ցույց է տալիս, թե ինչպես կարող են կիրառվել ռեսուրսների արդյունավետ և ավելի մաքուր արտադրություն (RECP) սկզբունքները շինանյութերի ոլորտում, որտեղ ռեսուրսների ինտենսիվությունը հաճախ պայմանավորված է սարքավորումների արդյունավետությամբ և գործընթացի վերահսկմամբ։"},caseLink:"https://www.eu4environment.org/app/uploads/2022/04/BC-ARARAT-CHANSIN-Armenia.pdf"}),e({id:"case-032",slug:"lusia-food",companyName:{en:"Lusia Food",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Improved housekeeping practices and equipment modernisation reduce both organic waste generation and energy consumption per unit of food product manufactured.",uk:"Удосконалення практик належного господарювання та модернізація обладнання дають змогу одночасно скоротити утворення органічних відходів і споживання енергії на одиницю виробленої харчової продукції.",ro:"Practicile de menaj îmbunătățite și modernizarea echipamentelor reduc atât generarea de deșeuri organice, cât și consumul de energie per unitate de produs alimentar fabricat.",hy:"Տնային տնտեսության բարելավված գործելակերպը և սարքավորումների արդիականացումը նվազեցնում են ինչպես օրգանական թափոնների արտադրությունը, այնպես էլ էներգիայի սպառումը արտադրված սննդամթերքի մեկ միավորի համար։"},summary:{en:"Lusia Food, a regional food-sector SME, adopted cleaner production strategies and modernized processing equipment to reduce organic waste and lower specific energy consumption per product unit.",uk:"Lusia Food, регіональне МСП харчового сектору, прийняло стратегію чистішого виробництва та модернізувало технологічне обладнання для зменшення органічних відходів і питомого споживання енергії на одиницю продукту.",ro:"Lusia Food, un IMM regional din sectorul alimentar, a adoptat strategii de producție mai curate și a modernizat echipamentele de procesare pentru a reduce deșeurile organice și a reduce consumul specific de energie pe unitatea de produs.",hy:"Սննդի ոլորտի տարածաշրջանային ՓՄՁ Lusia Food-ն ընդունել է ավելի մաքուր արտադրության ռազմավարություններ և վերամշակման արդիականացված սարքավորումներ՝ նվազեցնելու օրգանական թափոնները և նվազեցնելու հատուկ էներգիայի սպառումը մեկ միավորի համար։"},description:{en:"Lusia Food is a regional Armenian SME operating in the food processing sector that participated in the EU4Environment Resource Efficient and Cleaner Production (RECP) programme to improve its environmental and resource performance. The company adopted cleaner production strategies, including improved 'good housekeeping' practices such as better process monitoring, spill prevention, and material handling, alongside modernising its processing equipment. These combined measures reduced the volume of organic waste generated during production and lowered the specific energy consumption required per unit of food product, illustrating how operational and equipment-level interventions can be paired for compounding resource-efficiency gains.",uk:"Lusia Food – регіональне МСП у Вірменії, що працює у сфері продовольства та взяло участь у програмі EU4Environment (компоненту «Ресурсоефективне та чисте виробництво»), щоб підвищити екологічні показники та ресурсоефективність своєї діяльності. Компанія впровадила стратегії більш чистого виробництва, зокрема вдосконалила практики належного господарювання, як-от поліпшення контролю за виробничими процесами, запобігання проливам і втратам та вдосконалення поводження з матеріалами, а також модернізувала обладнання для перероблення. Сукупне застосування цих заходів дозволило скоротити обсяги органічних відходів, що утворюються під час виробництва, та зменшити питоме споживання енергії на одиницю харчової продукції. Цей приклад демонструє, як поєднання операційних заходів і модернізації обладнання може забезпечити додаткові переваги у підвищенні ресурсоефективності.",ro:"Lusia Food este o IMM regională armeană care operează în sectorul prelucrării alimentelor care a participat la programul EU4Environment Eficient Resource and Cleaner Production (RECP) pentru a-și îmbunătăți performanța de mediu și a resurselor. Compania a adoptat strategii de producție mai curate, inclusiv practici îmbunătățite de „bună întreținere”, cum ar fi o mai bună monitorizare a procesului, prevenirea scurgerilor și manipularea materialelor, alături de modernizarea echipamentului său de procesare. Aceste măsuri combinate au redus volumul de deșeuri organice generate în timpul producției și au redus consumul specific de energie necesar per unitate de produs alimentar, ilustrând modul în care intervențiile operaționale și la nivel de echipament pot fi asociate pentru a combina câștiguri de eficiență a resurselor.",hy:"Lusia Food-ը տարածաշրջանային հայկական ՓՄՁ է, որը գործում է սննդի վերամշակման ոլորտում, որը մասնակցել է EU4Environment Resource Efficient and Cleaner Production (RECP) ծրագրին՝ բարելավելու իր բնապահպանական և ռեսուրսների արդյունավետությունը: Ընկերությունը որդեգրեց ավելի մաքուր արտադրության ռազմավարություններ, ներառյալ բարելավված «տնային տնտեսության» բարելավված պրակտիկաները, ինչպիսիք են գործընթացի ավելի լավ մոնիտորինգը, արտահոսքի կանխումը և նյութերի մշակումը, ինչպես նաև վերամշակող սարքավորումների արդիականացումը: Այս համակցված միջոցառումները նվազեցրին արտադրության ընթացքում առաջացած օրգանական թափոնների ծավալը և նվազեցրին սննդամթերքի մեկ միավորի համար պահանջվող էներգիայի հատուկ սպառումը, ինչը ցույց է տալիս, թե ինչպես կարող են գործառնական և սարքավորումների մակարդակի միջամտությունները զուգակցվել ռեսուրսների արդյունավետության բարձրացման համար։"},caseLink:"https://www.eu4environment.org/app/uploads/2024/02/Lusia-Food.pdf"}),e({id:"case-033",slug:"erpin-agricultural-cooperative",companyName:{en:"Erpin Agricultural Cooperative",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Process improvements identified through the Resource Efficient and Cleaner Production (RECP) audit reduce both biological (organic) waste generation and water consumption per unit of dairy product processed.",uk:"Удосконалення виробничих процесів, визначені за результатами аудиту ресурсоефективного та чистого виробництва, дають змогу одночасно скоротити утворення біологічних (органічних) відходів і споживання води на одиницю переробленої молочної продукції.",ro:"Îmbunătățirile proceselor identificate prin auditul de producție eficientă și mai curată a resurselor (RECP) reduc atât generarea de deșeuri biologice (organice), cât și consumul de apă per unitate de produs lactat procesat.",hy:"Ռեսուրսների արդյունավետ և ավելի մաքուր արտադրություն (RECP) աուդիտի միջոցով հայտնաբերված գործընթացների բարելավումները նվազեցնում են ինչպես կենսաբանական (օրգանական) թափոնների առաջացումը, այնպես էլ ջրի սպառումը վերամշակված կաթնամթերքի մեկ միավորի հաշվով։"},summary:{en:"Erpin Agricultural Cooperative, a dairy processing SME, used a Resource Efficient and Cleaner Production (RECP) audit to identify inefficiencies in its milk processing lines, focusing interventions on minimizing biological waste and reducing water use per unit of dairy produced.",uk:"Erpin Agricultural Cooperative – це МСП із перероблення молока. Підприємство використало результати аудиту за методикою ресурсоефективного та чистого виробництва для виявлення неефективностей на своїх лініях із перероблення молока, зосередивши заходи на мінімізації біологічних відходів і скороченні споживання води на одиницю виробленої молочної продукції.",ro:"Cooperativa Agricolă Erpin, un IMM de procesare a produselor lactate, a folosit un audit de producție eficientă și mai curată a resurselor (RECP) pentru a identifica ineficiențele în liniile sale de procesare a laptelui, concentrând intervențiile pe minimizarea deșeurilor biologice și reducerea consumului de apă pe unitatea de lapte produs.",hy:"«Էրփին» գյուղատնտեսական կոոպերատիվը, որը կաթնամթերքի վերամշակող ՓՄՁ-ն է, օգտագործել է ռեսուրսների արդյունավետ և մաքուր արտադրություն (RECP) աուդիտ՝ հայտնաբերելու անարդյունավետությունը իր կաթի վերամշակման գծերում՝ կենտրոնացնելով միջամտությունները կենսաբանական թափոնները նվազագույնի հասցնելու և արտադրված մեկ միավոր կաթնամթերքի համար ջրի օգտագործումը նվազեցնելու վրա։"},description:{en:"Erpin Agricultural Cooperative operates a dairy processing facility that participated in the EU4Environment Resource Efficient and Cleaner Production (RECP) programme to assess resource use across its milk processing lines. Dairy processing is typically both water- and waste-intensive, given the volume of water used for cleaning and processing and the biological waste (such as whey and rinse residues) generated. The Resource Efficient and Cleaner Production (RECP) audit identified specific inefficiencies within Erpin's processing operations, leading to interventions focused on minimising biological waste output and reducing the water footprint associated with each unit of dairy product processed. This case reflects the programme's application to smaller agricultural cooperatives operating food processing facilities.",uk:"Erpin Agricultural Cooperative – сільськогосподарський кооператив, який здійснює перероблення молока та взяв участь у програмі EU4Environment (компонент «Ресурсоефективне та чисте виробництво»), щоб оцінити використання ресурсів на виробничих лініях із перероблення молока. Цей технологічний процес зазвичай потребує значних обсягів води та супроводжується утворенням значної кількості відходів, зокрема через використання води для очищення й перероблення та утворення біологічних відходів, як-от сироватка та залишки після промивання. Аудит завдяки РЕЧВ-оцінці виявив конкретні неефективні процеси у виробничій діяльності Erpin, що дало змогу визначити заходи, спрямовані на мінімізацію утворення біологічних відходів і скорочення споживання води на кожну одиницю переробленої молочної продукції. Цей приклад демонструє застосування підходів програми до невеликих сільськогосподарських кооперативів, які мають потужності для перероблення харчової продукції.",ro:"Cooperativa Agricolă Erpin operează o unitate de procesare a produselor lactate care a participat la programul EU4Environment Producție eficientă și mai curată a resurselor (RECP) pentru a evalua utilizarea resurselor pe liniile sale de procesare a laptelui. Prelucrarea produselor lactate este de obicei consumatoare atât de apă, cât și de deșeuri, având în vedere volumul de apă utilizat pentru curățare și procesare și deșeurile biologice (cum ar fi zerul și reziduurile de clătire) generate. Auditul de producție eficientă și mai curată a resurselor (RECP) a identificat ineficiențe specifice în cadrul operațiunilor de procesare ale Erpin, ducând la intervenții concentrate pe minimizarea producției de deșeuri biologice și pe reducerea amprentei de apă asociată cu fiecare unitate de produs lactat procesat. Acest caz reflectă aplicarea programului la cooperativele agricole mai mici care operează instalații de procesare a alimentelor.",hy:"«Էրփին» գյուղատնտեսական կոոպերատիվը գործում է կաթնամթերքի վերամշակման գործարան, որը մասնակցել է «EU4Environment Resource Efficient and Cleaner Production» (RECP) ծրագրին՝ գնահատելու ռեսուրսների օգտագործումը իր կաթի վերամշակման գծերում: Կաթնամթերքի վերամշակումը սովորաբար և՛ ջրի, և՛ թափոնների ինտենսիվ է, հաշվի առնելով մաքրման և մշակման համար օգտագործվող ջրի ծավալը և առաջացած կենսաբանական թափոնները (օրինակ՝ շիճուկը և ողողման մնացորդները): Ռեսուրսների արդյունավետ և ավելի մաքուր արտադրություն (RECP) աուդիտը հայտնաբերել է Erpin-ի վերամշակման գործունեության որոշակի անարդյունավետություն, ինչը հանգեցրել է միջամտությունների, որոնք ուղղված են նվազագույնի հասցնելու կենսաբանական թափոնների արտադրությունը և նվազեցնելով ջրի հետքը՝ կապված վերամշակված կաթնամթերքի յուրաքանչյուր միավորի հետ: Այս դեպքը արտացոլում է ծրագրի կիրառումը սննդի վերամշակման օբյեկտներ շահագործող գյուղատնտեսական փոքր կոոպերատիվների նկատմամբ։"},caseLink:"https://www.eu4environment.org/app/uploads/2024/02/Erpin.pdf"}),e({id:"case-034",slug:"rozfrood-llc",companyName:{en:"Rozfrood LLC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Food and Agriculture"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Process efficiency improvements and a shift toward renewable energy reduce the energy intensity of the energy-heavy freezing and cold-storage stages of food processing.",uk:"Підвищення ефективності виробничих процесів і перехід до використання відновлюваної енергії дають змогу зменшити енергоємність заморожування та зберігання продукції в холодильних установках – одних із найбільш енергоємних етапів харчового виробництва.",ro:"Îmbunătățirile eficienței procesului și o trecere către energia regenerabilă reduc intensitatea energetică a etapelor de congelare și depozitare la rece, cu consum mare de energie, ale procesării alimentelor.",hy:"Գործընթացների արդյունավետության բարելավումը և դեպի վերականգնվող էներգիայի անցումը նվազեցնում են սննդամթերքի վերամշակման էներգակիրների սառեցման և սառը պահեստավորման փուլերի էներգիայի ինտենսիվությունը։"},summary:{en:"Rozfrood LLC, a food manufacturer in the Lori region, implemented green solutions and Resource Efficient and Cleaner Production (RECP) recommendations to more efficiently process frozen fruits and vegetables, while transitioning toward renewable energy for freezing operations.",uk:"Rozfrood LLC, виробник продуктів харчування в регіоні Лорі, впровадив екологічні рішення та рекомендації щодо ресурсоефективного та чистого виробництва (RECP) для більш ефективної обробки заморожених фруктів і овочів, одночасно переходячи на відновлювані джерела енергії для операцій заморожування.",ro:"Rozfrood LLC, un producător de alimente din regiunea Lori, a implementat soluții verzi și recomandări de producție eficientă și mai curată a resurselor (RECP) pentru a procesa mai eficient fructele și legumele congelate, în timp ce trece la energie regenerabilă pentru operațiunile de congelare.",hy:"Լոռու մարզում սննդամթերք արտադրող «Ռոզֆրուդ» ՍՊԸ-ն իրականացրել է կանաչ լուծումներ և ռեսուրսների արդյունավետ և մաքուր արտադրություն (RECP) առաջարկություններ՝ սառեցված մրգերի և բանջարեղենի ավելի արդյունավետ մշակման համար՝ միաժամանակ անցնելով վերականգնվող էներգիայի՝ սառեցման աշխատանքների համար։"},description:{en:"Rozfrood LLC is a food manufacturer based in Armenia's Lori region, specialising in the processing of frozen fruits and vegetables. Freezing and cold storage are among the most energy-intensive stages of food processing, making them a priority target for resource-efficiency interventions. Through the EU4Environment Resource Efficient and Cleaner Production (RECP) programme, Rozfrood implemented green solutions and process recommendations to improve the efficiency of its freezing operations, while also taking steps to facilitate a transition toward renewable energy sources to power these processes. This case illustrates how Resource Efficient and Cleaner Production (RECP) interventions can support decarbonisation of particularly energy-intensive stages within the food supply chain.",uk:"Rozfrood LLC – виробник харчової продукції у регіоні Лорі (Вірменія), що спеціалізується на переробленні заморожених фруктів і овочів. Заморожування та зберігання продукції в холодильних установках – одні з найбільш енергоємних етапів харчового виробництва, тому вони стали пріоритетним напрямом для заходів із підвищення ресурсоефективності. У межах програми EU4Environment (компоненту «Ресурсоефективне та чисте виробництво») Rozfrood упровадив екологічні рішення та рекомендації щодо вдосконалення виробничих процесів, щоб підвищити ефективність заморожування, а також вжив заходів для переходу до використання відновлюваних джерел енергії для цих процесів. Цей приклад демонструє, як заходи з РЕЧВ можуть сприяти декарбонізації особливо енергоємних етапів у ланцюзі постачання харчових продуктів.",ro:"Rozfrood LLC este un producător de alimente cu sediul în regiunea Lori din Armenia, specializat în procesarea fructelor și legumelor congelate. Înghețarea și depozitarea la rece sunt printre etapele cele mai consumatoare de energie ale procesării alimentelor, ceea ce le face o țintă prioritară pentru intervențiile de utilizare eficientă a resurselor. Prin programul EU4Environment Resource Efficient and Cleaner Production (RECP), Rozfrood a implementat soluții ecologice și recomandări de proces pentru a îmbunătăți eficiența operațiunilor sale de congelare, luând în același timp măsuri pentru a facilita tranziția către surse regenerabile de energie pentru a alimenta aceste procese. Acest caz ilustrează modul în care intervențiile de producție eficientă și mai curată din punct de vedere al resurselor (RECP) pot sprijini decarbonizarea etapelor deosebit de mari consumatoare de energie din cadrul lanțului de aprovizionare cu alimente.",hy:"«Ռոզֆրուդ» ՍՊԸ-ն Հայաստանի Լոռու մարզում գործող սննդամթերք արտադրող ընկերություն է, որը մասնագիտացած է սառեցված մրգերի և բանջարեղենի վերամշակման մեջ: Սառեցումը և սառը պահեստավորումը սննդամթերքի վերամշակման ամենաէներգետիկ փուլերից են՝ դրանք դարձնելով ռեսուրսների արդյունավետ միջամտությունների առաջնահերթ թիրախ: EU4Environment Resource Efficient and Cleaner Production (RECP) ծրագրի միջոցով Rozfrood-ն իրականացրել է կանաչ լուծումներ և գործընթացների առաջարկություններ՝ բարելավելու իր սառեցման գործողությունների արդյունավետությունը, միաժամանակ քայլեր ձեռնարկելով հեշտացնելու անցումը դեպի վերականգնվող էներգիայի աղբյուրներ՝ այդ գործընթացները սնուցելու համար: Այս դեպքը ցույց է տալիս, թե ինչպես ռեսուրսների արդյունավետ և ավելի մաքուր արտադրություն (RECP) միջամտությունները կարող են աջակցել սննդամթերքի մատակարարման շղթայում հատկապես էներգատար փուլերի ածխաթթվայնացմանը։"},caseLink:"https://www.eu4environment.org/app/uploads/2024/02/Rozfrood-LLC.pdf"}),e({id:"case-035",slug:"magnon-ojsc",companyName:{en:"Magnon OJSC",uk:"",ro:"",hy:""},country:"Armenia",sector:["Manufacturing"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Preventive environmental strategies applied through the Resource Efficient and Cleaner Production (RECP) demonstration reduce raw material waste and improve overall process efficiency within the production cycle.",uk:"Превентивні екологічні стратегії, застосовані в межах демонстраційного проєкту з ресурсоефективного та чистого виробництва, дають змогу скоротити втрати сировини та підвищити загальну ефективність виробничих процесів.",ro:"Strategiile de mediu preventive aplicate prin demonstrația de producție eficientă și mai curată a resurselor (RECP) reduc risipa de materii prime și îmbunătățesc eficiența globală a procesului în cadrul ciclului de producție.",hy:"Կանխարգելիչ բնապահպանական ռազմավարությունները, որոնք կիրառվել են ռեսուրսների արդյունավետ և ավելի մաքուր արտադրություն (RECP) ցուցադրման միջոցով, նվազեցնում են հումքի թափոնները և բարելավում գործընթացի ընդհանուր արդյունավետությունը արտադրության ցիկլի ընթացքում։"},summary:{en:"Magnon OJSC, an Armenian manufacturing SME, served as a Resource Efficient and Cleaner Production (RECP) demonstration company, undergoing technical assessments to apply preventive environmental strategies aimed at decreasing raw material waste and increasing process efficiency.",uk:"ВАТ «Магнон», вірменське виробниче МСП, слугувало демонстраційною компанією ресурсоефективного та чистого виробництва (RECP), проходячи технічну оцінку для застосування превентивних екологічних стратегій, спрямованих на зменшення відходів сировини та підвищення ефективності процесу.",ro:"Magnon OJSC, un IMM de producție armean, a servit ca o companie demonstrativă de producție eficientă și mai curată a resurselor (RECP), fiind supusă unor evaluări tehnice pentru a aplica strategii preventive de mediu care vizează scăderea deșeurilor de materii prime și creșterea eficienței procesului.",hy:"Հայկական արտադրական ՓՄՁ Magnon ԲԲԸ-ն ծառայել է որպես ռեսուրսների արդյունավետ և ավելի մաքուր արտադրություն (RECP) ցուցադրական ընկերություն՝ անցնելով տեխնիկական գնահատումների՝ կիրառելով կանխարգելիչ բնապահպանական ռազմավարություններ՝ ուղղված հումքի թափոնների նվազեցմանը և գործընթացի արդյունավետության բարձրացմանը։"},description:{en:"Magnon OJSC served as a demonstration company within the EU4Environment Resource Efficient and Cleaner Production (RECP) programme, meaning it underwent a more detailed technical assessment intended to showcase resource-efficiency methodologies for other Armenian manufacturing small-medium enterprises (SMEs) to replicate. The assessment applied preventive environmental strategies, an approach that focuses on avoiding waste and inefficiency at the source within the production process, rather than managing waste after it is generated. The resulting interventions aimed to decrease raw material waste and increase overall process efficiency across Magnon's production cycle, with the company's experience intended to serve as a reference case for the broader Resource Efficient and Cleaner Production (RECP) programme in Armenia.",uk:"Magnon OJSC стало демонстраційним підприємством у межах програми EU4Environment (компоненту «Ресурсоефективне та чисте виробництво»), що передбачало проведення детальнішого технічного оцінювання для демонстрації методів підвищення ресурсоефективності, які можуть застосовувати інші вірменські МСП. Оцінювання передбачало застосування превентивних екологічних стратегій, спрямованих на запобігання утворенню відходів і неефективному використанню ресурсів безпосередньо у виробничому процесі, а не на поводження з відходами після їх утворення. Визначені за результатами оцінювання заходи були спрямовані на скорочення втрат сировини та підвищення загальної ефективності виробничих процесів Magnon. Досвід компанії має слугувати прикладом для ширшого застосування підходів ресурсоефективного та чистого виробництва у Вірменії.",ro:"Magnon OJSC a servit ca o companie demonstrativă în cadrul programului EU4Environment Resource Efficient and Cleaner Production (RECP), ceea ce înseamnă că a suferit o evaluare tehnică mai detaliată menită să prezinte metodologii de eficiență a resurselor pentru a le reproduce alte întreprinderi mici-medii (IMM-uri) armene de producție. Evaluarea a aplicat strategii preventive de mediu, o abordare care se concentrează pe evitarea risipei și a ineficienței la sursă în cadrul procesului de producție, mai degrabă decât pe gestionarea deșeurilor după ce acestea sunt generate. Intervențiile rezultate au avut ca scop scăderea deșeurilor de materii prime și creșterea eficienței generale a procesului pe parcursul ciclului de producție al Magnon, experiența companiei menită să servească drept caz de referință pentru programul mai larg de producție mai curată și eficientă a resurselor (RECP) din Armenia.",hy:"Magnon ԲԲԸ-ն ծառայում էր որպես ցուցադրական ընկերություն EU4Environment Resource Efficient and Cleaner Production (RECP) ծրագրի շրջանակներում, ինչը նշանակում է, որ այն ենթարկվել է ավելի մանրամասն տեխնիկական գնահատման, որը նպատակաուղղված է ցուցադրելու ռեսուրսների արդյունավետության մեթոդոլոգիաները հայկական այլ արտադրական փոքր և միջին ձեռնարկությունների (ՓՄՁ) համար՝ կրկնօրինակելու համար: Գնահատումը կիրառեց կանխարգելիչ բնապահպանական ռազմավարություններ, մոտեցում, որը կենտրոնանում է արտադրության գործընթացում թափոններից և անարդյունավետությունից խուսափելու վրա, այլ ոչ թե թափոնների կառավարումից հետո: Արդյունքում ստացված միջամտությունները նպատակ ունեին նվազեցնել հումքի թափոնները և բարձրացնել գործընթացի ընդհանուր արդյունավետությունը Magnon-ի արտադրական ցիկլում, ընդ որում ընկերության փորձը նպատակաուղղված է ծառայել որպես Հայաստանում ավելի արդյունավետ ռեսուրսների արդյունավետ և մաքուր արտադրություն (RECP) ծրագրի համար։"},caseLink:"https://www.eu4environment.org/app/uploads/2024/02/Magnon.pdf"}),e({id:"case-036",slug:"ecosoft",companyName:{en:"Ecosoft",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Waste Management"],rStrategies:["Reduce (R2)","Repair (R4)"],rStrategyDescription:{en:"The rental/subscription service model reduces the total volume of equipment manufactured and sold (Reduce); ongoing maintenance, cartridge replacement, and component repair extend the operational life of each unit (Repair).",uk:"Модель оренди та передплати дає змогу скоротити загальний обсяг обладнання, яке потрібно виробити та продати (Скорочення), а регулярне технічне обслуговування, заміна картриджів і ремонт компонентів – продовжити термін експлуатації кожної системи (Ремонт).",ro:"Modelul de servicii de închiriere/abonament reduce volumul total de echipamente fabricate și vândute (Reducere); întreținerea continuă, înlocuirea cartușului și repararea componentelor prelungesc durata de viață operațională a fiecărei unități (reparație).",hy:"Վարձակալության/բաժանորդագրման ծառայության մոդելը նվազեցնում է արտադրված և վաճառվող սարքավորումների ընդհանուր ծավալը (Նվազեցնել); ընթացիկ սպասարկումը, փամփուշտների փոխարինումը և բաղադրիչների վերանորոգումը երկարացնում են յուրաքանչյուր միավորի գործառնական կյանքը (Վերանորոգում)։"},summary:{en:"Ecosoft offers water purification systems through a rental and service-based model, reducing single-use plastic and extending equipment lifespan through repair, refurbishment and upgrades.",uk:"Ecosoft пропонує системи очищення води за моделлю оренди та обслуговування, зменшуючи використання одноразового пластику та подовжуючи термін служби обладнання завдяки ремонту, відновленню та модернізації.",ro:"Ecosoft oferă sisteme de purificare a apei printr-un model bazat pe închiriere și servicii, reducând plasticul de unică folosință și extinzând durata de viață a echipamentului prin reparații, recondiționări și upgrade.",hy:"Ecosoft-ն առաջարկում է ջրի մաքրման համակարգեր վարձակալության և սպասարկման վրա հիմնված մոդելի միջոցով՝ նվազեցնելով մեկանգամյա օգտագործման պլաստիկը և երկարացնելով սարքավորումների կյանքը վերանորոգման, վերանորոգման և արդիականացման միջոցով։"},description:{en:"Ecosoft is a leading Ukrainian manufacturer of water purification systems operating in the market for over 30 years. The company produces household filters, reverse osmosis systems, ultraviolet (UV) disinfection units, and industrial-scale installations for business, healthcare, food industry, and hospitality sectors. || In addition to selling equipment, the company offers water purification systems in a rental or subscription model with full service support. Clients receive equipment selection, installation, regular maintenance, cartridge replacement, and upgrade options without significant upfront costs. || The company applies approaches related to efficient resource use, repair, refurbishment, and equipment upgrading. It ensures long-term system operation, returns individual components into the service cycle, and enables plastic, metal, and electronic parts to be repaired or sent for recycling. || The environmental benefit lies in reducing the use of single-use plastic bottles, decreasing waste generation, and extending the service life of equipment. Regular maintenance helps avoid premature replacement of water purification systems. || The economic benefit for customers is the absence of high capital investment in equipment, predictable monthly costs, and reduced maintenance expenses.",uk:"Ecosoft – провідний український виробник систем очищення води, який працює на ринку понад 30 років. Компанія виробляє побутові фільтри, системи зворотного осмосу, установки ультрафіолетового знезараження та промислові системи для підприємств, закладів охорони здоров’я, харчової промисловості та сфери готельного й ресторанного бізнесу. || Окрім продажу обладнання, компанія пропонує системи очищення води за моделлю оренди або передплати з повним сервісним обслуговуванням. Клієнти отримують підбір обладнання, установлення, регулярне технічне обслуговування, заміну картриджів і можливість модернізації без значних початкових витрат. || Компанія застосовує підходи, пов’язані з ефективним використанням ресурсів, ремонтом, відновленням та модернізацією обладнання. Вона забезпечує тривалу експлуатацію систем, повертає окремі компоненти у сервісний цикл і дає змогу ремонтувати пластикові, металеві та електронні компоненти або передавати їх на перероблення. || Екологічний ефект полягає у скороченні використання одноразових пластикових пляшок, зменшенні утворення відходів і продовженні терміну експлуатації обладнання. Регулярне технічне обслуговування допомагає уникати передчасної заміни систем очищення води. || Економічна вигода для клієнтів – відсутність значних капітальних витрат на придбання обладнання, передбачувані щомісячні витрати та зменшення витрат на технічне обслуговування.",ro:"Ecosoft este un producător ucrainean lider de sisteme de purificare a apei care operează pe piață de peste 30 de ani. Compania produce filtre de uz casnic, sisteme de osmoză inversă, unități de dezinfecție cu ultraviolete (UV) și instalații la scară industrială pentru sectoarele de afaceri, sănătate, industria alimentară și ospitalitate. || Pe lângă vânzarea de echipamente, compania oferă sisteme de purificare a apei într-un model de închiriere sau abonament cu suport complet de servicii. Clienții primesc opțiuni de selecție a echipamentelor, instalare, întreținere regulată, înlocuire a cartușelor și opțiuni de upgrade fără costuri inițiale semnificative. || Compania aplică abordări legate de utilizarea eficientă a resurselor, reparații, recondiționări și modernizarea echipamentelor. Acesta asigură funcționarea pe termen lung a sistemului, returnează componentele individuale în ciclul de service și permite repararea sau trimiterea către reciclare a pieselor din plastic, metal și electronice. || Beneficiul de mediu constă în reducerea utilizării sticlelor de plastic de unică folosință, scăderea generării de deșeuri și prelungirea duratei de viață a echipamentelor. Întreținerea regulată ajută la evitarea înlocuirii premature a sistemelor de purificare a apei. || Beneficiul economic pentru clienți este absența investițiilor mari de capital în echipamente, costuri lunare previzibile și cheltuieli de întreținere reduse.",hy:"Ecosoft-ը ջրի մաքրման համակարգերի առաջատար ուկրաինական արտադրողն է, որը շուկայում գործում է ավելի քան 30 տարի: Ընկերությունն արտադրում է կենցաղային զտիչներ, հակադարձ օսմոզ համակարգեր, ուլտրամանուշակագույն (ուլտրամանուշակագույն) ախտահանման միավորներ և արդյունաբերական մասշտաբի կայանքներ բիզնեսի, առողջապահության, սննդի արդյունաբերության և հյուրընկալության ոլորտների համար։ || Սարքավորումների վաճառքից բացի, ընկերությունը առաջարկում է ջրի մաքրման համակարգեր վարձակալության կամ բաժանորդագրության մոդելով՝ սպասարկման ամբողջական աջակցությամբ: Հաճախորդները ստանում են սարքավորումների ընտրություն, տեղադրում, կանոնավոր սպասարկում, փամփուշտների փոխարինում և արդիականացում՝ առանց զգալի նախնական ծախսերի։ || Ընկերությունը կիրառում է մոտեցումներ՝ կապված ռեսուրսների արդյունավետ օգտագործման, վերանորոգման, վերանորոգման և սարքավորումների արդիականացման հետ: Այն ապահովում է համակարգի երկարաժամկետ աշխատանքը, առանձին բաղադրիչները վերադարձնում է սպասարկման ցիկլ և հնարավորություն է տալիս վերանորոգել պլաստիկ, մետաղական և էլեկտրոնային մասերը կամ ուղարկել վերամշակման։ || Բնապահպանական օգուտը կայանում է նրանում, որ մեկանգամյա օգտագործման պլաստիկ շշերի օգտագործումը նվազեցնելը, թափոնների արտադրությունը նվազեցնելը և սարքավորումների ծառայության ժամկետի երկարացումը: Կանոնավոր սպասարկումն օգնում է խուսափել ջրի մաքրման համակարգերի վաղաժամ փոխարինումից։ || Հաճախորդների համար տնտեսական օգուտը սարքավորումների մեջ մեծ կապիտալ ներդրումների բացակայությունն է, կանխատեսելի ամսական ծախսերը և սպասարկման ծախսերի կրճատումը։"},caseLink:"https://ecosoft.ua/ua/",image:"/images/cases/ukraine/ecosoft.jpg",imageAlt:{en:"Ecosoft case image",uk:"Зображення чохла Ecosoft",ro:"Imaginea carcasei Ecosoft",hy:"Ecosoft-ի պատյան պատկեր"}}),e({id:"case-037",slug:"optima-service",companyName:{en:"Optima Service",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Services"],rStrategies:["Reduce (R2)","Refurbish (R5)"],rStrategyDescription:{en:"The service-based access model reduces the total volume of new IT hardware purchased by clients (Reduce); centralised lifecycle management enables equipment to be refurbished and returned to productive use after upgrades (Refurbish).",uk:"Модель доступу до обладнання як послуги дає змогу клієнтам скоротити загальний обсяг нового ІТ-обладнання, яке вони купують (Скорочення), а централізоване управління життєвим циклом обладнання – відновлювати його та повертати до продуктивного використання після модернізації (Відновлення).",ro:"Modelul de acces bazat pe servicii reduce volumul total de hardware IT nou achiziționat de clienți (Reducere); gestionarea centralizată a ciclului de viață permite echipamentelor să fie recondiționate și readuse la utilizare productivă după upgrade (renovare).",hy:"Ծառայությունների վրա հիմնված մուտքի մոդելը նվազեցնում է հաճախորդների կողմից գնված նոր ՏՏ սարքավորումների ընդհանուր ծավալը (Նվազեցնել); Կյանքի ցիկլի կենտրոնացված կառավարումը հնարավորություն է տալիս սարքավորումը վերանորոգել և արդիականացումից հետո վերադարձնել արդյունավետ օգտագործման (Refurbish)։"},summary:{en:"Optima Service provides IT equipment through a Workplace as a Service model, supplying fully managed hardware, software and support that extends equipment lifespan through centralised maintenance and refurbishment.",uk:"Optima Service надає ІТ-обладнання за моделлю «Робоче місце як послуга», постачаючи повністю кероване апаратне забезпечення, програмні засоби та технічну підтримку, що подовжує термін служби техніки завдяки централізованому обслуговуванню та відновленню.",ro:"Optima Service furnizează echipamente IT printr-un model Workplace as a Service, furnizând hardware, software și suport complet gestionate care prelungesc durata de viață a echipamentelor prin întreținere și renovare centralizate.",hy:"Optima Service-ը տրամադրում է ՏՏ սարքավորումներ Workplace as a Service մոդելի միջոցով՝ տրամադրելով ամբողջությամբ կառավարվող սարքաշար, ծրագրակազմ և աջակցություն, որը երկարացնում է սարքավորումների կյանքը կենտրոնացված սպասարկման և վերանորոգման միջոցով։"},description:{en:"Optima Service is a Ukrainian company providing IT infrastructure services and digital solutions for businesses. One of its core business areas is the Workplace as a Service (WaaS) model, through which the company supplies clients with fully equipped workplaces, including computer hardware, software, networking equipment, and technical support. || The company operates under a service-based model, enabling clients to access fully functional workplaces without the need to purchase, maintain, or manage the equipment themselves. Optima Service provides installation, updates, technical support, repair, and replacement of equipment throughout its entire lifecycle. || The company applies resource-efficient approaches focused on equipment maintenance, upgrading, refurbishment, and reuse. Centralized management of IT assets helps extend the service life of equipment, improve utilization rates, and return individual components to productive use following upgrades or refurbishment. || The environmental benefits of this model include a reduction in electronic waste generation, decreased demand for the production of new equipment, and the extension of product lifecycles. Timely maintenance and modernization help prevent the premature replacement of devices. || The economic benefits for clients include the elimination of significant upfront capital expenditures for IT equipment, predictable service costs, and reduced expenses related to technical support. For the company, the service-based model ensures stable long-term demand and more efficient management of IT assets.",uk:"Optima Service – українська компанія, що надає послуги з ІТ-інфраструктури та цифрові рішення для бізнесу. Один із основних напрямів її діяльності – модель «Робоче місце як послуга», за якою компанія забезпечує клієнтів повністю обладнаними робочими місцями, зокрема комп’ютерною технікою, програмним забезпеченням, мережевим обладнанням і технічною підтримкою. || Компанія працює за сервісною моделлю, завдяки якій клієнти отримують доступ до повністю функціональних робочих місць без необхідності самостійно купувати, обслуговувати та управляти обладнанням. Optima Service забезпечує встановлення, оновлення, технічну підтримку, ремонт і заміну обладнання протягом усього його життєвого циклу. || Компанія застосовує ресурсоефективні підходи, зосереджені на технічному обслуговуванні, модернізації, відновленні та повторному використанні обладнання. Централізоване управління ІТ-активами дає змогу продовжити термін експлуатації обладнання, підвищити ефективність його використання та повертати окремі компоненти до продуктивного використання після модернізації або відновлення. || Екологічні переваги цієї моделі – зменшення утворення електронних відходів, скорочення потреби у виробництві нового обладнання та продовження терміну експлуатації продукції. Своєчасне технічне обслуговування та модернізація допомагають запобігти передчасній заміні пристроїв. || Економічні переваги для клієнтів – відсутність значних початкових капітальних витрат на ІТ-обладнання, передбачувані витрати на послуги та зменшення витрат на технічну підтримку. Для компанії сервісна модель забезпечує стабільний довгостроковий попит і ефективніше управління ІТ-активами.",ro:"Optima Service este o companie ucraineană care furnizează servicii de infrastructură IT și soluții digitale pentru afaceri. Unul dintre domeniile sale principale de afaceri este modelul Workplace as a Service (WaaS), prin care compania furnizează clienților locuri de muncă complet echipate, inclusiv hardware de computer, software, echipamente de rețea și suport tehnic. || Compania operează sub un model bazat pe servicii, permițând clienților să acceseze locuri de muncă complet funcționale fără a fi nevoie să achiziționeze, să întrețină sau să gestioneze ei înșiși echipamentele. Optima Service oferă instalarea, actualizările, asistența tehnică, repararea și înlocuirea echipamentelor pe întregul său ciclu de viață. || Compania aplică abordări eficiente din punct de vedere al resurselor axate pe întreținerea, modernizarea, renovarea și reutilizarea echipamentelor. Gestionarea centralizată a activelor IT ajută la prelungirea duratei de viață a echipamentelor, la îmbunătățirea ratelor de utilizare și la readucerea componentelor individuale la o utilizare productivă după upgrade-uri sau recondiționări. || Beneficiile de mediu ale acestui model includ o reducere a generării de deșeuri electronice, scăderea cererii pentru producția de echipamente noi și extinderea ciclurilor de viață ale produselor. Întreținerea și modernizarea în timp util ajută la prevenirea înlocuirii premature a dispozitivelor. || Beneficiile economice pentru clienți includ eliminarea cheltuielilor de capital semnificative în avans pentru echipamentele IT, costurile previzibile ale serviciilor și cheltuielile reduse legate de suportul tehnic. Pentru companie, modelul bazat pe servicii asigură o cerere stabilă pe termen lung și un management mai eficient al activelor IT.",hy:"Optima Service-ը ուկրաինական ընկերություն է, որը տրամադրում է ՏՏ ենթակառուցվածքի ծառայություններ և թվային լուծումներ բիզնեսի համար: Նրա հիմնական բիզնես ոլորտներից մեկը Workplace as a Service (WaaS) մոդելն է, որի միջոցով ընկերությունը հաճախորդներին տրամադրում է լիովին հագեցած աշխատատեղեր, ներառյալ համակարգչային տեխնիկա, ծրագրային ապահովում, ցանցային սարքավորումներ և տեխնիկական աջակցություն։ || Ընկերությունը գործում է ծառայությունների վրա հիմնված մոդելի ներքո՝ հնարավորություն տալով հաճախորդներին մուտք գործել լիարժեք գործունակ աշխատատեղեր՝ առանց սարքավորումները ձեռք բերելու, պահպանելու կամ կառավարելու անհրաժեշտության: Optima Service-ն ապահովում է սարքավորումների տեղադրում, թարմացումներ, տեխնիկական աջակցություն, վերանորոգում և փոխարինում իր ողջ կյանքի ընթացքում։ || Ընկերությունը կիրառում է ռեսուրսների համար արդյունավետ մոտեցումներ՝ ուղղված սարքավորումների պահպանման, արդիականացման, վերանորոգման և վերօգտագործման վրա: ՏՏ ակտիվների կենտրոնացված կառավարումն օգնում է երկարացնել սարքավորումների ծառայության ժամկետը, բարելավել օգտագործման տեմպերը և արդիականացումներից կամ վերանորոգումից հետո առանձին բաղադրիչները վերադարձնել արդյունավետ օգտագործման։ || Այս մոդելի բնապահպանական առավելությունները ներառում են էլեկտրոնային թափոնների արտադրության կրճատում, նոր սարքավորումների արտադրության պահանջարկի նվազում և արտադրանքի կյանքի ցիկլի երկարացում: Ժամանակին սպասարկումն ու արդիականացումը օգնում են կանխել սարքերի վաղաժամ փոխարինումը։ || Հաճախորդների համար տնտեսական օգուտները ներառում են ՏՏ սարքավորումների համար զգալի նախնական կապիտալ ծախսերի վերացումը, սպասարկման կանխատեսելի ծախսերը և տեխնիկական աջակցության հետ կապված ծախսերի կրճատումը: Ընկերության համար ծառայության վրա հիմնված մոդելը ապահովում է կայուն երկարաժամկետ պահանջարկ և ՏՏ ակտիվների ավելի արդյունավետ կառավարում։"},caseLink:"https://optima-service.ua/uk",image:"/images/cases/ukraine/optima-service.jpg",imageAlt:{en:"Optima Service case image",uk:"Зображення корпусу Оптима Сервіс",ro:"Imaginea cazului Optima Service",hy:"Optima Service գործի պատկեր"}}),e({id:"case-038",slug:"chystota-cleaning-company",companyName:{en:"Chystota (Cleaning Company)",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Services"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Clients pay for a cleaning outcome rather than purchasing equipment and supplies themselves; precise dosing, reusable tools, and bulk purchasing of agents reduce overall material, water, and packaging consumption.",uk:"Клієнти оплачують результат – чистоту та порядок – замість самостійного придбання обладнання й засобів для прибирання; точне дозування, багаторазові інструменти та закупівля засобів великими партіями дають змогу скоротити загальне споживання матеріалів, води та паковання.",ro:"Clienții plătesc pentru rezultatul curățeniei, mai degrabă decât să achiziționeze ei înșiși echipamente și consumabile; dozarea precisă, instrumentele reutilizabile și achiziția în vrac de agenți reduc consumul total de material, apă și ambalaje.",hy:"Հաճախորդները վճարում են մաքրման արդյունքի համար, այլ ոչ թե իրենք գնելու սարքավորումներ և պարագաներ. ճշգրիտ չափաբաժինները, բազմակի օգտագործման գործիքները և նյութերի զանգվածային գնումները նվազեցնում են նյութի, ջրի և փաթեթավորման ընդհանուր սպառումը։"},summary:{en:"Chystota is a professional cleaning service provider whose service-based model reduces overall consumption of cleaning equipment, chemicals and packaging compared to individual ownership.",uk:"«Чистота» – постачальник професійних клінінгових послуг, чия сервісна модель зменшує загальне споживання прибирального обладнання, хімічних засобів та паковання порівняно з їх придбанням в індивідуальну власність.",ro:"Chystota este un furnizor profesionist de servicii de curățenie al cărui model bazat pe servicii reduce consumul total de echipamente de curățare, substanțe chimice și ambalaje în comparație cu proprietatea individuală.",hy:"Chystota-ն պրոֆեսիոնալ մաքրման ծառայություններ մատուցող է, որի ծառայությունների վրա հիմնված մոդելը նվազեցնում է մաքրման սարքավորումների, քիմիական նյութերի և փաթեթավորման ընդհանուր սպառումը անհատական սեփականության համեմատ։"},description:{en:"The cleaning company Chystota is a professional service provider with more than 15 years of experience, offering services for residential and commercial premises. The company performs regular and deep cleaning, window washing, post-renovation cleaning, upholstery cleaning, and other services. It uses its own equipment, certified professional cleaning agents, and trained staff. || The company operates under a service-based model, where the client pays for the outcome – cleanliness and order – rather than purchasing equipment, cleaning supplies, or additional tools. This approach helps reduce overall consumption of goods and resources. || The company applies the principle of efficient resource use. Thanks to staff expertise, cleaning agents are precisely dosed, efficient equipment and reusable tools are used, which reduces consumption of materials, water, and packaging. Purchasing cleaning agents in bulk also reduces single-use packaging waste. || The environmental benefit lies in reduced use of household chemicals, lower packaging waste generation, and decreased risk of water pollution. In addition, professional care for furniture, surfaces, and carpets extends their lifespan and prevents premature replacement. || The economic benefit for clients is the absence of costs for purchasing specialised equipment, professional cleaning products, and staff training. For the company, the service model ensures stable demand and scalability of services.",uk:"Клінінгова компанія Chystota – професійний надавач послуг із понад 15-річним досвідом, що обслуговує житлові та комерційні приміщення. Компанія виконує регулярне та генеральне прибирання, миття вікон, прибирання після ремонту, чищення м’яких меблів та інші роботи. Вона використовує власне обладнання, сертифіковані професійні засоби для прибирання та працює з підготовленим персоналом. || Компанія працює за сервісною моделлю, за якої клієнт платить за результат – чистоту та порядок – замість придбання обладнання, засобів для прибирання та додаткових інструментів. Такий підхід допомагає скоротити загальне споживання товарів і ресурсів. || Компанія застосовує принцип ефективного використання ресурсів. Завдяки професійним навичкам працівників засоби для прибирання дозуються точно, використовуються ефективне обладнання та багаторазові інструменти, що дає змогу скоротити споживання матеріалів і води та зменшити кількість паковання. Закупівля засобів для прибирання великими партіями також дає змогу скоротити утворення відходів одноразового паковання. || Екологічні переваги – скорочення використання побутової хімії, зменшення утворення відходів паковання та зниження ризику забруднення води. Крім того, професійний догляд за меблями, поверхнями та килимами продовжує термін їхньої експлуатації та запобігає передчасній заміні. || Економічні переваги для клієнтів – відсутність витрат на придбання спеціалізованого обладнання, професійних засобів для прибирання та навчання персоналу. Для компанії сервісна модель забезпечує стабільний попит і можливість масштабування послуг.",ro:"Firma de curatenie Chystota este un furnizor de servicii profesionist cu peste 15 ani de experienta, oferind servicii pentru spatii rezidentiale si comerciale. Compania efectuează curățare regulată și profundă, spălare geamuri, curățare post-renovare, curățare tapițerie și alte servicii. Folosește propriul echipament, agenți de curățare profesioniști certificați și personal instruit. || Compania funcționează conform unui model bazat pe servicii, în care clientul plătește pentru rezultat – curățenia și ordinea – mai degrabă decât să achiziționeze echipamente, materiale de curățenie sau unelte suplimentare. Această abordare ajută la reducerea consumului general de bunuri și resurse. || Compania aplică principiul utilizării eficiente a resurselor. Datorită expertizei personalului, agenții de curățare sunt dozați cu precizie, sunt utilizate echipamente eficiente și unelte reutilizabile, ceea ce reduce consumul de materiale, apă și ambalaje. Achiziționarea agenților de curățare în vrac reduce, de asemenea, deșeurile de ambalaje de unică folosință. || Beneficiul pentru mediu constă în utilizarea redusă a substanțelor chimice de uz casnic, reducerea generării de deșeuri de ambalaje și reducerea riscului de poluare a apei. În plus, îngrijirea profesională pentru mobilier, suprafețe și covoare prelungește durata de viață a acestora și previne înlocuirea prematură. || Beneficiul economic pentru clienți este absența costurilor pentru achiziționarea de echipamente specializate, produse profesionale de curățare și pregătirea personalului. Pentru companie, modelul de servicii asigură cerere stabilă și scalabilitate a serviciilor.",hy:"Մաքրող ընկերությունը Chystota-ն պրոֆեսիոնալ ծառայություններ մատուցող է ավելի քան 15 տարվա փորձով, որն առաջարկում է ծառայություններ բնակելի և կոմերցիոն տարածքների համար: Ընկերությունն իրականացնում է կանոնավոր և խորը մաքրում, պատուհանների լվացում, հետվերանորոգման մաքրում, պաստառագործության մաքրում և այլ ծառայություններ։ Այն օգտագործում է իր սեփական սարքավորումները, հավաստագրված պրոֆեսիոնալ մաքրող միջոցները և պատրաստված անձնակազմը։ || Ընկերությունը գործում է ծառայության վրա հիմնված մոդելի ներքո, որտեղ հաճախորդը վճարում է արդյունքի համար՝ մաքրություն և կարգուկանոն, այլ ոչ թե գնելու սարքավորումներ, մաքրման պարագաներ կամ լրացուցիչ գործիքներ: Այս մոտեցումն օգնում է նվազեցնել ապրանքների և ռեսուրսների ընդհանուր սպառումը։ || Ընկերությունը կիրառում է ռեսուրսների արդյունավետ օգտագործման սկզբունքը։ Անձնակազմի փորձաքննության շնորհիվ մաքրող միջոցները ճշգրիտ չափվում են, օգտագործվում են արդյունավետ սարքավորումներ և բազմակի օգտագործման գործիքներ, ինչը նվազեցնում է նյութերի, ջրի և փաթեթավորման սպառումը: Մաքրող միջոցների մեծաքանակ գնումը նաև նվազեցնում է մեկանգամյա օգտագործման փաթեթավորման թափոնները։ || Բնապահպանական օգուտը կայանում է նրանում, որ կենցաղային քիմիկատների օգտագործումը նվազում է, փաթեթավորման թափոնների ավելի քիչ արտադրություն և ջրի աղտոտման ռիսկի նվազում: Բացի այդ, կահույքի, մակերեսների և գորգերի մասնագիտական խնամքը երկարացնում է դրանց կյանքի տևողությունը և կանխում է վաղաժամ փոխարինումը։ || Հաճախորդների համար տնտեսական օգուտը մասնագիտացված սարքավորումների, պրոֆեսիոնալ մաքրման միջոցների և անձնակազմի վերապատրաստման համար ծախսերի բացակայությունն է: Ընկերության համար սպասարկման մոդելը ապահովում է ծառայությունների կայուն պահանջարկ և մասշտաբայնություն։"},caseLink:"https://chystota.ua",image:"/images/cases/ukraine/chystota-cleaning-company.jpg",imageAlt:{en:"Chystota (Cleaning Company) case image",uk:"Зображення кейсу «Чистота» (Клінінгова компанія).",ro:"Imaginea cazului Chystota (Compania de curățenie).",hy:"Chystota (Cleaning Company) գործի պատկեր"}}),e({id:"case-039",slug:"drive-shina",companyName:{en:"DRIVE SHINA",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Automotive"],rStrategies:["Repair (R4)"],rStrategyDescription:{en:"Puncture, cut and deformation repairs, tread restoration, and retreading restore tyre functionality and return tyres to operational use rather than requiring premature replacement.",uk:"Ремонт проколів, порізів і деформацій, відновлення протектора та відновлення шин повертають шинам функціональність і дають змогу повторно використовувати їх за призначенням замість передчасної заміни.",ro:"Reparațiile prin perforare, tăiere și deformare, refacerea benzii de rulare și reșaparea restaurează funcționalitatea anvelopelor și readuc anvelopele la uz operațional, în loc să necesite înlocuirea prematură.",hy:"Ծակումը, կտրումը և դեֆորմացիան վերանորոգումը, քայլքի վերականգնումը և վերաթողարկումը վերականգնում են անվադողերի գործունակությունը և վերադարձնում անվադողերը գործառնական օգտագործման, քան վաղաժամ փոխարինում պահանջելը։"},summary:{en:"DRIVE SHINA repairs, refurbishes and retreads tyres for passenger and commercial vehicles, extending tyre service life and reducing landfill volumes and energy-intensive new tyre production.",uk:"DRIVE SHINA ремонтує, модернізує та відновлює протектор шин для легкових і комерційних автомобілів, продовжуючи термін їхньої експлуатації та зменшуючи обсяги шин, що потрапляють на полігони, а також потребу в енергоємному виробництві нових шин.",ro:"DRIVE SHINA repară, recondiționează și reșapează anvelopele pentru vehicule de pasageri și comerciale, prelungind durata de viață a anvelopelor și reducând volumele depozitelor de gunoi și producția de anvelope noi consumatoare de energie.",hy:"DRIVE SHINA-ն վերանորոգում, վերանորոգում և վերամշակում է մարդատար և առևտրային մեքենաների անվադողերը՝ երկարացնելով անվադողերի ծառայության ժամկետը և նվազեցնելով աղբավայրերի ծավալները և էներգատար նոր անվադողերի արտադրությունը։"},description:{en:"DRIVE SHINA, LLC is a Ukrainian company whose key activity is tyre service. The enterprise specialises in the repair, refurbishment, and renewal of tyres for passenger and commercial vehicles, using professional diagnostic and servicing equipment. || The company's activities are aimed at maximising the use of already embedded product resources. Instead of premature replacement, the company restores tyre functionality and returns them to operational use. || DRIVE SHINA performs puncture, cut, and deformation repairs, tread restoration, structural reinforcement, and retreading – the renewal of the tread layer to extend the tyre's service life. || The environmental benefit lies in reducing the number of tyres sent to landfills or requiring energy-intensive recycling processes. Extending tyre lifespan preserves rubber, steel cord, and textile materials in use, while retreading can consume up to 70% less energy compared to producing a new tyre. || The economic benefit lies in lower costs for vehicle owners and transport companies, as tyre refurbishment is cheaper than purchasing new ones. For fleet operators, this also means less frequent procurement and reduced logistics costs.",uk:"DRIVE SHINA, LLC – українська компанія, її основний напрям діяльності – обслуговування шин. Підприємство спеціалізується на ремонті, модернізації та відновленні шин для легкових і комерційних транспортних засобів, використовуючи професійне діагностичне та сервісне обладнання. || Діяльність компанії спрямована на максимально тривале використання ресурсів, уже вкладених у продукцію. Замість передчасної заміни компанія відновлює функціональність шин і повертає їх до експлуатації. || DRIVE SHINA виконує ремонт проколів, порізів і деформацій, відновлення протектора, посилення конструкції та відновлення протектора методом наварювання – нанесення нового шару протектора для продовження терміну експлуатації шини. || Екологічні переваги – скорочення кількості шин, що потрапляють на звалища або потребують енергоємного перероблення. Продовження терміну експлуатації шин дає змогу зберігати гуму, сталевий корд і текстильні матеріали в експлуатації, тоді як відновлення протектора може потребувати до 70% менше енергії порівняно з виробництвом нової шини. || Економічна вигода – зниження витрат для власників транспортних засобів і транспортних компаній, оскільки відновлення шин коштує дешевше за придбання нових. Для операторів автопарків це також означає меншу потребу в придбанні нових шин і, відповідно, зменшення логістичних витрат.",ro:"DRIVE SHINA, LLC este o companie ucraineană a cărei activitate cheie este deservirea anvelopelor. Întreprinderea este specializată în repararea, recondiționarea și reînnoirea anvelopelor pentru vehicule de pasageri și comerciale, folosind echipamente profesionale de diagnosticare și service. || Activitățile companiei au ca scop maximizarea utilizării resurselor de produse deja încorporate. În loc de înlocuirea prematură, compania restabilește funcționalitatea anvelopelor și le readuce la uz operațional. || DRIVE SHINA efectuează reparații prin perforare, tăiere și deformare, refacere a benzii de rulare, armare structurală și reșapare - reînnoirea stratului benzii de rulare pentru a prelungi durata de viață a anvelopei. || Beneficiul pentru mediu constă în reducerea numărului de anvelope trimise la gropile de gunoi sau necesitatea unor procese de reciclare consumatoare de energie. Extinderea duratei de viață a anvelopei păstrează cauciucul, cablul de oțel și materialele textile utilizate, în timp ce reșaparea poate consuma cu până la 70% mai puțină energie în comparație cu producerea unei anvelope noi. || Beneficiul economic constă în costurile mai mici pentru proprietarii de vehicule și companiile de transport, deoarece recondiționarea anvelopelor este mai ieftină decât achiziționarea unora noi. Pentru operatorii de flote, acest lucru înseamnă, de asemenea, achiziții mai puțin frecvente și costuri logistice reduse.",hy:"DRIVE SHINA, LLC-ն ուկրաինական ընկերություն է, որի հիմնական գործունեությունը անվադողերի սպասարկումն է: Ձեռնարկությունը մասնագիտացած է մարդատար և առևտրային մեքենաների անվադողերի վերանորոգման, վերանորոգման և նորացման մեջ՝ օգտագործելով պրոֆեսիոնալ դիագնոստիկ և սպասարկող սարքավորումներ։ || Ընկերության գործունեությունն ուղղված է արդեն ներդրված արտադրանքի ռեսուրսների առավելագույն օգտագործմանը: Վաղաժամ փոխարինման փոխարեն ընկերությունը վերականգնում է անվադողերի գործունակությունը և վերադարձնում դրանք գործառնական օգտագործման։|| DRIVE SHINA-ն իրականացնում է ծակման, կտրվածքի և դեֆորմացիայի վերանորոգում, քայլքի վերականգնում, կառուցվածքային ամրացում և վերաթողարկում՝ քայլքի շերտի թարմացում՝ անվադողի ծառայության ժամկետը երկարացնելու համար։ || Բնապահպանական օգուտը կայանում է նրանում, որ կրճատվում է աղբավայրեր ուղարկվող անվադողերի քանակը կամ պահանջում են էներգիա պահանջող վերամշակման գործընթացներ: Անվադողերի ծառայության ժամկետի երկարացումը պահպանում է ռետինը, պողպատե լարը և օգտագործվող տեքստիլ նյութերը, մինչդեռ վերաթողումը կարող է մինչև 70% ավելի քիչ էներգիա ծախսել՝ համեմատած նոր անվադողերի արտադրության հետ։ || Տնտեսական օգուտը տրանսպորտային միջոցների սեփականատերերի և տրանսպորտային ընկերությունների համար ցածր ծախսերի մեջ է, քանի որ անվադողերի վերանորոգումն ավելի էժան է, քան նորերը գնելը: Նավատորմի օպերատորների համար դա նաև նշանակում է ավելի քիչ հաճախակի գնումներ և նվազեցված լոգիստիկ ծախսեր։"},caseLink:"https://driveshina.com/",image:"/images/cases/ukraine/drive-shina.jpg",imageAlt:{en:"DRIVE SHINA case image",uk:"Зображення корпусу DRIVE SHINA",ro:"Imaginea carcasei DRIVE SHINA",hy:"DRIVE SHINA գործի պատկերը"}}),e({id:"case-040",slug:"tsekh",companyName:{en:"TSEKH",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Textiles"],rStrategies:["Repair (R4)"],rStrategyDescription:{en:"Sole replacement, heel repair, recolouring and leather restoration replace only worn components, keeping footwear in use for additional seasons rather than being discarded and replaced.",uk:"Заміна підошви, ремонт підборів, відновлення кольору та шкіри дають змогу замінювати лише зношені компоненти, продовжуючи використання взуття протягом сезонів замість його викидання та заміни на нове.",ro:"Înlocuirea talpii, repararea călcâiului, recolorarea și restaurarea pielii înlocuiesc doar componentele uzate, păstrând încălțămintea în uz pentru sezoane suplimentare, mai degrabă decât să fie aruncată și înlocuită.",hy:"Տակացու փոխարինումը, կրունկների վերանորոգումը, գունազարդումը և կաշվի վերականգնումը փոխարինում են միայն մաշված բաղադրիչները, որպեսզի կոշիկները օգտագործվեն լրացուցիչ սեզոնների ընթացքում, այլ ոչ թե դեն նետվեն և փոխարինվեն։"},summary:{en:"TSEKH provides professional footwear repair and restoration services, extending the useful life of shoes as an alternative to replacement and reducing demand for new footwear production.",uk:"TSEKH професійно ремонтує та відновлює взуття, даючи йому друге життя замість придбання нової пари. Це також зменшує потребу у перевиробництві.",ro:"TSEKH oferă servicii profesionale de reparare și restaurare a încălțămintei, prelungind durata de viață utilă a pantofilor ca alternativă la înlocuire și reducând cererea pentru producția de încălțăminte nouă.",hy:"TSEKH-ը մատուցում է պրոֆեսիոնալ կոշիկների վերանորոգման և վերականգնման ծառայություններ՝ երկարացնելով կոշիկների օգտակար կյանքը՝ որպես փոխարինման այլընտրանք և նվազեցնելով նոր կոշիկի արտադրության պահանջարկը։"},description:{en:"TSEKH is a Ukrainian service business providing professional footwear repair, restoration, and care services. The company performs sole replacement, heel repair, recolouring, leather restoration, lining repair, and other works aimed at extending the lifespan of footwear. || The enterprise operates on the principle of maximising the use of existing products instead of prematurely replacing them with new ones. This approach helps preserve product value, reduce resource consumption, and minimise waste generation. This is particularly important for footwear, which consists of multiple materials and is difficult to recycle. || The company applies repair, restoration, and regular maintenance practices. Instead of disposal, the service replaces only worn components, improves the appearance of footwear, and keeps it in proper condition. This allows high-quality shoes to be used for several additional seasons or years. || The environmental benefit lies in waste reduction and decreased demand for new footwear production. It is estimated that producing one pair of leather shoes can generate 10-20 kg CO₂eq, while repair significantly reduces these emissions by extending product life. || The economic benefit for consumers is substantial cost savings, as repair services are significantly cheaper than purchasing new high-quality footwear.",uk:"TSEKH – українське підприємство зі сфери послуг, що надає професійні послуги з ремонту, відновлення та догляду за взуттям. Компанія виконує заміну підошви, ремонт підборів, відновлення кольору, відновлення шкіри, ремонт підкладки та інші роботи, спрямовані на продовження терміну експлуатації взуття. || Підприємство дотримується принципу максимального використання вже наявної продукції замість її передчасної заміни на нову. Такий підхід допомагає зберігати цінність продукції, скорочувати споживання ресурсів і мінімізувати утворення відходів. Це особливо важливо для взуття, яке складається з різних матеріалів і складно піддається переробленню. || Компанія застосовує практики ремонту, відновлення та регулярного догляду. Замість утилізації замінюються лише зношені компоненти, поліпшується зовнішній вигляд взуття та підтримується його належний стан. Це дає змогу використовувати якісне взуття упродовж кількох сезонів або років. || Екологічні переваги – зменшення утворення відходів і скорочення потреби у виробництві нового взуття. За оцінками, виробництво однієї пари шкіряного взуття може спричиняти утворення 10-20 кг CO₂-екв., тоді як ремонт істотно зменшує ці викиди завдяки продовженню терміну  експлуатації продукції. || Економічна вигода для споживачів – суттєве скорочення витрат, оскільки послуги з ремонту значно дешевші за придбання нового якісного взуття.",ro:"TSEKH este o companie de servicii din Ucraina care oferă servicii profesionale de reparare, restaurare și îngrijire a încălțămintei. Compania efectuează înlocuirea talpii, repararea călcâiului, recolorarea, restaurarea pielii, repararea căptușelii și alte lucrări care vizează prelungirea duratei de viață a încălțămintei. || Întreprinderea funcționează pe principiul maximizării utilizării produselor existente în loc să le înlocuiască prematur cu altele noi. Această abordare ajută la păstrarea valorii produsului, la reducerea consumului de resurse și la minimizarea generării de deșeuri. Acest lucru este deosebit de important pentru încălțămintea, care constă din mai multe materiale și este dificil de reciclat. || Compania aplică practici de reparații, restaurare și întreținere regulată. În loc de eliminare, serviciul înlocuiește doar componentele uzate, îmbunătățește aspectul încălțămintei și o menține în stare corespunzătoare. Acest lucru permite folosirea pantofilor de înaltă calitate pentru mai multe sezoane sau ani suplimentari. || Beneficiul pentru mediu constă în reducerea deșeurilor și scăderea cererii pentru producția de încălțăminte nouă. Se estimează că producerea unei perechi de pantofi din piele poate genera 10-20 kg CO₂eq, în timp ce reparația reduce semnificativ aceste emisii prin prelungirea duratei de viață a produsului. || Beneficiul economic pentru consumatori este economiile substanțiale de costuri, deoarece serviciile de reparații sunt semnificativ mai ieftine decât achiziționarea de încălțăminte nouă de înaltă calitate.",hy:"TSEKH-ը ուկրաինական սպասարկման բիզնես է, որը մատուցում է պրոֆեսիոնալ կոշիկների վերանորոգում, վերականգնում և խնամքի ծառայություններ: Ընկերությունը կատարում է ներբանների փոխարինում, կրունկների նորոգում, ներկում, կաշվի վերականգնում, աստառի նորոգում և այլ աշխատանքներ՝ ուղղված կոշիկների շահագործման ժամկետը երկարացնելուն։ || Ձեռնարկությունը գործում է առկա ապրանքների առավելագույն օգտագործումը նորերով ժամանակից շուտ փոխարինելու սկզբունքով: Այս մոտեցումը օգնում է պահպանել արտադրանքի արժեքը, նվազեցնել ռեսուրսների սպառումը և նվազագույնի հասցնել թափոնների առաջացումը: Սա հատկապես կարևոր է կոշիկի համար, որը բաղկացած է բազմաթիվ նյութերից և դժվար է վերամշակել։ || Ընկերությունը կիրառում է վերանորոգման, վերականգնման և կանոնավոր սպասարկման պրակտիկա: Հեռացման փոխարեն ծառայությունը փոխարինում է միայն մաշված բաղադրամասերը, բարելավում է կոշիկների տեսքը և պահում այն պատշաճ վիճակում։ Սա թույլ է տալիս բարձրորակ կոշիկներ օգտագործել մի քանի լրացուցիչ սեզոնների կամ տարիների ընթացքում։|| Բնապահպանական օգուտը կայանում է թափոնների կրճատման և նոր կոշիկի արտադրության պահանջարկի նվազման մեջ: Ենթադրվում է, որ մեկ զույգ կաշվե կոշիկի արտադրությունը կարող է առաջացնել 10-20 կգ CO₂eq, մինչդեռ վերանորոգումը զգալիորեն նվազեցնում է այդ արտանետումները՝ երկարացնելով արտադրանքի կյանքը։ || Սպառողների համար տնտեսական օգուտը ծախսերի զգալի խնայողությունն է, քանի որ վերանորոգման ծառայությունները զգալիորեն ավելի էժան են, քան նոր բարձրորակ կոշիկներ գնելը։"},caseLink:"https://ceh.ua",image:"/images/cases/ukraine/tsekh.jpg",imageAlt:{en:"TSEKH case image",uk:"Корпус ЦЕХ зображення",ro:"Imaginea cazului TSEKH",hy:"ՑԵԽ գործի պատկեր"}}),e({id:"case-041",slug:"chystulia",companyName:{en:"Chystulia",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Textiles"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Shared, temporary access to professional equipment replaces the need for many individual household washing machines (one professional machine can replace 8-15 household machines), reducing overall material and resource consumption.",uk:"Спільний тимчасовий доступ до професійного обладнання дає змогу відмовитися від великої кількості індивідуальних побутових пральних машин: одна професійна машина може замінити 8-15 побутових машин, що скорочує загальне споживання матеріалів і ресурсів.",ro:"Accesul partajat, temporar, la echipamente profesionale înlocuiește nevoia multor mașini de spălat de uz casnic individuale (o mașină profesională poate înlocui 8-15 mașini de uz casnic), reducând consumul total de materiale și resurse.",hy:"Պրոֆեսիոնալ սարքավորումների ընդհանուր, ժամանակավոր հասանելիությունը փոխարինում է բազմաթիվ անհատական կենցաղային լվացքի մեքենաների (մեկ պրոֆեսիոնալ մեքենան կարող է փոխարինել 8-15 կենցաղային մեքենաների) անհրաժեշտությունը՝ նվազեցնելով նյութերի և ռեսուրսների ընդհանուր սպառումը։"},summary:{en:"Chystulia is a self-service laundromat giving customers temporary access to professional washing and drying equipment, reducing the number of household machines needed and cutting per-load energy and water use.",uk:"Chystulia – це пральня самообслуговування, яка надає клієнтам тимчасовий доступ до професійного прального та сушильного обладнання, зменшуючи потребу в побутових пральних машинах і скорочуючи витрати енергії та води на одне завантаження.",ro:"Chystulia este o spălătorie cu autoservire, care oferă clienților acces temporar la echipamente profesionale de spălat și uscare, reducând numărul de mașini de uz casnic necesare și reducând consumul de energie pe sarcină și apă.",hy:"Chystulia-ն ինքնասպասարկվող լվացքատուն է, որը հաճախորդներին հնարավորություն է տալիս ժամանակավոր օգտվել լվացքի և չորացման պրոֆեսիոնալ սարքավորումներից, նվազեցնելով անհրաժեշտ կենցաղային մեքենաների քանակը և կրճատելով էներգիայի և ջրի օգտագործումը յուրաքանչյուր բեռի համար։"},description:{en:"The Chystulia self-service laundromat provides washing and drying services in a self-service format. Customers gain access to professional washing and drying machines without the need to purchase their own equipment. The service is particularly convenient for washing bulky items, everyday clothing, and for using professional detergents. || Instead of individual ownership of equipment, consumers use it temporarily as a service. This reduces the need to produce new washing machines and increases the efficiency of existing equipment utilisation. || The company applies approaches such as temporary access to equipment, a service-based usage model, and centralised operation of resource-efficient machinery. One professional machine can replace 8-15 household washing machines, significantly reducing the consumption of steel, plastic, and electronics. || The environmental benefit lies in reduced production of household appliances, lower electronic waste generation, and more efficient resource use. Professional equipment allows a reduction in electricity consumption by 20-40% and water use by 30-50% per kilogram of laundry. || The economic benefit for clients is the absence of costs related to purchasing equipment, maintenance, repairs, and space for installation. For the business, the model ensures stable service-based revenue, high equipment utilisation, and the potential for network expansion.",uk:"Пральня самообслуговування Chystulia надає послуги прання та сушіння у форматі самообслуговування. Клієнти отримують доступ до професійних пральних і сушильних машин без необхідності купувати власне обладнання. Послуга особливо зручна для прання об’ємних речей, повсякденного одягу та використання професійних засобів для прання. || Замість індивідуального володіння обладнанням споживачі тимчасово користуються ним як послугою. Це зменшує потребу у виробництві нових пральних машин і підвищує ефективність використання вже наявного обладнання. || Компанія застосовує підходи, що передбачають тимчасовий доступ до обладнання, сервісну модель його використання та централізовану експлуатацію ресурсоефективного обладнання. Одна професійна машина може замінити 8-15 побутових пральних машин, що дає змогу суттєво скоротити споживання сталі, пластику та електронних компонентів. || Екологічні переваги – зменшення потреби у виробництві побутової техніки, скорочення утворення електронних відходів і ефективніше використання ресурсів. Професійне обладнання дає змогу скоротити споживання електроенергії на 20-40% і води на 30-50% на кілограм білизни. || Економічні переваги для клієнтів – відсутність витрат на придбання обладнання, його технічне обслуговування та ремонт, а також потреби у виділенні місця для його встановлення. Для бізнесу така модель забезпечує стабільні доходи від надання послуг, високу завантаженість обладнання та можливість розширення мережі.",ro:"Spălătoria cu autoservire Chystulia oferă servicii de spălare și uscare în format self-service. Clienții au acces la mașini profesionale de spălat și uscare fără a fi nevoie să-și achiziționeze propriul echipament. Serviciul este deosebit de convenabil pentru spălarea articolelor voluminoase, a hainelor de zi cu zi și pentru utilizarea detergenților profesioniști. || În loc de proprietatea individuală a echipamentelor, consumatorii îl folosesc temporar ca serviciu. Acest lucru reduce necesitatea de a produce mașini de spălat noi și crește eficiența utilizării echipamentelor existente. || Compania aplică abordări precum accesul temporar la echipamente, un model de utilizare bazat pe servicii și operarea centralizată a utilajelor eficiente din punct de vedere al resurselor. O mașină profesională poate înlocui 8-15 mașini de spălat rufe de uz casnic, reducând semnificativ consumul de oțel, plastic și electronice. || Beneficiul pentru mediu constă în producția redusă de aparate electrocasnice, generarea mai scăzută de deșeuri electronice și utilizarea mai eficientă a resurselor. Echipamentul profesional permite o reducere a consumului de energie electrică cu 20-40% și a consumului de apă cu 30-50% per kilogram de rufe. || Beneficiul economic pentru clienți este absența costurilor legate de achiziționarea de echipamente, întreținere, reparații și spațiu pentru instalare. Pentru afacere, modelul asigură venituri stabile bazate pe servicii, utilizarea ridicată a echipamentelor și potențialul de extindere a rețelei.",hy:"Chystulia ինքնասպասարկման լվացքատունը տրամադրում է լվացքի և չորացման ծառայություններ ինքնասպասարկման ձևաչափով: Հաճախորդները մուտք են ստանում պրոֆեսիոնալ լվացքի և չորացման մեքենաներ՝ առանց իրենց սեփական սարքավորումները ձեռք բերելու անհրաժեշտության: Ծառայությունը հատկապես հարմար է մեծածավալ իրերը, ամենօրյա հագուստը լվանալու և պրոֆեսիոնալ լվացող միջոցներ օգտագործելու համար։ || ՍՍարքավորումների անհատական սեփականության փոխարեն սպառողները այն օգտագործում են ժամանակավորապես որպես ծառայություն: Սա նվազեցնում է նոր լվացքի մեքենաների արտադրության անհրաժեշտությունը և մեծացնում առկա սարքավորումների օգտագործման արդյունավետությունը։ || Ընկերությունը կիրառում է այնպիսի մոտեցումներ, ինչպիսիք են սարքավորումների ժամանակավոր հասանելիությունը, ծառայությունների վրա հիմնված օգտագործման մոդելը և ռեսուրսների համար արդյունավետ մեքենաների կենտրոնացված շահագործումը: Մեկ պրոֆեսիոնալ մեքենան կարող է փոխարինել 8-15 կենցաղային լվացքի մեքենաներ՝ զգալիորեն նվազեցնելով պողպատի, պլաստիկի և էլեկտրոնիկայի սպառումը։ || Բնապահպանական օգուտը կայանում է նրանում, որ կենցաղային տեխնիկայի արտադրությունը կրճատվում է, էլեկտրոնային թափոնների ավելի քիչ արտադրություն և ռեսուրսների ավելի արդյունավետ օգտագործում: Պրոֆեսիոնալ սարքավորումները թույլ են տալիս նվազեցնել էլեկտրաէներգիայի սպառումը 20-40%-ով, իսկ ջրի օգտագործումը՝ 30-50%-ով մեկ կիլոգրամ լվացքի համար։ || Հաճախորդների համար տնտեսական օգուտը սարքավորումների ձեռքբերման, պահպանման, վերանորոգման և տեղադրման համար տարածքի հետ կապված ծախսերի բացակայությունն է: Բիզնեսի համար մոդելը ապահովում է ծառայության վրա հիմնված կայուն եկամուտ, սարքավորումների բարձր օգտագործում և ցանցի ընդլայնման հնարավորություն։"},caseLink:"https://www.chystyulya.com.ua/",image:"/images/cases/ukraine/chystulia.jpg",imageAlt:{en:"Chystulia case image",uk:"Зображення випадку Chystulia",ro:"Imaginea cazului Chstulia",hy:"Chystulia դեպքի պատկերը"}}),e({id:"case-042",slug:"samrent",companyName:{en:"Samrent",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Construction"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Repeated use of the same rented tools by different customers reduces the overall number of tools that need to be manufactured, lowering associated metal, plastic, energy and water consumption.",uk:"Багаторазове використання тих самих орендованих інструментів різними клієнтами дає змогу скоротити загальну кількість інструментів, які потрібно виробляти, а отже – зменшити пов’язані з їх виробництвом витрати металу, пластику, енергії та води.",ro:"Utilizarea repetată a acelorași scule închiriate de către diferiți clienți reduce numărul total de unelte care trebuie fabricate, reducând consumul asociat de metal, plastic, energie și apă.",hy:"Տարբեր հաճախորդների կողմից վարձակալված միևնույն գործիքների կրկնակի օգտագործումը նվազեցնում է արտադրվող գործիքների ընդհանուր թիվը՝ նվազեցնելով դրա հետ կապված մետաղի, պլաստիկի, էներգիայի և ջրի սպառումը։"},summary:{en:"Samrent rents out construction and repair tools, giving customers temporary access to equipment instead of ownership and reducing overall demand for new tool manufacturing.",uk:"Samrent здає в оренду інструменти для будівництва та ремонту, надаючи клієнтам можливість тимчасово користуватися обладнанням замість придбання у власність, що зменшує загальну потребу у виробництві нових інструментів.",ro:"Samrent închiriază unelte de construcție și reparații, oferind clienților acces temporar la echipamente în loc de proprietate și reducând cererea generală pentru fabricarea de noi scule.",hy:"Samrent-ը վարձակալում է շինարարական և վերանորոգման գործիքներ՝ հնարավորություն տալով հաճախորդներին ժամանակավոր հասանելիություն ունենալ սարքավորումներին սեփականության փոխարեն և նվազեցնելով նոր գործիքների արտադրության ընդհանուր պահանջարկը։"},description:{en:"Samrent, LLC is a Ukrainian company providing rental services for construction and repair tools. The company's inventory includes concrete mixers, compressors, vibrating plates, jackhammers, power tools, and other equipment for both professional and household use. || The company provides customers with temporary access to equipment instead of ownership. This is particularly effective for one-time or short-term tasks, when purchased tools often remain unused for long periods after completion. || Through repeated use of the same tools by different customers, the overall demand for new equipment decreases, leading to reduced consumption of metal, plastic, energy, and water. Tools that have lost value for one user continue to serve other clients. In addition, the company provides regular maintenance and repair, extending the service life of equipment and maintaining high functionality. || The environmental benefit lies in reduced overproduction, lower resource consumption, and decreased CO₂ emissions associated with industrial manufacturing. || The economic benefit is shared by both parties: the company gains stable rental income, while customers can access professional tools at a significantly lower cost than purchasing them.",uk:"Samrent, LLC – українська компанія, що надає послуги з оренди будівельних і ремонтних інструментів. Асортимент обладнання компанії охоплює бетономішалки, компресори, віброплити, відбійні молотки, електроінструменти та інше обладнання для професійного й побутового використання. || Компанія надає клієнтам тимчасовий доступ до обладнання замість його придбання. Це особливо ефективно для одноразових або короткострокових робіт, після завершення яких придбані інструменти часто тривалий час залишаються невикористаними. || Завдяки багаторазовому використанню тих самих інструментів різними клієнтами зменшується загальна потреба у виробництві нового обладнання, а отже – споживання металу, пластику, енергії та води. Інструменти, які вже не потрібні одному користувачеві, продовжують використовувати інші клієнти. Крім того, компанія регулярно здійснює технічне обслуговування та ремонт, продовжуючи термін експлуатації обладнання та підтримуючи його належний функціональний стан. || Екологічні переваги – зменшення надлишкового виробництва, скорочення споживання ресурсів і зниження викидів CO₂, пов’язаних із промисловим виробництвом. || Економічна вигода – спільна для обох сторін: компанія отримує стабільний дохід від оренди, а клієнти можуть користуватися професійними інструментами за значно нижчою вартістю, ніж у разі їх придбання.",ro:"Samrent, LLC este o companie ucraineană care oferă servicii de închiriere de scule de construcție și reparații. Inventarul companiei include betoniere, compresoare, plăci vibratoare, ciocane pneumatice, scule electrice și alte echipamente atât pentru uz profesional, cât și pentru uz casnic. || Compania oferă clienților acces temporar la echipamente în loc de proprietate. Acest lucru este deosebit de eficient pentru sarcini unice sau pe termen scurt, când instrumentele achiziționate rămân adesea neutilizate pentru perioade lungi de timp după finalizare. || Prin utilizarea repetată a acelorași instrumente de către diferiți clienți, cererea generală pentru echipamente noi scade, ceea ce duce la un consum redus de metal, plastic, energie și apă. Instrumentele care și-au pierdut valoare pentru un utilizator continuă să servească alți clienți. În plus, compania asigură întreținere și reparații regulate, prelungind durata de viață a echipamentelor și menținând funcționalitatea ridicată. || Beneficiul de mediu constă în reducerea supraproducției, consumul mai scăzut de resurse și scăderea emisiilor de CO₂ asociate producției industriale. || Beneficiul economic este împărțit de ambele părți: compania obține venituri stabile din chirie, în timp ce clienții pot accesa instrumente profesionale la un cost semnificativ mai mic decât achiziționarea acestora.",hy:"Samrent, LLC-ն ուկրաինական ընկերություն է, որը տրամադրում է շինարարական և վերանորոգման գործիքների վարձակալության ծառայություններ: Ընկերության գույքագրումը ներառում է բետոնախառնիչներ, կոմպրեսորներ, թրթռացող թիթեղներ, մուրճեր, էլեկտրական գործիքներ և այլ սարքավորումներ ինչպես պրոֆեսիոնալ, այնպես էլ կենցաղային օգտագործման համար։ || Ընկերությունը հաճախորդներին տրամադրում է սարքավորումների ժամանակավոր հասանելիություն՝ սեփականության փոխարեն: Սա հատկապես արդյունավետ է մեկանգամյա կամ կարճաժամկետ առաջադրանքների համար, երբ գնված գործիքները հաճախ ավարտից հետո երկար ժամանակ չեն օգտագործվում։ || Տարբեր հաճախորդների կողմից նույն գործիքների բազմակի օգտագործման շնորհիվ նոր սարքավորումների ընդհանուր պահանջարկը նվազում է, ինչը հանգեցնում է մետաղի, պլաստիկի, էներգիայի և ջրի սպառման նվազմանը: Գործիքները, որոնք կորցրել են արժեքը մեկ օգտագործողի համար, շարունակում են սպասարկել այլ հաճախորդների: Բացի այդ, ընկերությունն իրականացնում է կանոնավոր սպասարկում և վերանորոգում՝ երկարացնելով սարքավորումների ծառայության ժամկետը և պահպանելով բարձր գործունակությունը։ || Բնապահպանական օգուտը կայանում է գերարտադրության կրճատման, ռեսուրսների ցածր սպառման և արդյունաբերական արտադրության հետ կապված CO₂ արտանետումների նվազման մեջ։ || Տնտեսական օգուտը կիսում են երկու կողմերը. ընկերությունը ստանում է կայուն վարձակալական եկամուտ, մինչդեռ հաճախորդները կարող են օգտվել մասնագիտական գործիքներից զգալիորեն ցածր գնով, քան դրանք գնելը։"},caseLink:"https://samrent.kiev.ua",image:"/images/cases/ukraine/samrent.jpg",imageAlt:{en:"Samrent case image",uk:"Зображення корпусу Samrent",ro:"Imaginea cazului Samrent",hy:"Samrent դեպքի պատկերը"}}),e({id:"case-043",slug:"kinder-prokat",companyName:{en:"Kinder Prokat",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Retail"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Sequential rental use by multiple families reduces the number of new children's products purchased and manufactured, extending each product's effective lifespan across many users.",uk:"Послідовне використання одних і тих самих товарів різними родинами завдяки оренді дає змогу скоротити кількість нових дитячих товарів, які купують і виробляють, та продовжити термін ефективного використання кожного товару.",ro:"Utilizarea succesivă a închirierii de către mai multe familii reduce numărul de produse noi pentru copii achiziționate și fabricate, prelungind durata de viață efectivă a fiecărui produs pentru mulți utilizatori.",hy:"Բազմաթիվ ընտանիքների կողմից վարձակալության հաջորդական օգտագործումը նվազեցնում է գնված և արտադրված մանկական նոր ապրանքների քանակը՝ երկարացնելով յուրաքանչյուր ապրանքի արդյունավետ կյանքի տևողությունը շատ օգտվողների համար։"},summary:{en:"Kinder Prokat rents children's products such as strollers, car seats and play equipment, allowing multiple families to sequentially use the same items and reducing new purchases of fast-outgrown goods.",uk:"Kinder Prokat здає в оренду дитячі товари, як-от візочки, автокрісла та ігрове обладнання, дозволяючи кільком сім'ям послідовно користуватися тими самими речами й зменшуючи кількість покупок нових товарів, з яких діти швидко виростають.",ro:"Kinder Prokat închiriază produse pentru copii, cum ar fi cărucioare, scaune de mașină și echipamente de joacă, permițând mai multor familii să folosească în mod succesiv aceleași articole și reducând noile achiziții de bunuri depășite rapid.",hy:"Kinder Prokat-ը վարձակալում է մանկական ապրանքներ, ինչպիսիք են մանկասայլակները, մեքենայի նստատեղերը և խաղային սարքավորումները, ինչը թույլ է տալիս բազմաթիվ ընտանիքների հաջորդաբար օգտագործել նույն ապրանքները և նվազեցնելով արագ աճող ապրանքների նոր գնումները։"},description:{en:"Kinder Prokat is a local Ukrainian initiative operating in the Zakarpattia oblast. The company offers a wide range of children's products for rent, including strollers, car seats, feeding chairs, baby scales, play complexes, household appliances, and other items. || The enterprise provides customers with temporary access to products instead of purchasing them. This is particularly relevant for children's goods, which are often used only for a short period due to rapid child growth or seasonal needs. || The same product can be sequentially used by many families, which reduces the number of new purchases, lowers material consumption, and extends product lifespan. || Thanks to the rental model, customers save money, as the average usage cost is only 10-12% of the purchase price. In addition, families avoid storage costs for items that quickly become unnecessary. || The environmental benefit lies in the reduction of bulky household waste, lower consumption of plastic, metal, textiles, and electronic components, as well as reduced indirect CO₂ emissions associated with the production of new goods.",uk:"Kinder Prokat – місцева українська ініціатива, що працює в Закарпатській області. Компанія пропонує широкий асортимент дитячих товарів в оренду, зокрема дитячі візочки, автокрісла, стільчики для годування, дитячі ваги, ігрові комплекси, побутову техніку та інші товари. || Підприємство надає клієнтам тимчасовий доступ до товарів замість їх придбання. Це особливо актуально для дитячих товарів, які часто потрібні лише протягом короткого періоду, оскільки діти швидко виростають із них або потреба в таких товарах виникає лише в певний сезон. || Один і той самий товар може послідовно використовуватися багатьма сім’ями, що дає змогу зменшити кількість нових покупок, скоротити споживання матеріалів і продовжити термін експлуатації товарів. || Завдяки моделі оренди клієнти заощаджують кошти, оскільки середня вартість користування становить лише 10-12% від ціни придбання. Крім того, сім’ям не потрібно витрачатися на зберігання речей, які швидко стають непотрібними. || Екологічні переваги – зменшення обсягів великогабаритних побутових відходів, скорочення споживання пластику, металу, текстилю та електронних компонентів, а також зменшення непрямих викидів CO₂, пов’язаних із виробництвом нових товарів.",ro:"Kinder Prokat este o inițiativă locală ucraineană care operează în regiunea Zakarpattia. Compania oferă spre închiriere o gamă largă de produse pentru copii, inclusiv cărucioare, scaune auto, scaune de hrănire, cântare pentru copii, complexe de joacă, aparate de uz casnic și alte articole. || Întreprinderea oferă clienților acces temporar la produse în loc să le cumpere. Acest lucru este deosebit de relevant pentru bunurile pentru copii, care sunt adesea folosite doar pentru o perioadă scurtă din cauza creșterii rapide a copilului sau a nevoilor sezoniere. || Același produs poate fi folosit succesiv de multe familii, ceea ce reduce numărul de noi achiziții, scade consumul de materiale și prelungește durata de viață a produsului. || Datorită modelului de închiriere, clienții economisesc bani, întrucât costul mediu de utilizare este de doar 10-12% din prețul de achiziție. În plus, familiile evită costurile de depozitare pentru articolele care devin rapid inutile. || Beneficiul de mediu constă în reducerea deșeurilor menajere voluminoase, consumul mai mic de plastic, metal, textile și componente electronice, precum și reducerea emisiilor indirecte de CO₂ asociate cu producția de bunuri noi.",hy:"Kinder Prokat-ը տեղական ուկրաինական նախաձեռնություն է, որը գործում է Զաքարպատիայի մարզում: Ընկերությունն առաջարկում է վարձով մանկական ապրանքների լայն տեսականի՝ մանկասայլակներ, մեքենայի նստատեղեր, կերակրման աթոռներ, մանկական կշեռքներ, խաղային համալիրներ, կենցաղային տեխնիկա և այլ իրեր։ || Ձեռնարկությունը հաճախորդներին տրամադրում է ապրանքներ գնելու փոխարեն ժամանակավոր հասանելիություն: Սա հատկապես կարևոր է մանկական ապրանքների համար, որոնք հաճախ օգտագործվում են միայն կարճ ժամանակահատվածում՝ երեխայի արագ աճի կամ սեզոնային կարիքների պատճառով։ || Նույն ապրանքը կարող է հաջորդաբար օգտագործվել բազմաթիվ ընտանիքների կողմից, ինչը նվազեցնում է նոր գնումների քանակը, նվազեցնում նյութի սպառումը և երկարացնում արտադրանքի կյանքի տևողությունը։ || Վարձակալության մոդելի շնորհիվ հաճախորդները խնայում են գումար, քանի որ օգտագործման միջին արժեքը կազմում է գնի ընդամենը 10-12%-ը: Բացի այդ, ընտանիքները խուսափում են պահեստավորման ծախսերից այն իրերի համար, որոնք արագ դառնում են անհարկի։ || Բնապահպանական օգուտը կայանում է նրանում, որ կենցաղային մեծածավալ թափոնների կրճատումը, պլաստիկի, մետաղի, տեքստիլի և էլեկտրոնային բաղադրիչների ավելի քիչ սպառումը, ինչպես նաև նոր ապրանքների արտադրության հետ կապված CO₂ անուղղակի արտանետումների նվազումը։"},caseLink:"https://kinderprokat.com.ua",image:"/images/cases/ukraine/kinder-prokat.jpg",imageAlt:{en:"Kinder Prokat case image",uk:"Зображення корпусу Kinder Prokat",ro:"Imaginea cazului Kinder Prokat",hy:"Kinder Prokat գործի պատկերը"}}),e({id:"case-044",slug:"express-tehbud",companyName:{en:"Express Tehbud",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Construction"],rStrategies:["Reduce (R2)"],rStrategyDescription:{en:"Renting machinery to multiple clients instead of each purchasing separate equipment reduces overall demand for new machinery and the associated steel and metal resource consumption.",uk:"Оренда техніки різними клієнтами замість придбання окремого обладнання кожною компанією дає змогу скоротити загальну потребу в новій техніці та пов’язане з її виробництвом споживання сталі й металів.",ro:"Închirierea de utilaje către mai mulți clienți în loc de achiziționarea fiecăruia de echipamente separate reduce cererea generală pentru utilaje noi și consumul asociat de resurse de oțel și metal.",hy:"Մեքենաների վարձույթը մի քանի հաճախորդների փոխարեն յուրաքանչյուր առանձին սարքավորում գնելու փոխարեն նվազեցնում է նոր մեքենաների ընդհանուր պահանջարկը և դրա հետ կապված պողպատի և մետաղական ռեսուրսների սպառումը։"},summary:{en:"Express Tehbud rents construction machinery such as excavators and loaders, allowing clients to access equipment functions without ownership and increasing overall equipment utilisation rates.",uk:"Express Tehbud надає в оренду будівельну техніку, зокрема екскаватори та навантажувачі, що дозволяє клієнтам використовувати функціонал обладнання без придбання його у власність і підвищує загальний коефіцієнт експлуатації техніки.",ro:"Express Tehbud închiriază mașini de construcții, cum ar fi excavatoare și încărcătoare, permițând clienților să acceseze funcțiile echipamentelor fără proprietate și crescând ratele generale de utilizare a echipamentelor.",hy:"Express Tehbud-ը վարձակալում է շինարարական մեքենաներ, ինչպիսիք են էքսկավատորները և բեռնիչները, ինչը թույլ է տալիս հաճախորդներին մուտք գործել սարքավորումների գործառույթներ առանց սեփականության և բարձրացնելով սարքավորումների օգտագործման ընդհանուր դրույքաչափերը։"},description:{en:"Express Tehbud is a Ukrainian company that rents out construction machinery, including excavators, loaders, aerial work platforms, dump trucks, and other equipment. Clients gain access to machinery for operational use without the need to purchase it. The company also provides servicing, technical support, repair, and logistics. || The company operates under a service-based model where clients use the function of the equipment rather than owning it. This is particularly important in the construction sector, where machinery is often used unevenly and remains idle for significant periods. || The company applies approaches such as temporary access to assets, centralized lifecycle management of equipment, increased utilisation rates, and extended service life through regular maintenance. As a result, a single unit of machinery can serve multiple clients instead of each company purchasing separate equipment. || The environmental benefit lies in reduced demand for new machinery, lower consumption of steel, non-ferrous metals, and other resources, as well as reduced generation of scrap metal and industrial waste. Planned maintenance also extends the operational lifespan of equipment. || The economic benefit for clients includes the absence of large capital expenditures on equipment purchase, flexible usage, and elimination of maintenance and downtime costs. For the company, the model ensures high asset utilisation, stable service-based revenue, and opportunities for refurbishment or resale of equipment.",uk:"Express Tehbud – українська компанія, що здає в оренду будівельну техніку, зокрема екскаватори, навантажувачі, автовишки, самоскиди та інше обладнання. Клієнти отримують доступ до техніки для виконання робіт без необхідності її придбання. Компанія також забезпечує технічне обслуговування, технічну підтримку, ремонт і логістичні послуги. || Компанія працює за сервісною моделлю, за якої клієнти отримують доступ до необхідної техніки без її придбання та володіння нею. Такий підхід особливо актуальний для будівельної галузі, де потреба в техніці може бути періодичною, а придбане обладнання – тривалий час не використовуватися.. || Компанія застосовує підходи, що передбачають тимчасовий доступ до активів, централізоване управління життєвим циклом обладнання, підвищення рівня його використання та продовження терміну експлуатації завдяки регулярному технічному обслуговуванню. У результаті одна одиниця техніки може обслуговувати кількох клієнтів, замість того щоб кожна компанія придбавала окреме обладнання. || Екологічні переваги – зменшення потреби у виробництві нової техніки, скорочення споживання сталі, кольорових металів та інших ресурсів, а також зменшення утворення металобрухту та промислових відходів. Планове технічне обслуговування також продовжує термін експлуатації обладнання. || Економічні переваги для клієнтів – можливість користуватися необхідною технікою без значних капітальних витрат на її придбання, а також без витрат на її технічне обслуговування та утримання в періоди простою. Для компанії така модель дає змогу ефективніше використовувати техніку, отримувати стабільний дохід від її оренди та продовжувати термін її експлуатації завдяки технічному обслуговуванню, відновленню та повторному використанню.",ro:"Express Tehbud este o companie ucraineană care închiriază mașini de construcții, inclusiv excavatoare, încărcătoare, platforme de lucru aeriene, basculante și alte echipamente. Clienții au acces la utilaje pentru utilizare operațională fără a fi nevoie să le achiziționeze. Compania oferă, de asemenea, service, suport tehnic, reparații și logistică. || Compania operează sub un model bazat pe servicii, în care clienții folosesc funcția echipamentului în loc să-l dețină. Acest lucru este deosebit de important în sectorul construcțiilor, unde utilajele sunt adesea utilizate în mod neuniform și rămân inactiv pentru perioade semnificative. || Compania aplică abordări precum accesul temporar la active, gestionarea centralizată a ciclului de viață al echipamentelor, ratele de utilizare crescute și durata de viață extinsă prin întreținere regulată. Ca rezultat, o singură unitate de utilaje poate deservi mai mulți clienți în loc ca fiecare companie să achiziționeze echipamente separate. || Beneficiul de mediu constă în cererea redusă de mașini noi, consumul mai mic de oțel, metale neferoase și alte resurse, precum și generarea redusă de fier vechi și deșeuri industriale. Întreținerea planificată prelungește și durata de viață operațională a echipamentelor. || Beneficiul economic pentru clienți include absența cheltuielilor mari de capital pentru achiziționarea de echipamente, utilizarea flexibilă și eliminarea costurilor de întreținere și de oprire. Pentru companie, modelul asigură o utilizare ridicată a activelor, venituri stabile bazate pe servicii și oportunități de renovare sau revânzare a echipamentelor.",hy:"Express Tehbud-ը ուկրաինական ընկերություն է, որը վարձակալում է շինարարական մեքենաներ, ներառյալ էքսկավատորներ, բեռնիչներ, օդային աշխատանքային հարթակներ, ինքնաթափ մեքենաներ և այլ սարքավորումներ: Հաճախորդները ձեռք են բերում մեքենաների հասանելիություն գործառնական օգտագործման համար՝ առանց դրանք գնելու անհրաժեշտության: Ընկերությունը տրամադրում է նաև սպասարկում, տեխնիկական աջակցություն, վերանորոգում և լոգիստիկա։ || Ընկերությունը գործում է ծառայության վրա հիմնված մոդելի ներքո, որտեղ հաճախորդներն օգտագործում են սարքավորումների գործառույթը, այլ ոչ թե սեփականության իրավունքով: Սա հատկապես կարևոր է շինարարության ոլորտում, որտեղ մեքենաները հաճախ օգտագործվում են անհավասարաչափ և զգալի ժամանակահատվածներում մնում են պարապուրդի մեջ։ || Ընկերությունը կիրառում է այնպիսի մոտեցումներ, ինչպիսիք են ակտիվներին ժամանակավոր մուտքը, սարքավորումների կյանքի ցիկլի կենտրոնացված կառավարումը, օգտագործման արագության բարձրացումը և կանոնավոր սպասարկման ծառայության ժամկետի երկարացումը: Արդյունքում, մեքենաների մեկ միավորը կարող է սպասարկել մի քանի հաճախորդների՝ յուրաքանչյուր ընկերություն առանձին սարքավորումներ գնելու փոխարեն։ || Բնապահպանական օգուտը կապված է նոր մեքենաների պահանջարկի նվազման, պողպատի, գունավոր մետաղների և այլ ռեսուրսների սպառման, ինչպես նաև մետաղի ջարդոնի և արդյունաբերական թափոնների արտադրության կրճատման հետ: Պլանավորված սպասարկումը նաև երկարացնում է սարքավորումների շահագործման ժամկետը։ || Հաճախորդների համար տնտեսական օգուտը ներառում է սարքավորումների ձեռքբերման, ճկուն օգտագործման և պահպանման և պարապուրդի ծախսերի վերացման համար մեծ կապիտալ ծախսերի բացակայությունը: Ընկերության համար մոդելը ապահովում է ակտիվների բարձր օգտագործում, սպասարկման վրա հիմնված կայուն եկամուտ և սարքավորումների վերանորոգման կամ վերավաճառքի հնարավորություններ։"},caseLink:"https://express-tehbud.com",image:"/images/cases/ukraine/express-tehbud.jpg",imageAlt:{en:"Express Tehbud case image",uk:"Зображення корпусу Express Tehbud",ro:"Imaginea carcasei Express Tehbud",hy:"Էքսպրես Թեհբուդի գործի պատկերը"}}),e({id:"case-045",slug:"hempire",companyName:{en:"Hempire",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Construction"],rStrategies:["Rethink (R1)"],rStrategyDescription:{en:"Conventional resource-intensive construction materials are rethought and replaced with a renewable, fast-regenerating, Carbon dioxide (CO2)-absorbing plant-based feedstock (hemp), which after use can be reused or naturally biodegraded.",uk:"Підприємство замінює традиційні ресурсоємні матеріали відновлюваною рослинною сировиною. Технічні коноплі швидко відновлюються, поглинають CO₂ під час вегетації та можуть вирощуватися в Україні, що зменшує транспортні витрати й залежність від імпорту.",ro:"Materialele de construcție convenționale, mari consumatoare de resurse sunt regândite și înlocuite cu o materie primă de origine vegetală (cânepă) regenerabilă, cu regenerare rapidă, care absoarbe dioxid de carbon (CO2), care după utilizare poate fi reutilizată sau biodegradată în mod natural.",hy:"Պայմանական ռեսուրսներ ինտենսիվ շինարարական նյութերը վերանայվում են և փոխարինվում են վերականգնվող, արագ վերականգնվող, ածխածնի երկօքսիդ (CO2) կլանող բուսական հումքով (կանեփ), որն օգտագործելուց հետո կարող է կրկին օգտագործվել կամ բնականորեն կենսաքայքայվել։"},summary:{en:"Hempire manufactures eco-friendly construction materials, including blocks, plasters and insulation, from industrial hemp shives and natural lime binders, substituting renewable feedstock for resource-intensive materials.",uk:"Hempire виробляє екологічні будівельні матеріали – блоки, штукатурки та теплоізоляційні матеріали – з костриці промислових конопель і природних вапняних в’яжучих, замінюючи ресурсоємні матеріали відновлюваною сировиною.",ro:"Hempire produce materiale de construcții ecologice, inclusiv blocuri, tencuieli și izolație, din stupi industriale de cânepă și lianți de var natural, înlocuind materialele regenerabile cu materiale intensive în resurse.",hy:"Hempire-ն արտադրում է էկոլոգիապես մաքուր շինանյութեր, այդ թվում՝ բլոկներ, գիպսեր և մեկուսացում, արդյունաբերական կանեփի շղարշներից և բնական կրաքարի կապող նյութերից՝ փոխարինելով վերականգնվող հումքը ռեսուրսների ինտենսիվ նյութերով։"},description:{en:"HEMPIRE is a Ukrainian company producing environmentally friendly construction materials made from hemp shives (hurds) and natural lime-based binders. The company manufactures blocks, plasters, and insulation materials for energy-efficient and green construction. || The enterprise replaces traditional resource-intensive materials with renewable plant-based raw materials. Industrial hemp regenerates quickly, absorbs CO₂ during growth, and can be cultivated in Ukraine, which reduces transport costs and dependence on imported raw materials. || The use of agricultural residues – hemp shives – allows by-products to be transformed into valuable construction materials. The production process requires less energy, and after use, the materials can be reused or naturally biodegraded. || HEMPIRE products help reduce the carbon footprint in construction. For example, insulating a 100 m² house using Hempire Mix technology can reduce emissions by approximately 34 tons of CO₂ compared to conventional solutions. In addition, the materials enable energy savings of around 30% in heating and cooling costs.",uk:"HEMPIRE – українська компанія, що виробляє екологічні будівельні матеріали з костриці конопель і природних вапняних в’яжучих. Компанія виробляє блоки, штукатурки та теплоізоляційні матеріали для енергоефективного та екологічного будівництва. || Підприємство замінює традиційні ресурсоємні матеріали відновлюваною рослинною сировиною. Промислові коноплі швидко відновлюються, поглинають CO₂ під час вегетації та можуть вирощуватися в Україні, що дає змогу скоротити транспортні витрати й залежність від імпортної сировини. || Використання сільськогосподарських залишків – костриці конопель – дає змогу перетворювати побічні продукти на цінні будівельні матеріали. Виробничий процес потребує менше енергії, а після використання матеріали можуть бути повторно використані або природним шляхом біологічно розкладатися. || Продукція HEMPIRE допомагає зменшити вуглецевий слід будівництва. Наприклад, утеплення будинку площею 100 м² за технологією Hempire Mix може забезпечити скорочення викидів приблизно на 34 тонни CO₂ порівняно з традиційними рішеннями. Крім того, використання цих матеріалів дає змогу заощаджувати близько 30% витрат на опалення та охолодження.",ro:"HEMPIRE este o companie ucraineană care produce materiale de construcție ecologice, realizate din șuruburi de cânepă și lianți naturali pe bază de var. Compania produce blocuri, tencuieli și materiale de izolare pentru construcții ecologice și eficiente din punct de vedere energetic. || Întreprinderea înlocuiește materialele tradiționale mari consumatoare de resurse cu materii prime regenerabile pe bază de plante. Cânepa industrială se regenerează rapid, absoarbe CO₂ în timpul creșterii și poate fi cultivată în Ucraina, ceea ce reduce costurile de transport și dependența de materiile prime importate. || Folosirea reziduurilor agricole – stupi de cânepă – permite ca subprodusele să fie transformate în materiale de construcție valoroase. Procesul de producție necesită mai puțină energie, iar după utilizare, materialele pot fi refolosite sau biodegradate în mod natural. || Produsele HEMPIRE ajută la reducerea amprentei de carbon în construcții. De exemplu, izolarea unei case de 100 m² folosind tehnologia Hempire Mix poate reduce emisiile cu aproximativ 34 de tone de CO₂ în comparație cu soluțiile convenționale. În plus, materialele permit economii de energie de aproximativ 30% la costurile de încălzire și răcire.",hy:"HEMPIRE-ը ուկրաինական ընկերություն է, որն արտադրում է էկոլոգիապես մաքուր շինանյութեր, որոնք պատրաստված են կանեփի ցողուններից և բնական կրաքարի հիմքով կապող նյութերից: Ընկերությունն արտադրում է բլոկներ, սվաղներ և մեկուսիչ նյութեր էներգաարդյունավետ և կանաչ շինարարության համար։ || Ձեռնարկությունը ավանդական ռեսուրսների ինտենսիվ նյութերը փոխարինում է վերականգնվող բուսական հումքով: Արդյունաբերական կանեփը արագ վերականգնվում է, աճի ընթացքում կլանում է CO₂ և կարող է մշակվել Ուկրաինայում, ինչը նվազեցնում է տրանսպորտային ծախսերը և կախվածությունը ներմուծվող հումքից։ || Գյուղատնտեսական մնացորդների՝ կանեփի մնացորդների օգտագործումը թույլ է տալիս ենթամթերքները վերածել արժեքավոր շինանյութերի: Արտադրության գործընթացը պահանջում է ավելի քիչ էներգիա, և օգտագործելուց հետո նյութերը կարող են նորից օգտագործվել կամ բնականորեն կենսաքայքայվել։ || HEMPIRE արտադրանքը օգնում է նվազեցնել ածխածնի հետքը շինարարության մեջ: Օրինակ, Hempire Mix տեխնոլոգիայի կիրառմամբ 100 մ² տան մեկուսացումը կարող է նվազեցնել CO2 արտանետումները մոտավորապես 34 տոննայով` համեմատած սովորական լուծումների: Բացի այդ, նյութերը թույլ են տալիս մոտ 30% էներգիա խնայել ջեռուցման և հովացման ծախսերում։"},caseLink:"https://hempire.com.ua",image:"/images/cases/ukraine/hempire.jpg",imageAlt:{en:"Hempire case image",uk:"Зображення корпусу Hempire",ro:"Imaginea cazului Hempire",hy:"Hempire դեպքի պատկերը"}}),e({id:"case-046",slug:"univest",companyName:{en:"Univest",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Packaging"],rStrategies:["Recycle (R8)","Rethink (R1)"],rStrategyDescription:{en:"Products are designed to be recycled and returned to the production cycle after use (Recycle); plastic and polyethylene packaging materials are rethought and replaced with renewable, recyclable paper and cellulose alternatives (Rethink).",uk:"Продукція так розроблена, щоб після використання її можна було переробити та повернути у виробничий цикл (Перероблення); пластикове та поліетиленове паковання переосмислюється та замінюється відновлюваними паперовими й целюлозними альтернативами, придатними до перероблення (Переосмислення).",ro:"Produsele sunt concepute pentru a fi reciclate și returnate la ciclul de producție după utilizare (Reciclare); Materialele de ambalare din plastic și polietilenă sunt regândite și înlocuite cu hârtie regenerabilă, reciclabilă și alternative de celuloză (Rethink).",hy:"Արտադրանքը նախագծված է վերամշակվելու և օգտագործելուց հետո արտադրական ցիկլ վերադարձնելու համար (Recycle); Պլաստիկ և պոլիէթիլենային փաթեթավորման նյութերը վերանայվում և փոխարինվում են վերականգնվող, վերամշակվող թղթի և ցելյուլոզային այլընտրանքներով (Rethink)։"},summary:{en:"Univest manufactures paper-based packaging products designed for recyclability, replacing plastic and polyethylene packaging with renewable, recyclable cellulose materials at scale.",uk:"Univest виробляє паперове паковання, придатне для перероблення, замінюючи пластикове та поліетиленове паковання відновлюваними й придатними для перероблення целюлозними матеріалами у великих масштабах.",ro:"Univest produce ambalaje pe bază de hârtie concepute pentru reciclare, înlocuind ambalajele din plastic și polietilenă cu materiale celulozice regenerabile și reciclabile la scară.",hy:"Univest-ը արտադրում է թղթի վրա հիմնված փաթեթավորման արտադրանք, որը նախատեսված է վերամշակման համար՝ փոխարինելով պլաստիկ և պոլիէթիլենային փաթեթավորումը վերականգնվող, վերամշակվող ցելյուլոզային նյութերով։"},description:{en:"Univest Company, LLC is one of the largest packaging manufacturers in Ukraine. The company operates on a full-cycle basis, producing paper cups, containers, plates, boxes, salad bowls, and molded pulp lids for HoReCa, delivery services, retail, and petrol stations. || The enterprise replaces plastic and polyethylene with renewable and recyclable materials. In particular, the company produces UniCup cups and UniLids lids, which can be recycled after use and returned into the production cycle. || The use of paper and cellulose simplifies waste recycling, reduces dependence on virgin raw materials, and decreases plastic waste generation. In addition, Univest implements resource-efficient solutions, including a solar power plant and a closed-loop water system, which reduce energy and water consumption. || The environmental benefit lies in reduced waste generation, lower CO₂ emissions, and decreased environmental pressure. At the same time, the company gains economic advantages through material circularity and reduced dependence on expensive energy resources.",uk:"Univest Company, LLC – один із найбільших виробників паковання в Україні. Компанія працює за повним виробничим циклом і виробляє паперові стакани, контейнери, тарілки, коробки, салатники та кришки з формованої целюлози для закладів громадського харчування, служб доставки, роздрібної торгівлі та автозаправних станцій. || Підприємство замінює пластик і поліетилен відновлюваними матеріалами, придатними до перероблення. Зокрема, компанія виробляє стакани UniCup і кришки UniLids, які після використання можна переробити та повернути у виробничий цикл. || Використання паперу та целюлози спрощує перероблення відходів, зменшує залежність від первинної сировини та скорочує утворення пластикових відходів. Крім того, Univest упроваджує ресурсоефективні рішення, зокрема сонячну електростанцію та замкнену систему водопостачання, що дають змогу скоротити споживання енергії та води. || Екологічні переваги – зменшення утворення відходів, скорочення викидів CO₂ та зниження негативного впливу на довкілля. Водночас компанія отримує економічні переваги завдяки циркулярному використанню матеріалів і зменшенню залежності від дорогих енергоресурсів.",ro:"Univest Company, LLC este unul dintre cei mai mari producători de ambalaje din Ucraina. Compania operează pe un ciclu complet, producând pahare de hârtie, recipiente, farfurii, cutii, boluri de salată și capace turnate de pulpă pentru HoReCa, servicii de livrare, comerț cu amănuntul și benzinării. || Întreprinderea înlocuiește plasticul și polietilena cu materiale regenerabile și reciclabile. În special, compania produce pahare UniCup și capace UniLids, care pot fi reciclate după utilizare și returnate în ciclul de producție. || Utilizarea hârtiei și a celulozei simplifică reciclarea deșeurilor, reduce dependența de materiile prime virgine și scade generarea de deșeuri din plastic. În plus, Univest implementează soluții eficiente din punct de vedere al resurselor, inclusiv o centrală solară și un sistem de apă în circuit închis, care reduc consumul de energie și apă. || Beneficiul pentru mediu constă în reducerea generării de deșeuri, emisii mai scăzute de CO₂ și scăderea presiunii asupra mediului. În același timp, compania câștigă avantaje economice prin circularitatea materială și dependența redusă de resurse energetice costisitoare.",hy:"Univest Company, LLC-ն Ուկրաինայի ամենամեծ փաթեթավորում արտադրողներից է: Ընկերությունը գործում է ամբողջ ցիկլի հիման վրա՝ արտադրելով թղթե բաժակներ, տարաներ, ափսեներ, տուփեր, աղցանների ամաններ և կաղապարված կափարիչներ HoReCa-ի, առաքման ծառայությունների, մանրածախ առևտրի և բենզալցակայանների համար։ || Ձեռնարկությունը պլաստիկն ու պոլիէթիլենը փոխարինում է վերականգնվող և վերամշակվող նյութերով։ Մասնավորապես, ընկերությունն արտադրում է UniCup բաժակներ և UniLids կափարիչներ, որոնք կարող են օգտագործվելուց հետո վերամշակվել և վերադարձվել արտադրության ցիկլ։ || Թղթի և ցելյուլոզայի օգտագործումը հեշտացնում է թափոնների վերամշակումը, նվազեցնում է կույս հումքից կախվածությունը և նվազեցնում պլաստիկ թափոնների արտադրությունը: Բացի այդ, Univest-ն իրականացնում է ռեսուրսների արդյունավետ լուծումներ, ներառյալ արևային էլեկտրակայան և փակ ջրային համակարգ, որոնք նվազեցնում են էներգիայի և ջրի սպառումը։ || Բնապահպանական օգուտը կապված է թափոնների արտադրության կրճատման, CO2-ի ցածր արտանետումների և շրջակա միջավայրի ճնշման նվազման մեջ: Միևնույն ժամանակ, ընկերությունը տնտեսական առավելություններ է ստանում նյութական շրջանաձևության և թանկ էներգառեսուրսներից կախվածության նվազեցման շնորհիվ։"},caseLink:"https://univest.ua",image:"/images/cases/ukraine/univest.jpg",imageAlt:{en:"Univest case image",uk:"Зображення корпусу Univest",ro:"Imagine de caz Univest",hy:"Univest գործի պատկերը"}}),e({id:"case-047",slug:"eco-build-ukraine",companyName:{en:"Eco Build Ukraine",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Construction"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Straw, an agricultural residue often left unused or burned, is compressed and processed into structural and insulation panels, converting an agricultural by-product into a construction material input.",uk:"Солома – сільськогосподарський побічний продукт, який часто залишається невикористаним або спалюється, – спресовується та переробляється на конструкційні й теплоізоляційні панелі, перетворюючи сільськогосподарський побічний продукт на сировину для виробництва будівельних матеріалів.",ro:"Paiele, un reziduu agricol adesea lăsat nefolosit sau arse, sunt comprimate și prelucrate în panouri structurale și izolatoare, transformând un produs secundar agricol într-un material de construcții.",hy:"Ծղոտը, գյուղատնտեսական մնացորդը, որը հաճախ մնում է չօգտագործված կամ այրված, սեղմվում և մշակվում է կառուցվածքային և մեկուսիչ պանելների մեջ՝ գյուղատնտեսական ենթամթերքը վերածելով շինանյութի մուտքի։"},summary:{en:"Eco Build Ukraine manufactures structural and insulation panels from compressed straw, an agricultural by-product, substituting a renewable, carbon-sequestering material for conventional construction inputs.",uk:"Ця компанія виробляє конструкційні та ізоляційні панелі із пресованої соломи (побічного продукту сільського господарства), замінюючи традиційні будівельні матеріали відновлюваним матеріалом, що поглинає та утримує вуглець.",ro:"Eco Build Ukraine produce panouri structurale și izolatoare din paie comprimată, un produs secundar agricol, înlocuind un material regenerabil, de captare a carbonului, cu inputurile convenționale de construcție.",hy:"Eco Build Ukraine-ն արտադրում է կառուցվածքային և մեկուսիչ պանելներ սեղմված ծղոտից, որը գյուղատնտեսական կողմնակի արտադրանք է, որը փոխարինում է վերականգնվող, ածխածնի զավթիչ նյութը սովորական շինարարական նյութերի համար։"},description:{en:"Eco Build Ukraine is a Ukrainian manufacturer of structural and thermal insulation panels made from compressed straw. The company produces eco-friendly solutions for residential and commercial construction used in external walls, insulation systems, frame structures, and energy-efficient buildings. || The enterprise replaces traditional resource-intensive materials with renewable bio-based feedstock. The main raw material is straw – an agricultural by-product that is often left unused or burned. || The company applies approaches based on agricultural residue utilisation, production of biodegradable materials, reduction of construction-related carbon emissions, and development of local supply chains. This enables the use of local resources, reduces transportation costs, and creates added value in regional economies. || The environmental benefit lies in reduced straw burning, lower construction waste generation, and decreased CO₂ emissions. Straw contains biogenic carbon, meaning that 1 m³ of panels can sequester approximately 80-120 kg of CO₂, whereas conventional insulation materials have a significantly higher carbon footprint. || The economic benefit is reflected in lower insulation costs, faster installation, and reduced building heating expenses. Energy savings are estimated at 20-40% compared to standard solutions. Additionally, the agricultural sector gains new revenue streams from straw sales, while regions benefit from job creation and local economic development.",uk:"Eco Build Ukraine – український виробник конструкційних і теплоізоляційних панелей зі спресованої соломи. Компанія виробляє екологічні рішення для житлового та комерційного будівництва, які використовуються для зовнішніх стін, теплоізоляційних систем, каркасних конструкцій та енергоефективних будівель. || Підприємство замінює традиційні ресурсоємні матеріали відновлюваною сировиною біологічного походження. Основна сировина – солома, сільськогосподарський побічний продукт, який часто залишається невикористаним або спалюється. || Компанія застосовує підходи, що передбачають використання сільськогосподарських побічних продуктів, виробництво біологічно розкладних матеріалів, скорочення викидів вуглецю, пов’язаних із будівництвом, та розвиток локальних ланцюгів постачання. Це дає змогу використовувати місцеві ресурси, скорочувати транспортні витрати та створювати додану вартість у регіональній економіці. || Екологічні переваги – скорочення спалювання соломи, зменшення утворення будівельних відходів та скорочення викидів CO₂. Солома містить біогенний вуглець, завдяки чому 1 м³ панелей може утримувати приблизно 80-120 кг CO₂, тоді як традиційні теплоізоляційні матеріали мають значно більший вуглецевий слід. || Економічні переваги – нижча вартість теплоізоляції, швидше встановлення та скорочення витрат на опалення будівель. За оцінками, економія енергії становить 20-40% порівняно зі стандартними рішеннями. Крім того, сільськогосподарська галузь отримує нові джерела доходу завдяки продажу соломи, а регіони – нові робочі місця та можливості для розвитку місцевої економіки.",ro:"Eco Build Ukraine este un producător ucrainean de panouri structurale și termoizolante din paie comprimată. Compania produce soluții ecologice pentru construcții rezidențiale și comerciale utilizate în pereți exteriori, sisteme de izolare, structuri de cadru și clădiri eficiente din punct de vedere energetic. || Întreprinderea înlocuiește materialele tradiționale mari consumatoare de resurse cu materii prime regenerabile pe bază de bio. Materia primă principală este paiele – un produs secundar agricol care este adesea lăsat nefolosit sau ars. || Compania aplică abordări bazate pe utilizarea reziduurilor agricole, producția de materiale biodegradabile, reducerea emisiilor de carbon legate de construcții și dezvoltarea lanțurilor locale de aprovizionare. Acest lucru permite utilizarea resurselor locale, reduce costurile de transport și creează valoare adăugată în economiile regionale. || Beneficiul pentru mediu constă în reducerea arderii paielor, reducerea generării de deșeuri din construcții și reducerea emisiilor de CO₂. Paiele conțin carbon biogen, ceea ce înseamnă că 1 m³ de panouri poate capta aproximativ 80-120 kg de CO₂, în timp ce materialele de izolație convenționale au o amprentă de carbon semnificativ mai mare. || Beneficiul economic se reflectă în costuri mai mici de izolare, instalare mai rapidă și cheltuieli reduse pentru încălzirea clădirii. Economiile de energie sunt estimate la 20-40% fata de solutiile standard. În plus, sectorul agricol câștigă noi fluxuri de venituri din vânzările de paie, în timp ce regiunile beneficiază de crearea de locuri de muncă și de dezvoltarea economică locală.",hy:"Eco Build Ukraine-ն ուկրաինական արտադրող է սեղմված ծղոտից պատրաստված կառուցվածքային և ջերմամեկուսիչ պանելների: Ընկերությունն արտադրում է էկոլոգիապես մաքուր լուծումներ բնակելի և կոմերցիոն շինարարության համար, որոնք օգտագործվում են արտաքին պատերի, մեկուսացման համակարգերի, շրջանակային կառույցների և էներգաարդյունավետ շենքերի համար։ || Ձեռնարկությունը փոխարինում է ավանդական ռեսուրսների ինտենսիվ նյութերը վերականգնվող կենսաբանական հումքով: Հիմնական հումքը ծղոտն է՝ գյուղատնտեսական ենթամթերք, որը հաճախ մնում է չօգտագործված կամ այրվում։ || Ընկերությունը կիրառում է մոտեցումներ՝ հիմնված գյուղատնտեսական մնացորդների օգտագործման, կենսաքայքայվող նյութերի արտադրության, շինարարության հետ կապված ածխածնի արտանետումների նվազեցման և տեղական մատակարարման շղթայի զարգացման վրա: Սա հնարավորություն է տալիս օգտագործել տեղական ռեսուրսները, նվազեցնում է տրանսպորտային ծախսերը և ավելացված արժեք է ստեղծում տարածաշրջանային տնտեսություններում։ || Բնապահպանական օգուտը կայանում է նրանում, որ կրճատվում է ծղոտի այրումը, շինարարական թափոնների պակասը և CO₂ արտանետումները: Ծղոտը պարունակում է բիոգեն ածխածին, ինչը նշանակում է, որ 1 մ³ պանելները կարող են կլանել մոտավորապես 80-120 կգ CO2, մինչդեռ սովորական մեկուսիչ նյութերն ունեն զգալիորեն ավելի բարձր ածխածնի հետք։ || Տնտեսական օգուտը արտացոլվում է մեկուսացման ավելի ցածր ծախսերով, ավելի արագ տեղադրմամբ և շենքի ջեռուցման ծախսերի կրճատմամբ: Էներգախնայողությունը գնահատվում է 20-40% ստանդարտ լուծումների համեմատ: Բացի այդ, գյուղատնտեսության ոլորտը եկամուտների նոր հոսքեր է ստանում ծղոտի վաճառքից, մինչդեռ մարզերը շահում են աշխատատեղերի ստեղծումից և տեղական տնտեսական զարգացումից։"},caseLink:"https://eco-build.com.ua",image:"/images/cases/ukraine/eco-build-ukraine.jpg",imageAlt:{en:"Eco Build Ukraine case image",uk:"Зображення корпусу Eco Build Ukraine",ro:"Imaginea cazului Eco Build Ukraine",hy:"Eco Build Ukraine գործի պատկերը"}}),e({id:"case-048",slug:"lion-recycling-ukraine",companyName:{en:"Lion Recycling Ukraine",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Plastics"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Plastic waste undergoes sorting, cleaning, shredding, washing and granulation, after which it is returned to the production cycle as recycled polymer granules used to manufacture new products.",uk:"Пластикові відходи сортують, очищують, подрібнюють, миють та гранулюють, після чого повертають у виробничий цикл у вигляді вторинних полімерних гранул, які використовуються для виробництва нової продукції.",ro:"Deșeurile de plastic sunt supuse sortării, curățării, mărunțirii, spălării și granulării, după care sunt returnate în ciclul de producție sub formă de granule polimerice reciclate utilizate pentru fabricarea de produse noi.",hy:"Պլաստիկ թափոնները ենթարկվում են տեսակավորման, մաքրման, մանրացման, լվացման և հատիկավորման, որից հետո այն վերադարձվում է արտադրական ցիկլ՝ որպես վերամշակված պոլիմերային հատիկներ, որոնք օգտագործվում են նոր արտադրանքի արտադրության համար։"},summary:{en:"Lion Recycling Ukraine collects, sorts and processes plastic waste into secondary polymer granules, returning recycled material into industrial production and reducing reliance on virgin polymer resources.",uk:"Lion Recycling Ukraine збирає, сортує та переробляє пластикові відходи на вторинні полімерні гранули, повертаючи вторинну сировину в промислове виробництво та зменшуючи залежність від первинних полімерних ресурсів.",ro:"Lion Recycling Ukraine colectează, sortează și prelucrează deșeurile de plastic în granule polimerice secundare, returnând materialul reciclat în producția industrială și reducând dependența de resursele polimerice virgine.",hy:"Lion Recycling Ukraine-ն հավաքում, տեսակավորում և վերամշակում է պլաստիկ թափոնները երկրորդական պոլիմերային հատիկների՝ վերամշակված նյութերը վերադարձնելով արդյունաբերական արտադրության և նվազեցնելով կուս պոլիմերային ռեսուրսների կախվածությունը։"},description:{en:"Lion Recycling Ukraine is one of Ukraine's leading operators in the field of polymer waste recycling. The company specializes in the collection, sorting, and processing of plastic waste, followed by the production of secondary polymer granules for industrial use. || The company transforms plastic waste into high-quality raw materials for manufacturing new products. It works with various types of polymers, plastic packaging, films, and production scraps. || The waste undergoes a multi-stage treatment process, including sorting, cleaning, shredding, washing, and granulation, after which it is returned to the production cycle in the form of recycled polymer granules. These materials are used to manufacture packaging, films, pipes, construction products, and other goods. || The environmental impact includes reducing the volume of plastic waste, decreasing landfill pressure, and lowering the demand for virgin polymer resources. Plastic recycling also requires less energy compared to the production of new raw materials. || The economic impact is reflected in lower material costs for Ukrainian manufacturers. The use of recycled granules can provide savings of up to EUR 200 per tonne of raw material, reducing the production cost of finished goods. In addition, the company creates a stable market for plastic waste and generates jobs in the recycling sector.",uk:"Lion Recycling Ukraine – один із провідних операторів України у сфері перероблення полімерних відходів. Компанія спеціалізується на збиранні, сортуванні та переробленні пластикових відходів із подальшим виробництвом вторинних полімерних гранул для промислового використання. || Компанія перетворює пластикові відходи на якісну сировину для виробництва нової продукції. Вона працює з різними видами полімерів, пластиковим пакованням, плівками та виробничими відходами. || Пластикові відходи піддають багатоступеневому обробленню, яке охоплює сортування, очищення, подрібнення, миття та гранулювання, після чого вони повертаються у виробничий цикл у вигляді вторинних полімерних гранул. Ці матеріали використовуються для виробництва паковання, плівок, труб, будівельної продукції та інших товарів. || Екологічні переваги – зменшення обсягів пластикових відходів, зниження навантаження на полігони та скорочення потреби у первинній полімерній сировині. Перероблення пластику також потребує менше енергії порівняно з виробництвом нової сировини. || Економічні переваги – зниження витрат українських виробників на сировину. Використання вторинних полімерних гранул дає змогу заощаджувати до 200 євро на тонні сировини, зменшуючи собівартість готової продукції. Крім того, компанія створює стабільний ринок для пластикових відходів та робочі місця у сфері перероблення.",ro:"Lion Recycling Ukraine este unul dintre principalii operatori ai Ucrainei în domeniul reciclării deșeurilor de polimeri. Compania este specializată în colectarea, sortarea și prelucrarea deșeurilor din plastic, urmată de producția de granule polimerice secundare pentru uz industrial. || Compania transformă deșeurile de plastic în materii prime de înaltă calitate pentru fabricarea de produse noi. Funcționează cu diferite tipuri de polimeri, ambalaje din plastic, filme și resturi de producție. || Deșeurile sunt supuse unui proces de tratare în mai multe etape, inclusiv sortare, curățare, mărunțire, spălare și granulare, după care sunt returnate în ciclul de producție sub formă de granule polimerice reciclate. Aceste materiale sunt utilizate pentru fabricarea de ambalaje, filme, țevi, produse de construcții și alte bunuri. || Impactul asupra mediului include reducerea volumului deșeurilor de plastic, scăderea presiunii la depozitul de deșeuri și scăderea cererii de resurse de polimer virgin. Reciclarea plasticului necesită, de asemenea, mai puțină energie în comparație cu producerea de noi materii prime. || Impactul economic se reflectă în costuri mai mici ale materialelor pentru producătorii ucraineni. Utilizarea granulelor reciclate poate oferi economii de până la 200 EUR pe tonă de materie primă, reducând costul de producție al produselor finite. În plus, compania creează o piață stabilă pentru deșeurile de plastic și generează locuri de muncă în sectorul reciclării.",hy:"Lion Recycling Ukraine-ն Ուկրաինայի առաջատար օպերատորներից մեկն է պոլիմերային թափոնների վերամշակման ոլորտում: Ընկերությունը մասնագիտացած է պլաստիկ թափոնների հավաքման, տեսակավորման և վերամշակման մեջ, որին հաջորդում է արդյունաբերական օգտագործման համար նախատեսված երկրորդական պոլիմերային հատիկների արտադրությունը։ || Ընկերությունը պլաստիկ թափոնները վերածում է բարձրորակ հումքի՝ նոր արտադրանքի արտադրության համար: Այն աշխատում է տարբեր տեսակի պոլիմերների, պլաստիկ փաթեթավորման, թաղանթների և արտադրության ջարդոնների հետ։ || Թափոնն անցնում է բազմափուլ մաքրման գործընթաց՝ ներառյալ տեսակավորում, մաքրում, մանրացում, լվացում և հատիկավորում, որից հետո վերամշակված պոլիմերային հատիկների տեսքով վերադառնում է արտադրության ցիկլ: Այս նյութերն օգտագործվում են փաթեթավորման, թաղանթների, խողովակների, շինարարական ապրանքների և այլ ապրանքների արտադրության համար։ || Շրջակա միջավայրի վրա ազդեցությունը ներառում է պլաստիկ թափոնների ծավալի կրճատում, աղբավայրի ճնշման նվազում և կուսական պոլիմերային ռեսուրսների պահանջարկի նվազում: Պլաստիկի վերամշակումը նույնպես պահանջում է ավելի քիչ էներգիա՝ համեմատած նոր հումքի արտադրության հետ։|| Տնտեսական ազդեցությունն արտահայտվում է ուկրաինական արտադրողների համար նյութական ծախսերի ցածր մակարդակով: Վերամշակված հատիկների օգտագործումը կարող է ապահովել մինչև 200 եվրո խնայողություն մեկ տոննա հումքի համար՝ նվազեցնելով պատրաստի արտադրանքի արտադրության արժեքը: Բացի այդ, ընկերությունը ստեղծում է պլաստիկ թափոնների կայուն շուկա և աշխատատեղեր ստեղծում վերամշակման ոլորտում։"},caseLink:"https://lion-recycling.com.ua",image:"/images/cases/ukraine/lion-recycling-ukraine.jpg",imageAlt:{en:"Lion Recycling Ukraine case image",uk:"Зображення кейсу Lion Recycling Ukraine",ro:"Imaginea cazului Lion Recycling Ukraine",hy:"Lion Recycling Ukraine դեպքի պատկերը"}}),e({id:"case-050",slug:"util-akb",companyName:{en:"Util-akb",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Waste Management"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Used batteries are processed to recover lead, plastic casings, neutralised electrolytes, and non-ferrous metals, returning 95-99% of valuable materials to the production cycle for new batteries and industrial products.",uk:"Відпрацьовані акумулятори піддають обробленню для вилучення свинцю, пластикових корпусів, нейтралізованого електроліту та кольорових металів, після чого 95-99% цінних матеріалів повертаються у виробничий цикл для виготовлення нових акумуляторів та промислової продукції.",ro:"Bateriile uzate sunt procesate pentru a recupera plumbul, carcasele din plastic, electroliții neutralizați și metalele neferoase, returnând 95-99% din materiale valoroase în ciclul de producție pentru baterii noi și produse industriale.",hy:"Օգտագործված մարտկոցները վերամշակվում են կապարի, պլաստիկ պատյանների, չեզոքացված էլեկտրոլիտների և գունավոր մետաղների վերականգնման համար՝ արժեքավոր նյութերի 95-99%-ը վերադարձնելով նոր մարտկոցների և արդյունաբերական արտադրանքի արտադրության ցիկլ։"},summary:{en:"Util-akb collects and recycles used lead-acid batteries, recovering lead, plastics and non-ferrous metals for return into production while preventing toxic contamination from improper disposal.",uk:"Util-akb збирає та переробляє відпрацьовані свинцево-кислотні акумулятори, вилучаючи свинець, пластик і кольорові метали для повернення у виробництво та запобігаючи токсичному забрудненню від неналежної утилізації.",ro:"Util-akb colectează și reciclează bateriile plumb-acid uzate, recuperând plumbul, materialele plastice și metalele neferoase pentru revenirea în producție, prevenind în același timp contaminarea toxică de la eliminarea necorespunzătoare.",hy:"Util-akb-ն հավաքում և վերամշակում է օգտագործված կապարաթթվային մարտկոցները, կապարը, պլաստմասսա և գունավոր մետաղները վերադարձնելու համար՝ արտադրություն վերադարձնելու համար՝ միաժամանակ կանխելով թունավոր աղտոտումը ոչ պատշաճ հեռացումից։"},description:{en:"Util-akb specializes in the collection and recycling of used batteries, including starter, traction, and stationary lead-acid batteries. The company also handles lead, damaged batteries, and individual battery components. || The company converts hazardous waste into valuable secondary raw materials. This enables not only the safe disposal of used batteries but also the return of materials into the production cycle. || During the recycling process, lead and lead alloys are recovered for the production of new batteries, plastic casings are shredded and reused, and electrolytes are neutralized for further industrial application. Non-ferrous metals, including copper, nickel, and cadmium, are also recovered and returned to recycling streams. || The environmental impact lies in preventing toxic substances from contaminating soil and water. It is estimated that a single battery can pollute around 20 m² of soil or 400 litres of water, making proper recycling highly important for environmental protection. In addition, recycling reduces the need for extracting virgin resources and lowers the carbon footprint. || The economic impact includes the recovery of 95-99% of valuable materials from lead-acid batteries, reducing raw material costs for manufacturers of new batteries and other industrial products.",uk:"Util-akb спеціалізується на збиранні та переробленні відпрацьованих акумуляторів, зокрема стартерних, тягових і стаціонарних свинцево-кислотних акумуляторів. Компанія також працює зі свинцем, пошкодженими акумуляторами та окремими компонентами акумуляторів. || Компанія перетворює небезпечні відходи на цінну вторинну сировину. Це дає змогу не лише безпечно поводитися з відпрацьованими акумуляторами, а й повертати матеріали у виробничий цикл. || У процесі перероблення свинець і свинцеві сплави вилучають для виробництва нових акумуляторів, пластикові корпуси подрібнюють і використовують повторно, а електроліти нейтралізують для подальшого промислового застосування. Кольорові метали, зокрема мідь, нікель і кадмій, також вилучають і повертають у потоки перероблення. || Екологічні переваги – запобігання потраплянню токсичних речовин у ґрунт і воду. За оцінками, один акумулятор може забруднити близько 20 м² ґрунту або 400 літрів води, тому належне перероблення має важливе значення для захисту довкілля. Крім того, перероблення зменшує потребу у видобуванні первинних ресурсів та скорочує вуглецевий слід. || Економічні переваги – вилучення 95-99% цінних матеріалів зі свинцево-кислотних акумуляторів, що дає змогу зменшити витрати на сировину для виробників нових акумуляторів та іншої промислової продукції.",ro:"Util-akb este specializată în colectarea și reciclarea bateriilor uzate, inclusiv bateriilor de pornire, de tracțiune și staționare cu plumb-acid. De asemenea, compania se ocupă de plumb, baterii deteriorate și componente individuale ale bateriilor. || Compania transformă deșeurile periculoase în materii prime secundare valoroase. Acest lucru permite nu numai eliminarea în siguranță a bateriilor uzate, ci și returnarea materialelor în ciclul de producție. || În timpul procesului de reciclare, plumbul și aliajele de plumb sunt recuperate pentru producerea de baterii noi, carcasele din plastic sunt mărunțite și refolosite, iar electroliții sunt neutralizați pentru aplicații industriale ulterioare. Metalele neferoase, inclusiv cuprul, nichelul și cadmiul, sunt, de asemenea, recuperate și returnate în fluxurile de reciclare. || Impactul asupra mediului constă în prevenirea contaminării solului și a apei de către substanțele toxice. Se estimează că o singură baterie poate polua aproximativ 20 m² de sol sau 400 de litri de apă, ceea ce face ca reciclarea adecvată să fie extrem de importantă pentru protecția mediului. În plus, reciclarea reduce nevoia de extragere a resurselor virgine și scade amprenta de carbon. || Impactul economic include recuperarea a 95-99% din materiale valoroase din bateriile plumb-acid, reducerea costurilor cu materiile prime pentru producătorii de baterii noi și alte produse industriale.",hy:"Util-akb-ն մասնագիտացած է օգտագործված մարտկոցների հավաքման և վերամշակման մեջ, ներառյալ մեկնարկային, ձգողական և անշարժ կապարաթթվային մարտկոցները: Ընկերությունը նաև զբաղվում է կապարով, վնասված մարտկոցներով և մարտկոցի առանձին բաղադրիչներով։ || Ընկերությունը վտանգավոր թափոնները վերածում է արժեքավոր երկրորդական հումքի: Սա թույլ է տալիս ոչ միայն օգտագործված մարտկոցների անվտանգ հեռացումը, այլև նյութերի վերադարձը արտադրության ցիկլ։ || Վերամշակման գործընթացում կապարի և կապարի համաձուլվածքները վերականգնվում են նոր մարտկոցների արտադրության համար, պլաստիկ պատյանները մանրացվում և նորից օգտագործվում են, իսկ էլեկտրոլիտները չեզոքացվում են հետագա արդյունաբերական կիրառման համար: Գունավոր մետաղները, ներառյալ պղինձը, նիկելը և կադմիումը, նույնպես վերականգնվում և վերադարձվում են վերամշակման հոսքերին։ || Շրջակա միջավայրի վրա ազդեցությունը կայանում է նրանում, որ թունավոր նյութերը հողն ու ջուրը աղտոտեն: Ենթադրվում է, որ մեկ մարտկոցը կարող է աղտոտել մոտ 20 մ² հող կամ 400 լիտր ջուր, ինչը շատ կարևոր է դարձնում պատշաճ վերամշակումը շրջակա միջավայրի պաշտպանության համար: Բացի այդ, վերամշակումը նվազեցնում է կուսական ռեսուրսների արդյունահանման անհրաժեշտությունը և նվազեցնում ածխածնի հետքը։ || Տնտեսական ազդեցությունը ներառում է կապարաթթվային մարտկոցներից արժեքավոր նյութերի 95-99%-ի վերականգնում, նվազեցնելով հումքի ծախսերը նոր մարտկոցների և այլ արդյունաբերական արտադրանքների արտադրողների համար։:"},caseLink:"https://util-akb.com.ua/",image:"/images/cases/ukraine/util-akb.jpg",imageAlt:{en:"Util-akb case image",uk:"Зображення корпусу Util-akb",ro:"Imaginea cazului Util-akb",hy:"Util-akb գործի պատկեր"}}),e({id:"case-051",slug:"stabil-plastic",companyName:{en:"Stabil Plastic",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Plastics"],rStrategies:["Recycle (R8)"],rStrategyDescription:{en:"Polyethylene, polypropylene and other polymer waste streams are processed and returned to the production cycle as the base material for new construction, technical and landscaping products.",uk:"Відходи поліетилену, поліпропілену та інших полімерів піддають обробленню та повертають у виробничий цикл як основну сировину для виготовлення нової будівельної, технічної продукції та елементів благоустрою.",ro:"Polietilena, polipropilena și alte fluxuri de deșeuri polimerice sunt procesate și returnate în ciclul de producție ca material de bază pentru noi produse de construcții, tehnice și de amenajare a teritoriului.",hy:"Պոլիէթիլենային, պոլիպրոպիլենային և այլ պոլիմերային թափոնների հոսքերը վերամշակվում և վերադարձվում են արտադրական ցիկլ՝ որպես նոր շինարարական, տեխնիկական և կանաչապատման արտադրանքի հիմնական նյութ։:"},summary:{en:"Stabil Plastic manufactures construction and technical products from recycled polymer raw materials, returning plastic waste to the production cycle and reducing reliance on virgin petrochemical polymers.",uk:"Stabil Plastic виготовляє будівельні та технічні вироби з вторинної полімерної сировини, повертаючи пластикові відходи у виробничий цикл і зменшуючи залежність від первинних нафтохімічних полімерів.",ro:"Stabil Plastic produce produse de construcții și tehnice din materii prime polimerice reciclate, returnând deșeurile de plastic în ciclul de producție și reducând dependența de polimerii petrochimici virgini.",hy:"Stabil Plastic-ը շինարարական և տեխնիկական արտադրանք է արտադրում վերամշակված պոլիմերային հումքից՝ պլաստիկ թափոնները վերադարձնելով արտադրական ցիկլ և նվազեցնելով կուսական նավթաքիմիական պոլիմերներից կախվածությունը։"},description:{en:"Stabil Plastic is a Ukrainian company specializing in plastic waste recycling and the production of finished goods from recycled polymer raw materials. The company manufactures construction and technical components, polymer profiles, landscaping elements, and other industrial products. || The company returns plastic waste into the production cycle as a valuable raw material, helping reduce dependence on virgin petrochemical-based polymers. || Its operations apply approaches such as plastic waste recycling, manufacturing new products from secondary raw materials, replacing virgin polymers, and extending the lifecycle of materials. The company works with polyethylene, polypropylene, and other types of polymer waste, which, after processing, become the basis for new products. || The environmental impact includes reducing landfill waste volumes, lowering environmental pollution, and decreasing demand for petroleum-based raw materials. The use of recycled plastic can reduce emissions by 1-2 kg CO₂e per kilogram of material. If the company processes 1,000 tonnes of plastic annually, the potential reduction may amount to 1,000-2,000 tonnes of CO₂e each year. || The economic impact includes lower raw material costs, the creation of high value-added products, and the development of a local secondary materials market. In addition, polymer recycling requires 30-80% less energy than the production of virgin plastic.",uk:"Stabil Plastic – українська компанія, що спеціалізується на переробленні пластикових відходів і виробництві готової продукції з переробленої полімерної сировини. Компанія виробляє будівельні та технічні компоненти, полімерні профілі, елементи благоустрою та іншу промислову продукцію. || Компанія повертає пластикові відходи у виробничий цикл як цінну сировину, допомагаючи зменшити залежність від первинних полімерів нафтохімічного походження. || У своїй діяльності компанія застосовує такі підходи, як перероблення пластикових відходів, виробництво нової продукції з вторинної сировини, заміна первинних полімерів та продовження життєвого циклу матеріалів. Компанія працює з поліетиленом, поліпропіленом та іншими видами полімерних відходів, які після оброблення стають основою для нової продукції. || Екологічні переваги – зменшення обсягів відходів, що потрапляють на полігони, зниження забруднення довкілля та скорочення потреби в сировині нафтового походження. Використання переробленого пластику може зменшити викиди на 1-2 кг CO₂-екв. на кожен кілограм матеріалу. Якщо компанія щороку переробляє 1 тис. тонн пластику, потенційне скорочення викидів може становити 1-2 тис. тонн CO₂-екв. на рік. || Економічні переваги – зниження витрат на сировину, виробництво продукції з високою доданою вартістю та розвиток локального ринку вторинних матеріалів. Крім того, перероблення полімерів потребує на 30-80% менше енергії, ніж виробництво первинного пластику.",ro:"Stabil Plastic este o companie ucraineană specializată în reciclarea deșeurilor de plastic și producția de produse finite din materii prime polimerice reciclate. Compania produce componente tehnice și de construcții, profile polimerice, elemente de amenajare și alte produse industriale. || Compania returnează deșeurile de plastic în ciclul de producție ca materie primă valoroasă, contribuind la reducerea dependenței de polimerii virgini pe bază de petrochimie. || Operațiunile sale aplică abordări precum reciclarea deșeurilor de plastic, fabricarea de noi produse din materii prime secundare, înlocuirea polimerilor virgini și extinderea ciclului de viață al materialelor. Compania lucrează cu polietilenă, polipropilenă și alte tipuri de deșeuri polimerice, care, după procesare, devin baza pentru noi produse. || Impactul asupra mediului include reducerea volumelor de deșeuri din depozitele de gunoi, reducerea poluării mediului și scăderea cererii de materii prime pe bază de petrol. Utilizarea plasticului reciclat poate reduce emisiile cu 1-2 kg CO₂e per kilogram de material. Dacă compania prelucrează 1.000 de tone de plastic anual, potențiala reducere poate ajunge la 1.000-2.000 de tone de CO₂e în fiecare an. || Impactul economic include costuri mai mici ale materiilor prime, crearea de produse cu valoare adăugată mare și dezvoltarea unei piețe locale de materiale secundare. În plus, reciclarea polimerilor necesită cu 30-80% mai puțină energie decât producția de plastic virgin.",hy:"Stabil Plastic-ը ուկրաինական ընկերություն է, որը մասնագիտացած է պլաստիկ թափոնների վերամշակման և վերամշակված պոլիմերային հումքից պատրաստի արտադրանքի արտադրության մեջ: Ընկերությունն արտադրում է շինարարական և տեխնիկական բաղադրիչներ, պոլիմերային պրոֆիլներ, կանաչապատման տարրեր և այլ արդյունաբերական արտադրանք։ || Ընկերությունը պլաստիկ թափոնները վերադարձնում է արտադրական ցիկլ՝ որպես արժեքավոր հումք՝ օգնելով նվազեցնել կախվածությունը նավթաքիմիական հիմքով պոլիմերներից։ || Նրա գործառնություններում կիրառվում են այնպիսի մոտեցումներ, ինչպիսիք են պլաստիկ թափոնների վերամշակումը, երկրորդային հումքից նոր արտադրանքի արտադրությունը, կուսական պոլիմերների փոխարինումը և նյութերի կյանքի ցիկլի երկարացումը: Ընկերությունն աշխատում է պոլիէթիլենով, պոլիպրոպիլենով և այլ տեսակի պոլիմերային թափոններով, որոնք մշակելուց հետո հիմք են դառնում նոր արտադրանքի համար։ || Շրջակա միջավայրի վրա ազդեցությունը ներառում է աղբավայրերի թափոնների ծավալների կրճատում, շրջակա միջավայրի աղտոտվածության նվազեցում և նավթի վրա հիմնված հումքի պահանջարկի նվազում: Վերամշակված պլաստիկի օգտագործումը կարող է նվազեցնել արտանետումները 1-2 կգ CO₂e մեկ կիլոգրամ նյութի համար: Եթե ընկերությունը տարեկան մշակում է 1000 տոննա պլաստմասսա, ապա հնարավոր կրճատումը կարող է կազմել տարեկան 1000-2000 տոննա CO₂e։ || Տնտեսական ազդեցությունը ներառում է հումքի ավելի ցածր ծախսեր, բարձր ավելացված արժեքով արտադրանքի ստեղծում և տեղական երկրորդական նյութերի շուկայի զարգացում: Բացի այդ, պոլիմերների վերամշակումը պահանջում է 30-80%-ով ավելի քիչ էներգիա, քան մաքուր պլաստիկի արտադրությունը։"},caseLink:"https://www.stabilplastik.com.ua/",image:"/images/cases/ukraine/stabil-plastic.jpg",imageAlt:{en:"Stabil Plastic case image",uk:"Зображення пластикового корпусу Stabil",ro:"Imaginea carcasei din plastic stabil",hy:"Stabil Plastic պատյանի պատկեր"}}),e({id:"case-052",slug:"kuziv-craft",companyName:{en:"Kuziv Craft",uk:"",ro:"",hy:""},country:"Ukraine",sector:["Textiles"],rStrategies:["Repurpose (R7)"],rStrategyDescription:{en:"Post-consumer denim, sourced from second-hand stores or individuals, is manually cut, sewn and finished into a different product category (bags) rather than being recycled back into raw fiber.",uk:"Джинсовий одяг, який уже був у користуванні та надходить із магазинів секонд-хенду або від окремих людей, вручну розкроюють, зшивають і оздоблюють, перетворюючи його на продукцію іншої категорії – сумки – замість перероблення назад у текстильне волокно.",ro:"Denimul post-consum, provenit din magazine second-hand sau persoane fizice, este tăiat, cusut și finisat manual într-o categorie de produse diferită (pungi), în loc să fie reciclat înapoi în fibră brută.",hy:"Հետսպառողական ջինսը, որը ստացվել է օգտագործված խանութներից կամ անհատներից, ձեռքով կտրվում, կարվում և ավարտվում է ապրանքի այլ կատեգորիայի (տոպրակների) մեջ, այլ ոչ թե վերամշակվում է հում մանրաթելերի մեջ։"},summary:{en:"Kuziv Craft is an artisan brand that upcycles discarded denim garments into handmade designer bags, giving used textiles a new function and reducing demand for virgin textile materials.",uk:"Kuziv Craft – крафтовий бренд, який перетворює відпрацьований джинсовий одяг на дизайнерські сумки ручної роботи (апсайклінг), надаючи вживаному текстилю нове призначення та зменшуючи попит на первинні текстильні матеріали.",ro:"Kuziv Craft este un brand artizanal care reciclează articolele de îmbrăcăminte din denim aruncate în genți de designer realizate manual, oferind textilelor uzate o nouă funcție și reducând cererea de materiale textile virgine.",hy:"Kuziv Craft-ը արհեստավոր ապրանքանիշ է, որը վերափոխում է ջինսե հագուստները ձեռագործ դիզայներական պայուսակների մեջ՝ օգտագործված տեքստիլներին տալով նոր գործառույթ և նվազեցնելով կուսական տեքստիլ նյութերի պահանջարկը։"},description:{en:"Kuziv Craft is a Ukrainian artisan brand specializing in the production of handmade bags created from discarded denim garments. The company transforms used jeans into unique fashion accessories through a craft-based upcycling process. Most products are manufactured on demand, while post-consumer denim is sourced from second-hand stores or collected from individuals. || The company operates on the principle of extending the useful life of textile materials by giving discarded garments a new function instead of allowing them to become waste. Through creative redesign, denim is transformed into durable bags with a higher functional and aesthetic value, reducing the need for virgin textile materials. || The production process includes the collection and selection of used jeans, cleaning, disassembly, manual cutting, sewing, and finishing. Each product is individually handcrafted, allowing the company to maximize the value of existing textile resources while minimizing production waste. The made-to-order approach also helps avoid overproduction and unnecessary inventory. || The environmental benefits include reducing textile waste generation, extending the lifetime of textile materials, and decreasing the consumption of virgin fabrics. By reusing existing denim instead of producing new textile materials, the company contributes to lower resource consumption and supports more sustainable production and consumption patterns. || The economic benefits include creating value-added products from low-cost secondary materials, supporting local craft production, and developing a market for sustainable fashion products. The business also demonstrates how small enterprises can successfully combine environmental responsibility with unique product design and customer-oriented manufacturing.",uk:"Kuziv Craft – український крафтовий бренд, що спеціалізується на виробництві сумок ручної роботи з непотрібного джинсового одягу. Компанія перетворює використані джинси на унікальні модні аксесуари завдяки крафтовому процесу апсайклінгу. Більшість виробів виготовляється на замовлення, а джинсовий одяг, який уже був у користуванні, надходить із магазинів секонд-хенду або збирається від окремих людей. || Компанія дотримується принципу продовження терміну корисного використання текстильних матеріалів, надаючи непотрібному одягу нове призначення замість того, щоб він ставав відходами. Завдяки творчому переосмисленню джинсовий матеріал перетворюється на міцні сумки з вищою функціональною та естетичною цінністю, що зменшує потребу в первинних текстильних матеріалах. || Процес виробництва охоплює збирання та відбір використаних джинсів, очищення, розбирання, ручний розкрій, пошиття та оздоблення. Кожен виріб виготовляється вручну, що дає змогу максимально використовувати наявні текстильні ресурси та мінімізувати виробничі відходи. Виготовлення на замовлення також допомагає уникати виробництва зайвої продукції та накопичення непотрібних запасів. || Екологічні переваги – зменшення утворення текстильних відходів, продовження терміну використання текстильних матеріалів та скорочення споживання первинних тканин. Повторне використання наявного джинсового матеріалу замість виробництва нових текстильних матеріалів дає змогу заощаджувати ресурси та підтримує більш сталі моделі виробництва і споживання. || Економічні переваги – створення продукції з високою доданою вартістю з недорогих вторинних матеріалів, підтримка місцевого крафтового виробництва та розвиток ринку сталої моди. Цей бізнес також демонструє, як малі підприємства можуть поєднувати екологічну відповідальність з унікальним дизайном продукції та виробництвом, орієнтованим на потреби клієнтів.",ro:"Kuziv Craft este un brand artizanal ucrainean specializat în producția de genți lucrate manual, create din articole de îmbrăcăminte din denim aruncate. Compania transformă blugii uzați în accesorii de modă unice printr-un proces de upcycling bazat pe artizanat. Majoritatea produselor sunt fabricate la cerere, în timp ce denimul post-consum este obținut din magazinele second-hand sau colectat de la persoane fizice. || Compania funcționează pe principiul prelungirii duratei de viață utilă a materialelor textile, oferind articolelor de îmbrăcăminte aruncate o nouă funcție, în loc să le permită să devină deșeuri. Prin redesign creativ, denimul este transformat în genți durabile, cu o valoare funcțională și estetică mai mare, reducând nevoia de materiale textile virgine. || Procesul de producție include colectarea și selecția blugilor uzați, curățarea, dezasamblarea, tăierea manuală, cusutul și finisarea. Fiecare produs este realizat manual individual, permițând companiei să maximizeze valoarea resurselor textile existente minimizând în același timp risipa de producție. Abordarea făcută la comandă ajută, de asemenea, la evitarea supraproducției și a stocurilor inutile. || Beneficiile de mediu includ reducerea generării de deșeuri textile, prelungirea duratei de viață a materialelor textile și scăderea consumului de țesături virgine. Prin reutilizarea denimului existent în loc să producă noi materiale textile, compania contribuie la un consum mai mic de resurse și susține modele de producție și consum mai durabile. || Beneficiile economice includ crearea de produse cu valoare adăugată din materiale secundare ieftine, sprijinirea producției artizanale locale și dezvoltarea unei piețe pentru produse de modă durabile. Afacerea demonstrează, de asemenea, modul în care întreprinderile mici pot combina cu succes responsabilitatea de mediu cu designul unic al produsului și producția orientată către client.",hy:"Kuziv Craft-ը ուկրաինական արհեստավոր ապրանքանիշ է, որը մասնագիտացած է ձեռագործ պայուսակների արտադրության մեջ, որոնք ստեղծվել են դենիմից հանված հագուստից: Ընկերությունն օգտագործված ջինսերը վերածում է յուրօրինակ նորաձևության աքսեսուարների՝ արհեստագործական վերամշակման գործընթացի միջոցով: Ապրանքների մեծ մասն արտադրվում է ըստ պահանջարկի, մինչդեռ հետսպառողական ջինսերը ձեռք են բերվում օգտագործված խանութներից կամ հավաքվում են անհատներից։ || Ընկերությունը գործում է մանածագործական նյութերի օգտակար ծառայության ժամկետը երկարացնելու սկզբունքով՝ թափված հագուստին տալով նոր գործառույթ՝ դրանք թափոն դառնալու փոխարեն: Կրեատիվ վերադիզայնի միջոցով ջինսը վերածվում է երկարակյաց պայուսակների՝ ավելի բարձր գործունակ և էսթետիկ արժեքով, նվազեցնելով տեքստիլ նյութերի կարիքը։ || Արտադրության գործընթացը ներառում է օգտագործված ջինսերի հավաքում և ընտրություն, մաքրում, ապամոնտաժում, ձեռքով կտրում, կարում և հարդարում: Յուրաքանչյուր ապրանք պատրաստված է անհատապես, ինչը թույլ է տալիս ընկերությանը առավելագույնի հասցնել առկա տեքստիլ ռեսուրսների արժեքը՝ նվազագույնի հասցնելով արտադրական թափոնները: Պատվերով մոտեցումը նաև օգնում է խուսափել գերարտադրությունից և ավելորդ գույքագրումից։|| Բնապահպանական օգուտները ներառում են տեքստիլ թափոնների արտադրության կրճատում, տեքստիլ նյութերի շահագործման ժամկետի երկարացում և կուսական գործվածքների սպառման նվազում: Նոր մանածագործական նյութեր արտադրելու փոխարեն գոյություն ունեցող ջինսերը վերօգտագործելով՝ ընկերությունը նպաստում է ռեսուրսների սպառման նվազեցմանը և աջակցում է արտադրության և սպառման ավելի կայուն մոդելներին։ || Տնտեսական օգուտները ներառում են էժան երկրորդական նյութերից ավելացված արժեքի արտադրանքի ստեղծումը, տեղական արհեստագործական արտադրությանն աջակցելը և կայուն նորաձևության արտադրանքի շուկայի զարգացումը: Բիզնեսը նաև ցույց է տալիս, թե ինչպես փոքր ձեռնարկությունները կարող են հաջողությամբ համատեղել բնապահպանական պատասխանատվությունը եզակի արտադրանքի դիզայնի և հաճախորդների վրա հիմնված արտադրության հետ։"},caseLink:"https://instagram.com/kuziv.craft",image:"/images/cases/ukraine/kuziv-craft.jpg",imageAlt:{en:"Kuziv Craft case image",uk:"Зображення футляра Kuziv Craft",ro:"Imaginea cazului Kuziv Craft",hy:"Kuziv Craft գործի պատկեր"}})],h=[...new Set(o.flatMap(a=>{var i;return((i=a.filterValues)==null?void 0:i.sectors)??[]}))].sort(),f=[...new Set(o.flatMap(a=>{var i;return((i=a.filterValues)==null?void 0:i.countries)??[]}))].sort(),v=[...new Set(o.flatMap(a=>{var i;return((i=a.filterValues)==null?void 0:i.rStrategies)??[]}))].sort(d);export{v as a,h as b,f as c,o as d};
